function CloudProviderLogo({ provider }: { provider: CloudProvider }) {
  if (provider === 'pve') {
    return (
      <span className="cloud-provider-logo cloud-provider-logo-pve" aria-label="Proxmox Virtual Environment logo" role="img">
        <svg viewBox="0 0 150 56" aria-hidden="true" focusable="false">
          <rect x="3" y="7" width="144" height="42" rx="9" fill="#ffffff" />
          <path d="M20 18h22l-9 20H11l9-20Z" fill="#e57000" />
          <path d="M48 18h22l-9 20H39l9-20Z" fill="#52525b" />
          <path d="M76 18h22l-9 20H67l9-20Z" fill="#e57000" />
          <text x="106" y="28" fill="#1f2937" fontSize="11" fontWeight="800" textAnchor="middle">PROXMOX</text>
          <text x="106" y="40" fill="#e57000" fontSize="12" fontWeight="900" textAnchor="middle">VE</text>
        </svg>
      </span>
    );
  }

  if (provider === 'oci') {
    return (
      <span className="cloud-provider-logo cloud-provider-logo-oci" aria-label="Oracle Cloud Infrastructure logo" role="img">
        <svg viewBox="0 0 150 56" aria-hidden="true" focusable="false">
          <rect x="5" y="9" width="140" height="38" rx="19" fill="#c74634" />
          <text x="75" y="31" fill="#ffffff" fontSize="20" fontWeight="900" textAnchor="middle">ORACLE</text>
          <text x="75" y="42" fill="#fee2e2" fontSize="9" fontWeight="800" textAnchor="middle">CLOUD INFRASTRUCTURE</text>
        </svg>
      </span>
    );
  }

  if (provider === 'aws') {
    return (
      <span className="cloud-provider-logo cloud-provider-logo-aws" aria-label="Amazon Web Services logo" role="img">
        <svg viewBox="0 0 150 56" aria-hidden="true" focusable="false">
          <rect x="5" y="7" width="140" height="42" rx="9" fill="#232f3e" />
          <text x="74" y="32" fill="#ffffff" fontSize="25" fontWeight="900" textAnchor="middle">aws</text>
          <path d="M48 39c18 9 42 9 61-2" fill="none" stroke="#ff9900" strokeWidth="5" strokeLinecap="round" />
          <path d="M109 37l8-2-4 8" fill="none" stroke="#ff9900" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </span>
    );
  }

  if (provider === 'gcp') {
    return (
      <span className="cloud-provider-logo cloud-provider-logo-gcp" aria-label="Google Cloud logo" role="img">
        <svg viewBox="0 0 96 64" aria-hidden="true">
          <path d="M59.2 18.9h3.1l8.9-8.9.4-3.8C65.1 2 57.3 0 48.9 0 34.2 0 21.7 8.4 15.6 20.7c1 .1 2 .4 2.9.8l17.9-2.9s.9-1.5 1.4-1.4c2.8-3.1 6.8-5 11.1-5 4.1 0 7.8 1.6 10.3 4.5v2.2Z" fill="#ea4335" />
          <path d="M82 20.7c-2.1-7.7-6.8-14.2-13.1-18.4l-12.4 12.4c4.3 1.1 7.9 4 9.9 7.9v2.2c6.1 0 11 4.9 11 11s-4.9 11-11 11H48.6l-2.2 2.3v13.2l2.2 2.2h17.8c15.6 0 28.2-12.6 28.2-28.2 0-9.1-4.3-17.2-11-22.4l-1.6.8Z" fill="#4285f4" />
          <path d="M30.7 64.4h17.9V46.7H30.7c-1.3 0-2.6-.3-3.7-.8l-3.1 1-9 8.9-.8 3C18.7 62.3 24.5 64.4 30.7 64.4Z" fill="#34a853" />
          <path d="M30.7 7.8C15 7.8 2.4 20.4 2.4 36.1c0 9.8 5 18.4 12.5 23.5l12.8-12.8c-4.6-1.2-8-5.5-8-10.6 0-6.1 4.9-11 11-11 4.5 0 8.3 2.6 10.1 6.4l12.8-12.8C48.5 12.1 40.1 7.8 30.7 7.8Z" fill="#fbbc05" />
        </svg>
      </span>
    );
  }

  return (
    <span className="cloud-provider-logo cloud-provider-logo-azure" aria-label="Microsoft Azure logo" role="img">
      <svg viewBox="0 0 150 56" aria-hidden="true" focusable="false">
        <rect x="5" y="7" width="140" height="42" rx="9" fill="#ffffff" />
        <path d="M50 12 22 38h25l-8 14 36-23H53l16-17H50Z" fill="#0078d4" />
        <path d="M76 16h46v9H76zM76 30h46v9H76z" fill="#2563eb" />
        <text x="99" y="49" fill="#1d4ed8" fontSize="10" fontWeight="900" textAnchor="middle">AZURE</text>
      </svg>
    </span>
  );
}

function azureResourceGroupFrom(resource?: Partial<Pick<AzureResource, 'id' | 'resourceGroup' | 'storageAccountId'>> | null) {
  if (!resource) {
    return '';
  }
  if (resource.resourceGroup) {
    return String(resource.resourceGroup);
  }
  const match = String(resource.storageAccountId || resource.id || '').match(/\/resourceGroups\/([^/]+)/i);
  return match ? decodeURIComponent(match[1]) : '';
}

