function defaultNetworkName(type: NetworkConfigType, interfaces: NetworkInterface[]) {
  const prefix = type === 'bond' || type === 'OVSBond' ? 'bond' : type === 'vlan' ? 'vlan' : type === 'OVSIntPort' ? 'int' : 'vmbr';
  const existingNumbers = interfaces
    .map((item) => new RegExp(`^${prefix}(\\d+)$`).exec(item.iface)?.[1])
    .filter(Boolean)
    .map((value) => Number(value));
  const nextNumber = existingNumbers.length ? Math.max(...existingNumbers) + 1 : type === 'bridge' || type === 'OVSBridge' ? 1 : 0;
  return `${prefix}${nextNumber}`;
}

function selectedOptionValues(options: HTMLCollectionOf<HTMLOptionElement>) {
  return Array.from(options)
    .filter((option) => option.selected)
    .map((option) => option.value)
    .filter((value) => value !== 'none' && value !== '__none')
    .join(' ');
}

function networkInterfaceToForm(item: NetworkInterface): NetworkConfigInput {
  return {
    ...emptyNetworkForm,
    iface: item.iface,
    type: networkTypeOptions.some((option) => option.value === item.type) ? item.type as NetworkConfigType : 'bridge',
    autostart: item.autostart,
    method: item.method === 'static' ? 'static' : 'manual',
    address: item.address || '',
    netmask: item.netmask || '',
    gateway: item.gateway || '',
    bridgePorts: item.bridgePorts || 'none',
    slaves: item.slaves || '',
    bondMode: item.bondMode || 'balance-rr',
    vlanId: String(item.vlanId || ''),
    vlanRawDevice: item.vlanRawDevice || '',
    ovsBridge: item.ovsBridge || '',
    ovsBonds: item.ovsBonds || '',
    ovsPorts: item.ovsPorts || '',
    ovsOptions: item.ovsOptions || '',
    ovsTag: String(item.ovsTag || ''),
    mtu: String(item.mtu || ''),
    vlanAware: item.vlanAware,
    comments: item.comments || '',
  };
}

