function formatDate(value: string | null) {
  if (!value) {
    return 'Not checked yet';
  }
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(value));
}

function stripAnsiCodes(value: string) {
  return value.replace(/\u001b\[[0-9;?]*[ -/]*[@-~]/g, '');
}

function terraformRunStatusClass(status: string) {
  const normalized = status.toLowerCase();
  if (normalized === 'failed') {
    return 'bg-red-100 text-red-800';
  }
  if (normalized === 'succeeded') {
    return 'bg-emerald-100 text-emerald-800';
  }
  if (normalized === 'running') {
    return 'bg-cyan-100 text-cyan-800';
  }
  return 'bg-slate-100 text-slate-700';
}

function formatDuration(startedAt: string | null, finishedAt: string | null) {
  if (!startedAt) {
    return '-';
  }
  const start = new Date(startedAt).getTime();
  const end = finishedAt ? new Date(finishedAt).getTime() : Date.now();
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) {
    return '-';
  }
  const totalSeconds = Math.round((end - start) / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return minutes > 0 ? `${minutes}m ${seconds}s` : `${seconds}s`;
}

function formatRelativeAge(value?: string | null) {
  if (!value) {
    return 'not scanned yet';
  }
  const timestamp = new Date(value).getTime();
  if (!Number.isFinite(timestamp)) {
    return 'not scanned yet';
  }
  const elapsedMs = Date.now() - timestamp;
  const absoluteMs = Math.abs(elapsedMs);
  if (absoluteMs < 60_000) {
    return 'just now';
  }
  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ['year', 31_536_000_000],
    ['month', 2_592_000_000],
    ['day', 86_400_000],
    ['hour', 3_600_000],
    ['minute', 60_000],
  ];
  const formatter = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
  const [unit, unitMs] = units.find(([, candidateMs]) => absoluteMs >= candidateMs) || ['minute', 60_000];
  return formatter.format(Math.round(-elapsedMs / unitMs), unit);
}

function daysSince(value?: string) {
  if (!value) {
    return null;
  }
  const timestamp = new Date(value).getTime();
  if (!Number.isFinite(timestamp)) {
    return null;
  }
  return Math.max(0, Math.floor((Date.now() - timestamp) / 86_400_000));
}

function sizeGbFor(row: ResourceRecord | ociService.OciVolumeBackup) {
  const value = 'storageSizeGb' in row && row.storageSizeGb !== undefined ? row.storageSizeGb : row.sizeGb;
  const size = Number(value || 0);
  return Number.isFinite(size) ? size : 0;
}

