function formatStorageGb(value: number) {
  if (!Number.isFinite(value) || value <= 0) {
    return '0 GB';
  }
  if (value >= 1024) {
    return `${(value / 1024).toFixed(1)} TB`;
  }
  return `${Math.round(value).toLocaleString()} GB`;
}

