function MetricDonut({ label, value, detail }: { label: string; value: number; detail: string }) {
  const safeValue = Math.max(0, Math.min(100, Math.round(value)));
  const meterTone = safeValue >= 90 ? '#dc2626' : safeValue >= 75 ? '#f59e0b' : '#0891b2';
  return (
    <section className="metric-card">
      <header className="metric-card-header">
        <h3>{label}</h3>
        <span>ⓘ</span>
      </header>
      <div className="flex items-center gap-5 p-4">
        <div
          aria-label={`${label} ${safeValue}%`}
          className="grid h-28 w-28 shrink-0 place-items-center rounded-full"
          style={{ background: `conic-gradient(${meterTone} ${safeValue * 3.6}deg, #e2e8f0 0deg)` }}
        >
          <div className="grid h-20 w-20 place-items-center rounded-full bg-white text-center">
            <div>
              <p className="text-lg font-semibold text-slate-950">{safeValue}%</p>
              <p className="text-xs text-slate-500">{detail}</p>
            </div>
          </div>
        </div>
        <div className="min-w-0 flex-1 rounded-xl border border-cyan-100 bg-cyan-50 p-3">
          <p className="text-xs font-semibold uppercase tracking-wide text-cyan-700">Current load</p>
          <div className="mt-3 h-2.5 overflow-hidden rounded-full bg-slate-200">
            <div className="h-full rounded-full" style={{ width: `${safeValue}%`, backgroundColor: meterTone }} />
          </div>
          <p className="mt-3 text-xl font-semibold text-cyan-950">{safeValue}%</p>
        </div>
      </div>
    </section>
  );
}

function StorageConsumption({ used, total }: { used: number; total: number }) {
  const safeTotal = total > 0 ? total : 0;
  const safeUsed = Math.max(0, used);
  const percentUsed = safeTotal ? Math.min(100, Math.round((safeUsed / safeTotal) * 100)) : 0;
  const available = Math.max(0, safeTotal - safeUsed);

  return (
    <section className="metric-card xl:col-span-2">
      <header className="metric-card-header">
        <h3>Storage usage</h3>
        <span>ⓘ</span>
      </header>
      <div className="p-5">
        <div className="h-4 w-full overflow-hidden rounded-full bg-slate-200 shadow-inner">
          <div className="h-full rounded-full bg-gradient-to-r from-cyan-500 via-emerald-500 to-amber-400" style={{ width: `${percentUsed}%` }} />
        </div>
        <div className="mt-5 grid gap-4 sm:grid-cols-3">
          <div className="rounded-xl border border-cyan-100 bg-cyan-50 p-3">
            <p className="text-xs text-slate-600">Used</p>
            <p className="text-xl font-semibold text-cyan-950">{formatBytes(safeUsed)}</p>
          </div>
          <div className="rounded-xl border border-emerald-100 bg-emerald-50 p-3">
            <p className="text-xs text-slate-600">Available</p>
            <p className="text-xl font-semibold text-emerald-950">{formatBytes(available)}</p>
          </div>
          <div className="rounded-xl border border-indigo-100 bg-indigo-50 p-3 text-left sm:text-right">
            <p className="text-xs text-slate-600">Total size</p>
            <p className="text-xl font-semibold text-indigo-950">{formatBytes(safeTotal)}</p>
          </div>
        </div>
      </div>
    </section>
  );
}

function canRunAction(resource: ResourceRecord, action: ResourceAction, type: 'qemu' | 'lxc') {
  if (action === 'suspend' && type !== 'qemu') {
    return false;
  }
  if (action === 'start') {
    return resource.status !== 'running';
  }
  return resource.status === 'running';
}

function actionLabel(action: ResourceAction) {
  return action.charAt(0).toUpperCase() + action.slice(1);
}

function resourceKey(type: 'qemu' | 'lxc', resource: ResourceRecord) {
  return `${type}-${resource.node || 'node'}-${resource.vmid || 'unknown'}`;
}

function formatMib(value: unknown) {
  const numeric = Number(value || 0);
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return '-';
  }
  if (numeric >= 1024 * 1024) {
    return String(Math.round(numeric / 1024 / 1024));
  }
  return String(Math.round(numeric));
}

function normalizeUsagePercent(value: unknown) {
  const numeric = Number(value || 0);
  if (!Number.isFinite(numeric) || numeric < 0) {
    return null;
  }
  const percent = numeric <= 1 ? numeric * 100 : numeric;
  return Math.min(100, Math.max(0, Math.round(percent)));
}

function formatUptime(value: unknown) {
  const totalSeconds = Math.floor(Number(value || 0));
  if (!Number.isFinite(totalSeconds) || totalSeconds <= 0) {
    return '-';
  }
  const days = Math.floor(totalSeconds / 86400);
  const hours = Math.floor((totalSeconds % 86400) / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const padded = [hours, minutes, seconds].map((part) => String(part).padStart(2, '0')).join(':');
  return days > 0 ? `${days}d ${padded}` : padded;
}

function formatLogDate(value: string | null) {
  if (!value) {
    return '-';
  }
  return new Intl.DateTimeFormat(undefined, {
    month: 'short',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  }).format(new Date(value));
}

function taskStatusClass(task: ProxmoxTask) {
  if (!task.endedAt || task.status === 'running') {
    return 'bg-cyan-100 text-cyan-800';
  }
  if (task.exitstatus === 'OK' || task.status === 'OK') {
    return 'bg-emerald-100 text-emerald-800';
  }
  return 'bg-red-100 text-red-800';
}

function isTaskRunning(task: ProxmoxTask | null) {
  if (!task) {
    return false;
  }
  if (task.status === 'stopped' || task.exitstatus || task.endedAt) {
    return false;
  }
  return task.status === 'running' || !task.status;
}

function isTaskFailed(task: ProxmoxTask) {
  return Boolean(task.endedAt) && Boolean(task.exitstatus) && task.exitstatus !== 'OK';
}

function isTaskCompleted(task: ProxmoxTask) {
  return Boolean(task.endedAt) && (!task.exitstatus || task.exitstatus === 'OK');
}

function isTaskCancelable(task: ProxmoxTask) {
  return task.cancelable !== false && isTaskRunning(task) && Boolean(task.node && task.upid);
}

function isTaskRetryable(task: ProxmoxTask) {
  return isTaskFailed(task) && Boolean(task.retryable && task.node && task.upid);
}

function buildOciCompartmentTree(compartments: OciCompartment[], rootCompartmentId = '') {
  const byParent = new Map<string, OciCompartment[]>();
  const byId = new Map(compartments.map((compartment) => [compartment.id, compartment]));

  compartments.forEach((compartment) => {
    const parentId = compartment.parentCompartmentId || '';
    const key = byId.has(parentId) ? parentId : '';
    byParent.set(key, [...(byParent.get(key) || []), compartment]);
  });

  const rows: OciCompartmentTreeItem[] = [];
  const visited = new Set<string>();
  const sortCompartments = (items: OciCompartment[]) =>
    [...items].sort((left, right) => left.name.localeCompare(right.name, undefined, { sensitivity: 'base' }));

  function walk(parentId: string, depth: number, ancestors: string[] = []) {
    for (const compartment of sortCompartments(byParent.get(parentId) || [])) {
      if (visited.has(compartment.id)) {
        continue;
      }
      visited.add(compartment.id);
      const parent = compartment.parentCompartmentId ? byId.get(compartment.parentCompartmentId) : null;
      const pathParts = [...ancestors, compartment.name || compartment.id];
      rows.push({
        ...compartment,
        depth,
        parentName: parent?.name || (compartment.id === rootCompartmentId ? '-' : 'Root'),
        path: pathParts.join(' / '),
      });
      walk(compartment.id, depth + 1, pathParts);
    }
  }

  walk('', 0);
  for (const compartment of sortCompartments(compartments)) {
    if (!visited.has(compartment.id)) {
      rows.push({ ...compartment, depth: 0, parentName: 'Root', path: compartment.name || compartment.id });
    }
  }
  return rows;
}

