  function cloudForResource(resource: ResourceRecord): Exclude<ActiveCloud, null> {
    const type = String(resource.resourceType || resource.providerType || '').toLowerCase();
    const id = String(resource.id || '').toLowerCase();
    const gcpInventoryRows = [
      ...(gcpInventory?.projects || []),
      ...(gcpInventory?.regions || []),
      ...(gcpInventory?.zones || []),
      ...(gcpInventory?.networks || []),
      ...(gcpInventory?.subnets || []),
      ...(gcpInventory?.firewallRules || []),
      ...(gcpInventory?.routes || []),
      ...(gcpInventory?.routers || []),
      ...(gcpInventory?.externalIps || []),
      ...(gcpInventory?.instances || []),
      ...(gcpInventory?.disks || []),
      ...(gcpInventory?.snapshots || []),
      ...(gcpInventory?.images || []),
      ...(gcpInventory?.buckets || []),
      ...(gcpInventory?.sqlInstances || []),
      ...(gcpInventory?.sqlDatabases || []),
      ...(gcpInventory?.gkeClusters || []),
      ...(gcpInventory?.loadBalancers || []),
      ...(gcpInventory?.serviceAccounts || []),
    ];
    if (resource.id && gcpInventoryRows.some((row) => row.id === resource.id || row.name === resource.id)) {
      return 'gcp';
    }
    const gcpTypes = new Set(['project', 'region', 'zone', 'vpcnetwork', 'firewallrule', 'route', 'cloudrouter', 'externalip', 'computeinstance', 'disk', 'snapshot', 'image', 'bucket', 'sqlinstance', 'sqldatabase', 'gkecluster', 'loadbalancer', 'serviceaccount']);
    if (
      gcpTypes.has(type)
      || (activeCloud === 'gcp' && ['subnet', 'routetable'].includes(type))
      || id.includes('googleapis.com/')
      || id.includes('/compute/v1/projects/')
      || id.includes('/sql/v1beta4/projects/')
      || id.startsWith('projects/')
    ) {
      return 'gcp';
    }
    const azureInventoryRows = [
      ...(azureInventory?.virtualMachines || []),
      ...(azureInventory?.managedDisks || []),
      ...(azureInventory?.snapshots || []),
      ...(azureInventory?.images || []),
      ...(azureInventory?.restorePoints || []),
      ...(azureInventory?.vnets || []),
      ...(azureInventory?.subnets || []),
      ...(azureInventory?.routeTables || []),
      ...(azureInventory?.routes || []),
      ...(azureInventory?.networkSecurityGroups || []),
      ...(azureInventory?.networkSecurityRules || []),
      ...(azureInventory?.publicIps || []),
      ...(azureInventory?.loadBalancers || []),
      ...(azureInventory?.natGateways || []),
      ...(azureInventory?.privateEndpoints || []),
      ...(azureInventory?.storageAccounts || []),
      ...(azureInventory?.blobContainers || []),
      ...(azureInventory?.blobs || []),
      ...(azureInventory?.fileShares || []),
      ...(azureInventory?.sqlServers || []),
      ...(azureInventory?.sqlDatabases || []),
      ...(azureInventory?.cosmosDbAccounts || []),
      ...(azureInventory?.cosmosDbDatabases || []),
      ...(azureInventory?.postgresFlexibleServers || []),
      ...(azureInventory?.mysqlFlexibleServers || []),
    ];
    if (resource.id && azureInventoryRows.some((row) => row.id === resource.id || row.name === resource.id)) {
      return 'azure';
    }
    const azureTypes = new Set(['virtualmachine', 'manageddisk', 'snapshot', 'image', 'restorepoint', 'restorepointcollection', 'vnet', 'networksecuritygroup', 'networksecurityrule', 'publicip', 'loadbalancer', 'natgateway', 'privateendpoint', 'storageaccount', 'blobcontainer', 'blob', 'fileshare', 'sqlserver', 'sqldatabase', 'cosmosdbaccount', 'cosmosdbdatabase', 'postgresflexibleserver', 'mysqlflexibleserver']);
    if (
      activeCloud === 'azure'
      && (azureTypes.has(type) || ['subnet', 'routetable'].includes(type) || type.includes('microsoft.') || type.includes('microsoft/') || id.includes('/providers/microsoft.'))
    ) {
      return 'azure';
    }
    if (azureTypes.has(type) || type.includes('microsoft.') || type.includes('microsoft/') || id.includes('/providers/microsoft.') || id.startsWith('/subscriptions/')) {
      return 'azure';
    }
    const awsInventoryRows = [
      ...(awsInventory?.instances || []),
      ...(awsInventory?.vpcs || []),
      ...(awsInventory?.subnets || []),
      ...(awsInventory?.securityGroups || []),
      ...(awsInventory?.routeTables || []),
      ...(awsInventory?.internetGateways || []),
      ...(awsInventory?.natGateways || []),
      ...(awsInventory?.ebsVolumes || []),
      ...(awsInventory?.ebsSnapshots || []),
      ...(awsInventory?.s3Buckets || []),
      ...(awsInventory?.rdsDatabases || []),
      ...(awsInventory?.loadBalancers || []),
      ...(awsInventory?.elasticIps || []),
    ];
    if (resource.id && awsInventoryRows.some((row) => row.id === resource.id || row.name === resource.id)) {
      return 'aws';
    }
    const awsTypes = new Set(['ec2instance', 'vpc', 'securitygroup', 'routetable', 'internetgateway', 'natgateway', 'ebsvolume', 'ebssnapshot', 's3bucket', 'rdsdatabase', 'loadbalancer', 'elasticip']);
    const sharedTypes = new Set(['subnet', 'routetable', 'internetgateway', 'natgateway']);
    if (activeCloud === 'aws' && (awsTypes.has(type) || sharedTypes.has(type))) {
      return 'aws';
    }
    if (
      awsTypes.has(type)
      || type.includes('ec2')
      || type.includes('ebs')
      || type.includes('vpc')
      || type.includes('s3')
      || type.includes('rds')
      || type.includes('elastic')
      || id.startsWith('i-')
      || id.startsWith('vpc-')
      || id.startsWith('subnet-')
      || id.startsWith('sg-')
      || id.startsWith('rtb-')
      || id.startsWith('igw-')
      || id.startsWith('nat-')
      || id.startsWith('vol-')
      || id.startsWith('snap-')
      || id.startsWith('eipalloc-')
      || id.startsWith('eni-')
      || id.startsWith('ami-')
    ) {
      return 'aws';
    }
    return 'oci';
  }

  function openResourceDetail(resource: ResourceRecord) {
    const resourceCloud = cloudForResource(resource);
    setResourceDetailPreviousTab(activeTab === 'resourceDetail' || activeTab === 'ociResourceDetail' ? resourceDetailPreviousTab : activeTab);
    setResourceDetailTarget(resource);
    setActiveCloud(resourceCloud);
    setActiveTab('resourceDetail');
    void refreshAuditLog();
    if (
      resourceCloud === 'aws'
      && String(resource.resourceType || resource.providerType || '').toLowerCase() === 'routetable'
      && resource.id
      && resource.region
    ) {
      awsService
        .getAwsRouteTable(resource.id, resource.region, awsInventoryRegion)
        .then((response) => {
          updateAwsNetworkRow(response.data.routeTable);
          setResourceDetailTarget((current) => current?.id === resource.id ? { ...current, ...response.data.routeTable } : current);
        })
        .catch((err) => {
          setAwsNetworkActionError(err instanceof Error ? err.message : 'Unable to load route table rules.');
        });
    }
  }

  function closeResourceDetail() {
    setActiveTab(resourceDetailPreviousTab);
  }

  async function loadDashboard(connector = selectedConnector) {
    if (!selectedConnectorId || !connector) {
      setDashboard(null);
      setDashboardError('');
      return;
    }

    if (connector.status !== 'verified') {
      setDashboard(null);
      setDashboardError('Verify the selected connector to load resources.');
      return;
    }

    setDashboardLoading(true);
    setDashboardError('');

    try {
      const response = await dashboardService.getDashboard();
      setDashboard(response.data);
    } catch (err) {
      setDashboard(null);
      setDashboardError(err instanceof Error ? err.message : 'Unable to load dashboard.');
    } finally {
      setDashboardLoading(false);
    }
  }

