  function gcpZoneOf(row?: ResourceRecord | null) {
    return String(row?.availabilityDomain || row?.zone || '').trim();
  }

  function gcpRegionFromZone(zone: string) {
    return String(zone || '').replace(/-[a-z]$/, '');
  }

  function gcpNetworkIsCustom(network?: ResourceRecord | null) {
    if (!network) return false;
    const autoCreateSubnetworks = (network.rawSummary as Record<string, unknown> | undefined)?.autoCreateSubnetworks;
    if (typeof autoCreateSubnetworks === 'boolean') {
      return !autoCreateSubnetworks;
    }
    return String(network.status || '').toLowerCase() === 'custom';
  }

  function gcpSubnetMatchesNetwork(subnet: ResourceRecord, networkValue: string) {
    if (!networkValue) return true;
    const subnetNetwork = String(subnet.vpcId || (subnet.rawSummary as Record<string, unknown> | undefined)?.network || '');
    const subnetNetworkName = String(subnet.vpcName || subnetNetwork.split('/').pop() || '');
    return subnetNetwork === networkValue
      || subnetNetworkName === networkValue
      || subnetNetwork.endsWith(`/networks/${networkValue}`)
      || networkValue.endsWith(`/networks/${subnetNetworkName}`);
  }

  function gcpSubnetsForNetworkAndZone(networkValue: string, zoneValue: string) {
    const region = gcpRegionFromZone(zoneValue);
    return (gcpInventory?.subnets || []).filter((subnet) => {
      const matchesNetwork = gcpSubnetMatchesNetwork(subnet, networkValue);
      const matchesRegion = !region || !subnet.region || subnet.region === region;
      return matchesNetwork && matchesRegion && (subnet.id || subnet.name);
    });
  }

  function parseLabelsText(text: string) {
    return text
      .split(/[,\n]/)
      .map((part) => part.trim())
      .filter(Boolean)
      .reduce<Record<string, string>>((labels, part) => {
        const [key, ...rest] = part.split('=');
        const cleanKey = String(key || '').trim().toLowerCase().replace(/[^a-z0-9_-]/g, '-');
        if (cleanKey) {
          labels[cleanKey] = rest.join('=').trim();
        }
        return labels;
      }, {});
  }

  function updateGcpInstanceRow(instance: ResourceRecord) {
    const key = String(instance.id || instance.name || '');
    if (!key) {
      return;
    }
    setGcpInventory((current) => {
      if (!current) return current;
      const upsert = (rows: ResourceRecord[] = []) => {
        const exists = rows.some((row) => String(row.id || row.name) === key || (row.name && row.name === instance.name));
        return exists ? rows.map((row) => (String(row.id || row.name) === key || (row.name && row.name === instance.name) ? { ...row, ...instance } : row)) : [instance, ...rows];
      };
      const instances = upsert(current.instances);
      const allResources = upsert(current.allResources);
      return {
        ...current,
        instances,
        allResources,
        summary: {
          ...current.summary,
          instances: instances.length,
          runningInstances: instances.filter((row) => String(row.status || '').toLowerCase() === 'running').length,
          stoppedInstances: instances.filter((row) => ['terminated', 'stopped', 'stopping'].includes(String(row.status || '').toLowerCase())).length,
        },
      };
    });
  }

  function updateGcpResourceCollection(collection: 'disks' | 'snapshots' | 'images', resource: ResourceRecord) {
    const key = String(resource.id || resource.name || '');
    if (!key) return;
    setGcpInventory((current) => {
      if (!current) return current;
      const rows = current[collection] || [];
      const exists = rows.some((row) => String(row.id || row.name) === key || (row.name && row.name === resource.name));
      const nextRows = exists ? rows.map((row) => (String(row.id || row.name) === key || (row.name && row.name === resource.name) ? { ...row, ...resource } : row)) : [resource, ...rows];
      const allResources = exists ? current.allResources.map((row) => (String(row.id || row.name) === key || (row.name && row.name === resource.name) ? { ...row, ...resource } : row)) : [resource, ...current.allResources];
      return {
        ...current,
        [collection]: nextRows,
        allResources,
        summary: {
          ...current.summary,
          [collection]: nextRows.length,
          ...(collection === 'disks' ? { diskUsageGb: nextRows.reduce((sum, row) => sum + sizeGbFor(row), 0) } : {}),
        },
      };
    });
  }

  function updateGcpBucketRow(bucket: ResourceRecord) {
    const key = String(bucket.id || bucket.name || '');
    if (!key) return;
    setGcpInventory((current) => {
      if (!current) return current;
      const exists = current.buckets.some((row) => String(row.id || row.name) === key || row.name === bucket.name);
      const buckets = exists ? current.buckets.map((row) => (String(row.id || row.name) === key || row.name === bucket.name ? { ...row, ...bucket } : row)) : [bucket, ...current.buckets];
      const allResources = exists ? current.allResources.map((row) => (String(row.id || row.name) === key || row.name === bucket.name ? { ...row, ...bucket } : row)) : [bucket, ...current.allResources];
      return { ...current, buckets, allResources, summary: { ...current.summary, buckets: buckets.length } };
    });
  }

  function removeGcpBucketRow(bucketName: string) {
    setGcpInventory((current) => {
      if (!current) return current;
      const buckets = current.buckets.filter((row) => String(row.name || row.id) !== bucketName);
      const allResources = current.allResources.filter((row) => String(row.name || row.id) !== bucketName);
      return { ...current, buckets, allResources, summary: { ...current.summary, buckets: buckets.length } };
    });
  }

  function updateGcpNetworkCollection(collection: 'networks' | 'subnets' | 'firewallRules' | 'routes' | 'externalIps', resource: ResourceRecord) {
    const key = String(resource.id || resource.name || '');
    if (!key) return;
    setGcpInventory((current) => {
      if (!current) return current;
      const rows = current[collection] || [];
      const exists = rows.some((row) => String(row.id || row.name) === key || row.name === resource.name);
      const nextRows = exists ? rows.map((row) => (String(row.id || row.name) === key || row.name === resource.name ? { ...row, ...resource } : row)) : [resource, ...rows];
      const allResources = exists ? current.allResources.map((row) => (String(row.id || row.name) === key || row.name === resource.name ? { ...row, ...resource } : row)) : [resource, ...current.allResources];
      const summaryKey = collection === 'networks' ? 'networks' : collection === 'firewallRules' ? 'firewallRules' : collection;
      return { ...current, [collection]: nextRows, allResources, summary: { ...current.summary, [summaryKey]: nextRows.length } };
    });
  }

  function removeGcpNetworkResource(collection: 'networks' | 'subnets' | 'firewallRules' | 'routes' | 'externalIps', resourceName: string) {
    setGcpInventory((current) => {
      if (!current) return current;
      const rows = (current[collection] || []).filter((row) => String(row.name || row.id) !== resourceName);
      const allResources = current.allResources.filter((row) => String(row.name || row.id) !== resourceName);
      const summaryKey = collection === 'networks' ? 'networks' : collection === 'firewallRules' ? 'firewallRules' : collection;
      return { ...current, [collection]: rows, allResources, summary: { ...current.summary, [summaryKey]: rows.length } };
    });
  }

  function updateGcpSqlInstanceRow(instance: ResourceRecord) {
    const key = String(instance.id || instance.name || '');
    if (!key) return;
    setGcpInventory((current) => {
      if (!current) return current;
      const exists = current.sqlInstances.some((row) => String(row.id || row.name) === key || row.name === instance.name);
      const sqlInstances = exists ? current.sqlInstances.map((row) => (String(row.id || row.name) === key || row.name === instance.name ? { ...row, ...instance } : row)) : [instance, ...current.sqlInstances];
      const allResources = exists ? current.allResources.map((row) => (String(row.id || row.name) === key || row.name === instance.name ? { ...row, ...instance } : row)) : [instance, ...current.allResources];
      return { ...current, sqlInstances, allResources, summary: { ...current.summary, sqlInstances: sqlInstances.length } };
    });
  }

  function removeGcpSqlInstanceRow(instanceName: string) {
    setGcpInventory((current) => {
      if (!current) return current;
      const sqlInstances = current.sqlInstances.map((row) => (String(row.name || row.id) === instanceName ? { ...row, status: 'DELETING' } : row));
      const allResources = current.allResources.map((row) => (String(row.name || row.id) === instanceName ? { ...row, status: 'DELETING' } : row));
      return { ...current, sqlInstances, allResources, summary: { ...current.summary, sqlInstances: sqlInstances.length } };
    });
  }

  function gcpInstanceActionComplete(action: gcpService.GcpInstanceAction, status?: string) {
    const state = String(status || '').toLowerCase();
    if (action === 'start') return state === 'running';
    if (action === 'stop') return state === 'terminated';
    if (action === 'reset' || action === 'reboot') return state === 'running';
    return false;
  }

  async function pollGcpInstanceStatusAfterAction(instance: ResourceRecord, action: gcpService.GcpInstanceAction) {
    const name = String(instance.name || '').trim();
    const zone = gcpZoneOf(instance);
    let latest = instance;
    for (let attempt = 0; attempt < 6; attempt += 1) {
      await new Promise((resolve) => window.setTimeout(resolve, attempt === 0 ? 5000 : 7000));
      const response = await gcpService.getGcpInstanceStatus(name, zone);
      latest = { ...latest, ...response.data.instance };
      updateGcpInstanceRow(latest);
      if (gcpInstanceActionComplete(action, latest.status)) {
        return latest;
      }
    }
    return latest;
  }

  async function submitGcpInstanceAction(instance: ResourceRecord, action: gcpService.GcpInstanceAction) {
    const name = String(instance.name || '').trim();
    const zone = gcpZoneOf(instance);
    if (!name || !zone) {
      setGcpComputeActionError('VM name and zone are required for this operation.');
      return;
    }
    setGcpComputeActionInFlight(`${action}:${name}`);
    setGcpComputeActionError('');
    setGcpComputeActionMessage('');
    try {
      const response = await gcpService.runGcpInstanceAction(name, action, { zone });
      const submittedInstance = { ...instance, ...response.data.instance };
      updateGcpInstanceRow(submittedInstance);
      setGcpComputeActionMessage(`${response.data.message} Refreshing VM status...`);
      try {
        const refreshedInstance = await pollGcpInstanceStatusAfterAction(submittedInstance, action);
        const final = gcpInstanceActionComplete(action, refreshedInstance.status);
        setGcpComputeActionMessage(final ? `GCP VM ${name} is now ${gcpVmStateLabel(refreshedInstance.status)}.` : `${response.data.message} Use Refresh status if the VM is still changing state.`);
      } catch {
        setGcpComputeActionMessage(`${response.data.message} Status refresh did not complete. Use Refresh status in a moment.`);
      }
      void refreshAuditLog();
    } catch (err) {
      setGcpComputeActionError(err instanceof Error ? err.message : 'Unable to submit GCP VM action.');
      void refreshAuditLog();
    } finally {
      setGcpComputeActionInFlight('');
    }
  }

  async function refreshGcpInstanceStatus(instance: ResourceRecord) {
    const name = String(instance.name || '').trim();
    const zone = gcpZoneOf(instance);
    if (!name || !zone) {
      setGcpComputeActionError('VM name and zone are required to refresh status.');
      return;
    }
    setGcpComputeActionInFlight(`refresh:${name}`);
    setGcpComputeActionError('');
    setGcpComputeActionMessage('');
    try {
      const response = await gcpService.getGcpInstanceStatus(name, zone);
      updateGcpInstanceRow({ ...instance, ...response.data.instance });
      setGcpComputeActionMessage('GCP VM status refreshed.');
    } catch (err) {
      setGcpComputeActionError(err instanceof Error ? err.message : 'Unable to refresh GCP VM status.');
    } finally {
      setGcpComputeActionInFlight('');
    }
  }

  async function submitGcpVmCreate(event?: FormEvent) {
    event?.preventDefault();
    setGcpComputeActionError('');
    setGcpComputeActionMessage('');
    const selectedNetwork = (gcpInventory?.networks || []).find((network) => {
      const id = String(network.id || '');
      const name = String(network.name || '');
      return id === gcpVmCreateForm.network || name === gcpVmCreateForm.network;
    });
    const matchingSubnets = gcpSubnetsForNetworkAndZone(gcpVmCreateForm.network, gcpVmCreateForm.zone);
    if (gcpNetworkIsCustom(selectedNetwork) && !gcpVmCreateForm.subnetwork) {
      const region = gcpRegionFromZone(gcpVmCreateForm.zone);
      setGcpComputeActionError(
        matchingSubnets.length
          ? `The selected VPC is custom subnet mode. Select a subnet in ${region || 'the VM region'} before creating the VM.`
          : `The selected VPC is custom subnet mode, but no subnet is cached for ${region || 'the VM region'}. Refresh GCP inventory or create a subnet first, then retry.`,
      );
      return;
    }
    setGcpComputeActionInFlight('create');
    try {
      const networkTags = [
        ...gcpVmCreateForm.networkTags.split(',').map((tag) => tag.trim()).filter(Boolean),
        ...(gcpVmCreateForm.allowHttp ? ['http-server'] : []),
        ...(gcpVmCreateForm.allowHttps ? ['https-server'] : []),
        ...(gcpVmCreateForm.allowLbHealthChecks ? ['lb-health-check'] : []),
      ].filter((tag, index, list) => list.indexOf(tag) === index);
      const bootSourceType = gcpVmCreateForm.bootSourceType;
      const response = await gcpService.createGcpInstance({
        zone: gcpVmCreateForm.zone,
        name: gcpVmCreateForm.name,
        machineType: gcpVmCreateForm.machineType,
        diskSizeGb: gcpVmCreateForm.diskSizeGb,
        diskType: gcpVmCreateForm.diskType,
        network: gcpVmCreateForm.network,
        subnetwork: gcpVmCreateForm.subnetwork,
        assignPublicIp: gcpVmCreateForm.assignPublicIp,
        serviceAccountEmail: gcpVmCreateForm.serviceAccountEmail,
        acceptCostWarning: gcpVmCreateForm.acceptCostWarning,
        hostname: gcpVmCreateForm.hostname,
        ipForwarding: gcpVmCreateForm.ipForwarding,
        networkTags,
        ...(bootSourceType === 'snapshot' || bootSourceType === 'archiveSnapshot' ? { sourceSnapshot: gcpVmCreateForm.sourceSnapshot } : {}),
        ...(bootSourceType === 'existingDisk' ? { sourceDisk: gcpVmCreateForm.sourceDisk } : {}),
        ...(bootSourceType === 'publicImage' || bootSourceType === 'customImage' ? { sourceImage: gcpVmCreateForm.sourceImage } : {}),
        labels: parseLabelsText(gcpVmCreateForm.labelsText),
      });
      updateGcpInstanceRow(response.data.instance);
      setGcpComputeActionMessage(response.data.message);
      setGcpShowCreateVm(false);
      setGcpVmCreateForm(defaultGcpVmCreateForm);
      void refreshAuditLog();
    } catch (err) {
      setGcpComputeActionError(err instanceof Error ? err.message : 'Unable to create GCP VM.');
      void refreshAuditLog();
    } finally {
      setGcpComputeActionInFlight('');
    }
  }

