    setAzureVmActionError('');
    setAzureVmActionMessage('');
    const baseName = String(vm?.name || 'vm').replace(/[^a-zA-Z0-9-]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'vm';
    setAzureVmOperationForm({
      vmSize: String(vm?.size || vm?.shape || 'Standard_B1s'),
      artifactName: vm?.name ? `${baseName}-${mode}` : '',
      restorePointCollectionName: `${baseName}-restore-points`,
      restorePointName: `${baseName}-rp-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}`,
      restorePointConsistency: 'CrashConsistent',
    });
    setAzureVmCreateForm((current) => ({
      ...defaultAzureVmCreateForm,
      region: azureRegionFilter !== 'all' ? azureRegionFilter : current.region,
      resourceGroup: azureResourceGroupFilter !== 'all' ? azureResourceGroupFilter : current.resourceGroup,
    }));
