  function updateAzureResourceCollection(collection: keyof Pick<AzureInventory, 'storageAccounts' | 'blobContainers' | 'blobs' | 'fileShares' | 'managedDisks' | 'snapshots' | 'sqlServers' | 'sqlDatabases' | 'cosmosDbAccounts' | 'cosmosDbDatabases' | 'postgresFlexibleServers' | 'mysqlFlexibleServers'>, item: AzureResource) {
    if (!item?.id) {
      return;
    }
    setAzureInventory((current) => {
      if (!current) {
        return current;
      }
      const rows = ((current[collection] as AzureResource[]) || []);
      const exists = rows.some((row) => row.id === item.id);
      const nextRows = exists ? rows.map((row) => row.id === item.id ? { ...row, ...item } : row) : [item, ...rows];
      const allResources = collection === 'blobs'
        ? current.allResources
        : (current.allResources.some((row) => row.id === item.id)
          ? current.allResources.map((row) => row.id === item.id ? { ...row, ...item } : row)
          : [item, ...current.allResources]);
      return {
        ...current,
        [collection]: nextRows,
        allResources,
        summary: {
          ...current.summary,
          [collection]: nextRows.length,
          totalResources: allResources.length,
        },
      };
    });
  }

  function removeAzureResourceCollection(collection: keyof Pick<AzureInventory, 'storageAccounts' | 'blobContainers' | 'blobs' | 'fileShares' | 'managedDisks' | 'snapshots' | 'sqlServers' | 'sqlDatabases' | 'cosmosDbAccounts' | 'cosmosDbDatabases' | 'postgresFlexibleServers' | 'mysqlFlexibleServers'>, id?: string) {
    if (!id) {
      return;
    }
    setAzureInventory((current) => {
      if (!current) {
        return current;
      }
      const rows = ((current[collection] as AzureResource[]) || []).filter((row) => row.id !== id);
      const allResources = collection === 'blobs' ? current.allResources : current.allResources.filter((row) => row.id !== id);
      return {
        ...current,
        [collection]: rows,
        allResources,
        summary: {
          ...current.summary,
          [collection]: rows.length,
          totalResources: allResources.length,
        },
      };
    });
  }

  function azureNetworkCollection(resource: AzureResource): keyof Pick<AzureInventory, 'vnets' | 'subnets' | 'routeTables' | 'routes' | 'networkSecurityGroups' | 'networkSecurityRules' | 'publicIps' | 'loadBalancers' | 'natGateways' | 'privateEndpoints'> | '' {
    const type = resource.resourceType || resource.providerType;
    if (type === 'vnet') return 'vnets';
    if (type === 'subnet') return 'subnets';
    if (type === 'routeTable') return 'routeTables';
    if (type === 'route') return 'routes';
    if (type === 'networkSecurityGroup') return 'networkSecurityGroups';
    if (type === 'networkSecurityRule') return 'networkSecurityRules';
    if (type === 'publicIp') return 'publicIps';
    if (type === 'loadBalancer') return 'loadBalancers';
    if (type === 'natGateway') return 'natGateways';
    if (type === 'privateEndpoint') return 'privateEndpoints';
    return '';
  }

  function updateAzureNetworkRow(resource: AzureResource) {
    const collection = azureNetworkCollection(resource);
    if (!collection) return;
    setAzureInventory((current) => {
      if (!current) return current;
      const rows = (current[collection] || []) as AzureResource[];
      const nextRows = rows.some((row) => row.id === resource.id) ? rows.map((row) => row.id === resource.id ? { ...row, ...resource } : row) : [resource, ...rows];
      const allResources = current.allResources.some((row) => row.id === resource.id) ? current.allResources.map((row) => row.id === resource.id ? { ...row, ...resource } : row) : [resource, ...current.allResources];
      return { ...current, [collection]: nextRows, allResources, summary: { ...current.summary, [collection]: nextRows.length, totalResources: allResources.length } };
    });
  }

  function removeAzureNetworkRow(resource: AzureResource) {
    const collection = azureNetworkCollection(resource);
    if (!collection || !resource.id) return;
    setAzureInventory((current) => {
      if (!current) return current;
      const rows = ((current[collection] || []) as AzureResource[]).filter((row) => row.id !== resource.id);
      const allResources = current.allResources.filter((row) => row.id !== resource.id);
      return { ...current, [collection]: rows, allResources, summary: { ...current.summary, [collection]: rows.length, totalResources: allResources.length } };
    });
  }

