      if ((azureNetworkForm.resourceType === 'publicIp' || azureNetworkForm.resourceType === 'natGateway') && !azureNetworkShowPaidCreate) {
        throw new Error('Public IP and NAT Gateway creation is disabled by default because it can add Azure cost. Enable paid networking creation to continue.');
      }
