  function azureDatabaseCollection(resource: AzureResource): keyof Pick<AzureInventory, 'sqlServers' | 'sqlDatabases' | 'cosmosDbAccounts' | 'cosmosDbDatabases' | 'postgresFlexibleServers' | 'mysqlFlexibleServers'> | '' {
    const type = resource.resourceType || resource.providerType;
    if (type === 'sqlServer') return 'sqlServers';
    if (type === 'sqlDatabase') return 'sqlDatabases';
    if (type === 'cosmosDbAccount') return 'cosmosDbAccounts';
    if (type === 'cosmosDbDatabase') return 'cosmosDbDatabases';
    if (type === 'postgresFlexibleServer') return 'postgresFlexibleServers';
    if (type === 'mysqlFlexibleServer') return 'mysqlFlexibleServers';
    return '';
  }

  function updateAzureDatabaseRow(resource: AzureResource) {
    const collection = azureDatabaseCollection(resource);
    if (collection) {
      updateAzureResourceCollection(collection, resource);
    }
  }

  function removeAzureDatabaseRow(resource: AzureResource) {
    const collection = azureDatabaseCollection(resource);
    if (collection) {
      removeAzureResourceCollection(collection, resource.id);
    }
  }

  function azureDatabaseCanStartStop(resource: AzureResource) {
    const type = resource.resourceType || resource.providerType;
    return type === 'sqlDatabase' || type === 'postgresFlexibleServer' || type === 'mysqlFlexibleServer';
  }

