  function openAzureDatabaseDelete(resource: AzureResource) {
    if ((resource.resourceType || resource.providerType) === 'sqlDatabase') {
      openAzureSqlDatabaseDelete(resource);
      return;
    }
    openSafetyDelete({
      title: 'Delete Azure database resource',
      eyebrow: 'Azure Database',
      message: 'This permanently deletes the selected database resource. Confirm only after checking backups, dependencies, and restore requirements.',
      expected: resource.name,
      alternateExpected: resource.id,
      details: [
        { label: 'Resource', value: resource.name },
        { label: 'Type', value: azureTypeLabel(String(resource.resourceType || resource.providerType || 'database')) },
        { label: 'Resource group', value: resource.resourceGroup || '-' },
        { label: 'Region', value: resource.region || '-' },
      ],
      onConfirm: async (confirmation) => {
        const response = await azureService.deleteAzureDatabaseResource({
          resourceId: resource.id,
          resourceName: resource.name,
          resourceType: resource.resourceType || resource.providerType,
          region: resource.region,
          resourceGroup: resource.resourceGroup,
          confirmation,
        });
        removeAzureDatabaseRow(response.data.resource || resource);
        setAzureDatabaseActionMessage(response.data.message);
        void refreshAuditLog();
      },
    });
  }

  function azureDatabaseActions(resource: AzureResource) {
    const type = resource.resourceType || resource.providerType;
    const supportsStartStop = azureDatabaseCanStartStop(resource);
    const terminal = String(resource.status || '').toLowerCase().includes('deleting');
    return (
      <ActionMenu
        items={[
          { label: 'View details', tone: 'primary', onClick: () => openResourceDetail(resource as unknown as ResourceRecord) },
          { label: 'Refresh status', disabled: !resource.id || azureDatabaseActionInFlight === `refresh:${resource.id}`, onClick: () => void refreshAzureDatabaseRowStatus(resource), tone: 'primary' },
          { label: 'Start', disabled: !supportsStartStop || !resource.id || terminal || azureDatabaseActionInFlight === `start:${resource.id}`, onClick: () => void runAzureDatabaseQuickAction(resource, 'start'), tone: 'primary' },
          { label: 'Stop', disabled: !supportsStartStop || !resource.id || terminal || azureDatabaseActionInFlight === `stop:${resource.id}`, onClick: () => void runAzureDatabaseQuickAction(resource, 'stop'), tone: 'warning' },
          ...(type === 'sqlDatabase' ? [{ label: 'Prepare scale', onClick: () => prepareAzureSqlDatabaseScale(resource), tone: 'primary' as const }] : []),
          { label: 'Delete', tone: 'danger', disabled: !resource.id || terminal || resource.name === 'master', onClick: () => openAzureDatabaseDelete(resource) },
        ]}
      />
    );
  }

