  async function loadAzureBlobs(container = azureSelectedContainer) {
    if (!container) {
      setAzureStorageActionError('Select a blob container before loading blobs.');
      return;
    }
    const accountName = String(container.storageAccountName || '');
    const resourceGroup = azureResourceGroupFrom(container);
    if (!accountName || !resourceGroup || !container.name) {
      setAzureStorageActionError('Blob container is missing storage account, resource group, or container name. Refresh Azure storage discovery and try again.');
      return;
    }
    setAzureStorageActionInFlight(`blobs:${container.id}`);
    setAzureStorageActionError('');
    try {
      const response = await azureService.listAzureBlobs({
        accountName,
        resourceGroup,
        containerName: String(container.name || ''),
        region: container.region,
        prefix: azureBlobPrefix,
      });
      setAzureBlobRows(response.data.blobs);
      response.data.blobs.forEach((blob) => updateAzureResourceCollection('blobs', blob));
      setAzureStorageActionMessage(`Loaded ${response.data.blobs.length} blobs from ${accountName} / ${container.name}.`);
    } catch (err) {
      setAzureStorageActionError(err instanceof Error ? err.message : 'Unable to load Azure blobs.');
    } finally {
      setAzureStorageActionInFlight('');
    }
  }

  function openAzureBlobManager(container: AzureResource) {
    setAzureSelectedContainer(container);
    setAzureStorageActionError('');
    setAzureStorageActionMessage(`Opening blobs for ${container.storageAccountName || 'storage account'} / ${container.name || 'container'}...`);
    const cachedRows = (azureInventory?.blobs || []).filter((blob) =>
      blob.storageAccountName === container.storageAccountName && blob.containerName === container.name);
    setAzureBlobRows(cachedRows);
    window.setTimeout(() => {
      azureBlobManagerRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 50);
    void loadAzureBlobs(container);
  }

  function handleAzureBlobFile(file?: File | null) {
    if (!file) {
      setAzureBlobForm((current) => ({ ...current, contentBase64: '', fileName: '', fileSize: '' }));
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result || '');
      const base64 = result.includes(',') ? result.split(',').pop() || '' : result;
      setAzureBlobForm((current) => ({
        ...current,
        blobName: current.blobName || file.name,
        contentType: file.type || 'application/octet-stream',
        content: current.content,
        contentBase64: base64,
        fileName: file.name,
        fileSize: String(file.size),
      }));
      setAzureStorageActionError('');
      setAzureStorageActionMessage(`Selected ${file.name} for upload.`);
    };
    reader.onerror = () => {
      setAzureStorageActionError('Unable to read the selected file.');
    };
    reader.readAsDataURL(file);
  }

  async function submitAzureBlob(event: FormEvent) {
    event.preventDefault();
    if (!azureSelectedContainer) {
      setAzureStorageActionError('Select a blob container before uploading a blob.');
      return;
    }
    setAzureStorageActionInFlight('blob-upload');
    setAzureStorageActionError('');
    setAzureStorageActionMessage('');
    try {
      const accountName = String(azureSelectedContainer.storageAccountName || '');
      const resourceGroup = azureResourceGroupFrom(azureSelectedContainer);
      if (!accountName || !resourceGroup) {
        throw new Error('Selected blob container is missing storage account or resource group. Refresh Azure storage discovery and try again.');
      }
      if (!azureBlobForm.content && !azureBlobForm.contentBase64) {
        throw new Error('Select a file or enter text content before uploading.');
      }
      const response = await azureService.uploadAzureBlob({
        accountName,
        resourceGroup,
        containerName: String(azureSelectedContainer.name || ''),
        region: azureSelectedContainer.region,
        blobName: azureBlobForm.blobName,
        contentType: azureBlobForm.contentType,
        content: azureBlobForm.contentBase64 ? undefined : azureBlobForm.content,
        contentBase64: azureBlobForm.contentBase64 || undefined,
      });
      updateAzureResourceCollection('blobs', response.data.blob);
      setAzureBlobRows((current) => [response.data.blob, ...current.filter((row) => row.id !== response.data.blob.id)]);
      setAzureStorageActionMessage(response.data.message);
      setAzureBlobForm(defaultAzureBlobForm);
      void refreshAuditLog();
    } catch (err) {
      setAzureStorageActionError(err instanceof Error ? err.message : 'Unable to upload Azure blob.');
      void refreshAuditLog();
    } finally {
      setAzureStorageActionInFlight('');
    }
  }

