  function awsRequestScope(region?: string) {
    return {
      region: region || awsInventoryRegion || selectedAwsConnector?.region || '',
      scanRegion: awsInventoryRegion,
    };
  }

  function awsCreateRegionOptions() {
    return Array.from(new Set([
      ...(awsInventory?.regions || []).map((region) => region.name),
      ...(awsInventory?.scan?.scannedRegions || []),
      ...(awsInventory?.subnets || []).map((subnet) => subnet.region || ''),
      ...(awsInventory?.securityGroups || []).map((group) => group.region || ''),
      selectedAwsConnector?.region || '',
    ].filter(Boolean))).sort((left, right) => left.localeCompare(right));
  }

  function awsPreferredCreateRegion() {
    const regionOptions = awsCreateRegionOptions();
    if (awsInventoryRegion !== 'all' && regionOptions.includes(awsInventoryRegion)) {
      return awsInventoryRegion;
    }
    if (selectedAwsConnector?.region && regionOptions.includes(selectedAwsConnector.region)) {
      return selectedAwsConnector.region;
    }
    return regionOptions[0] || selectedAwsConnector?.region || '';
  }

  function awsCreateSubnetsForRegion(region: string) {
    return (awsInventory?.subnets || []).filter((subnet) => !region || subnet.region === region);
  }

  function awsCreateSecurityGroupsForRegion(region: string, subnetId = '') {
    const subnet = (awsInventory?.subnets || []).find((item) => item.id === subnetId);
    return (awsInventory?.securityGroups || []).filter((group) => {
      if (region && group.region !== region) {
        return false;
      }
      return !subnet?.vpcId || !group.vpcId || group.vpcId === subnet.vpcId;
    });
  }

  function awsCreateDefaultsForRegion(region: string) {
    const subnets = awsCreateSubnetsForRegion(region);
    const subnet = subnets[0];
    const securityGroups = awsCreateSecurityGroupsForRegion(region, subnet?.id || '');
    return {
      region,
      subnetId: subnet?.id || '',
      securityGroupId: securityGroups[0]?.id || '',
    };
  }

  async function loadAwsImageOptions(region: string, search = awsImageSearch) {
    if (!region || !selectedAwsConnector || selectedAwsConnector.status !== 'verified') {
      setAwsImageOptions([]);
      setAwsImagesError(region ? 'Verify the selected AWS connector before loading AMIs.' : '');
      return;
    }
    setAwsImagesLoading(true);
    setAwsImagesError('');
    try {
      const response = await awsService.getAwsImages(region, search);
      setAwsImageOptions(response.data.images || []);
      setAwsCreateInstanceForm((current) => ({
        ...current,
        imageId: current.imageId && (response.data.images || []).some((image) => image.id === current.imageId)
          ? current.imageId
          : response.data.images?.[0]?.id || '',
      }));
    } catch (err) {
      setAwsImageOptions([]);
      setAwsImagesError(err instanceof Error ? err.message : 'Unable to load AMI options.');
    } finally {
      setAwsImagesLoading(false);
    }
  }

