  async function submitAwsInstanceAction(instance: ResourceRecord, action: awsService.AwsInstanceAction) {
    if (!instance.id || !instance.region) {
      setAwsEc2ActionError('Instance ID and region are required.');
      return;
    }
    setAwsEc2ActionInFlight(`${action}:${instance.id}`);
    setAwsEc2ActionError('');
    setAwsEc2ActionMessage('');
    try {
      const response = await awsService.runAwsInstanceAction(instance.id, action, {
        ...awsRequestScope(instance.region),
        instanceName: instance.name,
      });
      updateAwsInstanceRow(response.data.instance);
      setAwsEc2ActionMessage(response.data.message);
      void refreshAuditLog();
      void pollAwsInstanceStatus(response.data.instance, action === 'stop' ? ['stopped'] : ['running']);
    } catch (err) {
      setAwsEc2ActionError(err instanceof Error ? err.message : `Unable to ${action} instance.`);
    } finally {
      setAwsEc2ActionInFlight('');
    }
  }

  function isAwsTransitionalState(status?: string) {
    return ['pending', 'stopping', 'shutting-down', 'rebooting'].includes(String(status || '').toLowerCase());
  }

  async function refreshAwsInstanceStatus(instance: ResourceRecord) {
    if (!instance.id || !instance.region) {
      return null;
    }
    setAwsEc2StatusRefreshing((current) => ({ ...current, [instance.id as string]: true }));
    try {
      const response = await awsService.getAwsInstanceStatus(instance.id, instance.region, awsInventoryRegion);
      updateAwsInstanceRow(response.data.instance);
      return response.data.instance;
    } catch (err) {
      setAwsEc2ActionError(err instanceof Error ? err.message : 'Unable to refresh EC2 instance status.');
      return null;
    } finally {
      setAwsEc2StatusRefreshing((current) => {
        const next = { ...current };
        delete next[instance.id as string];
        return next;
      });
    }
  }

  async function pollAwsInstanceStatus(instance: ResourceRecord, finalStates: string[] = ['running', 'stopped', 'terminated']) {
    if (!instance.id || !instance.region) {
      return;
    }
    let latest: ResourceRecord | null = instance;
    for (let attempt = 0; attempt < 18; attempt += 1) {
      await new Promise((resolve) => window.setTimeout(resolve, attempt === 0 ? 4000 : 6000));
      latest = await refreshAwsInstanceStatus(latest || instance);
      const state = String(latest?.status || '').toLowerCase();
      if (state && (finalStates.includes(state) || !isAwsTransitionalState(state))) {
        if (latest?.name || latest?.id) {
          setAwsEc2ActionMessage(`${latest.name || latest.id} is ${state}.`);
        }
        return;
      }
    }
  }

  function openAwsTerminate(instance: ResourceRecord) {
    openSafetyDelete({
      title: 'Terminate EC2 Instance',
      eyebrow: 'AWS Safety Confirmation',
      message: 'This will permanently terminate the selected EC2 instance. This action cannot be undone.',
      expected: instance.name || instance.id || '',
      alternateExpected: instance.id,
      confirmLabel: 'Terminate Instance',
      details: [
        { label: 'Instance', value: instance.name || instance.id || '-' },
        { label: 'Instance ID', value: instance.id || '-' },
        { label: 'Region', value: instance.region || '-' },
        { label: 'State', value: instance.status || '-' },
      ],
      onConfirm: async (confirmation) => {
        if (!instance.id || !instance.region) {
          throw new Error('Instance ID and region are required.');
        }
        const response = await awsService.terminateAwsInstance(instance.id, {
          ...awsRequestScope(instance.region),
          instanceName: instance.name,
          confirmation,
        });
        updateAwsInstanceRow(response.data.instance);
        setAwsEc2ActionMessage(response.data.message);
      },
    });
  }

  function openAwsEc2Drawer(mode: AwsEc2DrawerMode, instance?: ResourceRecord) {
    setAwsEc2Drawer({ mode, instance });
    setAwsEc2ActionError('');
    setAwsEc2ActionMessage('');
    if (mode === 'create') {
      const region = awsPreferredCreateRegion();
      setAwsCreateInstanceForm({
        ...defaultAwsCreateInstanceForm,
        ...awsCreateDefaultsForRegion(region),
      });
      setAwsImageSearch('');
      setAwsImageOptions([]);
      setAwsKeyPairOptions([]);
      setAwsNewKeyPairName('');
      setAwsCreatedKeyMaterial('');
      void loadAwsImageOptions(region, '');
      void loadAwsKeyPairOptions(region);
    }
    if (mode === 'ami') {
      setAwsAmiForm({
        ...defaultAwsAmiForm,
        name: `${instance?.name || instance?.id || 'instance'}-${new Date().toISOString().slice(0, 10)}`,
      });
    }
    if (mode === 'type') {
      setAwsTypeForm({ instanceType: String(instance?.shape || 't3.micro') });
    }
    if (mode === 'volume') {
      const availableVolume = awsAvailableVolumeOptions.find((volume) =>
        String(volume.status || '').toLowerCase() === 'available'
        && (!instance?.availabilityDomain || volume.availabilityDomain === instance.availabilityDomain),
      );
      setAwsVolumeForm({
        ...defaultAwsVolumeForm,
        volumeId: availableVolume?.id || '',
      });
    }
  }

