  function openAwsDeleteNetworkResource(resource: ResourceRecord) {
    const type = String(resource.resourceType || resource.providerType || '');
    const labels: Record<string, string> = {
      vpc: 'VPC',
      subnet: 'subnet',
      routeTable: 'route table',
      internetGateway: 'internet gateway',
      natGateway: 'NAT gateway',
    };
    openSafetyDelete({
      title: `Delete AWS ${labels[type] || 'network resource'}`,
      eyebrow: 'AWS Network',
      message: 'This deletes the selected AWS network resource. AWS will reject the request if dependent resources still exist.',
      expected: String(resource.name || resource.id || ''),
      alternateExpected: String(resource.id || ''),
      details: [
        { label: 'Resource', value: resource.name || resource.id || '-' },
        { label: 'ID', value: resource.id || '-' },
        { label: 'Region', value: resource.region || '-' },
        { label: 'VPC', value: resource.vpcId || '-' },
      ],
      confirmLabel: 'Delete Resource',
      onConfirm: async (confirmation) => {
        const payload = { ...awsRequestScope(resource.region), resourceName: resource.name || resource.id, vpcId: resource.vpcId, confirmation };
        let response: { data: { message: string; [key: string]: ResourceRecord | string } };
        if (type === 'vpc') {
          response = await awsService.deleteAwsVpc(String(resource.id), payload);
          removeAwsNetworkRow(response.data.vpc as ResourceRecord);
        } else if (type === 'subnet') {
          response = await awsService.deleteAwsSubnet(String(resource.id), payload);
          removeAwsNetworkRow(response.data.subnet as ResourceRecord);
        } else if (type === 'routeTable') {
          response = await awsService.deleteAwsRouteTable(String(resource.id), payload);
          removeAwsNetworkRow(response.data.routeTable as ResourceRecord);
        } else if (type === 'internetGateway') {
          response = await awsService.deleteAwsInternetGateway(String(resource.id), payload);
          removeAwsNetworkRow(response.data.internetGateway as ResourceRecord);
        } else {
          response = await awsService.deleteAwsNatGateway(String(resource.id), payload);
          removeAwsNetworkRow(response.data.natGateway as ResourceRecord);
        }
        setAwsNetworkActionMessage(String(response.data.message || 'AWS network delete submitted.'));
        void loadAwsNetworkMap();
        void refreshAuditLog();
      },
    });
  }

