  async function submitAwsRdsCreate(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const region = awsRdsCreateForm.region || (awsInventoryRegion !== 'all' ? awsInventoryRegion : selectedAwsConnector?.region || '');
    setAwsDatabaseActionInFlight('create-rds');
    setAwsDatabaseActionError('');
    setAwsDatabaseActionMessage('');
    try {
      if (awsRdsCreateForm.multiAz && Number(awsRdsCreateForm.backupRetentionPeriod || 0) < 1) {
        throw new Error('Multi-AZ RDS instances require automated backup retention of at least 1 day.');
      }
      const response = await awsService.createAwsRdsInstance({
        ...awsRequestScope(region),
        dbInstanceIdentifier: awsRdsCreateForm.dbInstanceIdentifier,
        dbInstanceClass: awsRdsCreateForm.dbInstanceClass,
        engine: awsRdsCreateForm.engine,
        engineVersion: awsRdsCreateForm.engineVersion,
        allocatedStorage: awsRdsCreateForm.allocatedStorage,
        masterUsername: awsRdsCreateForm.masterUsername,
        masterUserPassword: awsRdsCreateForm.masterUserPassword,
        dbName: awsRdsCreateForm.dbName,
        storageType: awsRdsCreateForm.storageType,
        dbSubnetGroupName: awsRdsCreateForm.dbSubnetGroupName,
        vpcSecurityGroupIds: awsRdsCreateForm.vpcSecurityGroupId ? [awsRdsCreateForm.vpcSecurityGroupId] : [],
        publiclyAccessible: awsRdsCreateForm.publiclyAccessible,
        backupRetentionPeriod: awsRdsCreateForm.backupRetentionPeriod,
        multiAz: awsRdsCreateForm.multiAz,
      });
      updateAwsRdsRow(response.data.database);
      setAwsDatabaseActionMessage(response.data.message);
      setAwsRdsCreateForm((current) => ({ ...defaultAwsRdsCreateForm, region: current.region }));
      void refreshAuditLog();
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Unable to create RDS DB instance.';
      setAwsDatabaseActionError(
        /FreeTierRestriction|backup retention period exceeds/i.test(message)
          ? `${message} Set Automated backups to Disabled or 1 day, then retry.`
          : message,
      );
    } finally {
      setAwsDatabaseActionInFlight('');
    }
  }

