  function updateOciVmRow(instanceId: string, updates: Partial<ResourceRecord>) {
    setOciAllResources((current) => current
      ? {
          ...current,
          instances: current.instances.map((item) => item.id === instanceId ? { ...item, ...updates } : item),
        }
      : current);
    setResourceDetailTarget((current) => current?.id === instanceId ? { ...current, ...updates } : current);
  }

  async function pollOciVmStatus(vm: ResourceRecord, expectedStatus: string, action: 'start' | 'stop' | 'reboot') {
    if (!vm.id || !vm.region) {
      return;
    }

    for (let attempt = 0; attempt < 24; attempt += 1) {
      await new Promise((resolve) => window.setTimeout(resolve, attempt === 0 ? 3000 : 5000));
      try {
        const response = await ociService.getOciVmStatus(vm.id, vm.region);
        const latest = response.data.instance;
        updateOciVmRow(vm.id, {
          ...latest,
          compartmentName: vm.compartmentName || latest.compartmentName,
          privateIp: vm.privateIp || latest.privateIp,
          publicIp: vm.publicIp || latest.publicIp,
        });
        const status = String(latest.status || '').toUpperCase();
        if (status === expectedStatus || (action === 'reboot' && status === 'RUNNING' && attempt > 0)) {
          setOciVmActionMessage(`${vm.name || 'OCI VM'} is now ${status}.`);
          return;
        }
      } catch (err) {
        setOciVmActionError(err instanceof Error ? err.message : 'Unable to refresh OCI VM status.');
        return;
      }
    }
    setOciVmActionMessage(`${vm.name || 'OCI VM'} action was submitted. Status is still updating in OCI.`);
  }

  async function runOciVmQuickAction(vm: ResourceRecord, action: 'start' | 'stop' | 'reboot') {
    if (!vm.id || !vm.region) {
      setOciVmActionError('VM OCID and region are required.');
      return;
    }
    const key = `${action}:${vm.id}`;
    setOciVmActionInFlight(key);
    setOciVmActionError('');
    setOciVmActionMessage('');
    try {
      const response = await ociService.runOciVmAction(vm.id, action, vm.region);
      setOciVmActionMessage(response.data.message);
      const nextStatus = action === 'start' ? 'STARTING' : action === 'stop' ? 'STOPPING' : 'REBOOTING';
      updateOciVmRow(vm.id, { status: nextStatus });
      void refreshAuditLog();
      await pollOciVmStatus(vm, action === 'stop' ? 'STOPPED' : 'RUNNING', action);
    } catch (err) {
      setOciVmActionError(err instanceof Error ? err.message : 'Unable to run OCI VM action.');
    } finally {
      setOciVmActionInFlight('');
    }
  }

  function upsertOciCustomImage(image: OciCustomImage) {
    if (!image.id) {
      return;
    }
    setOciCustomImages((current) => {
      const existing = current.find((item) => item.id === image.id);
      const merged = existing
        ? {
            ...existing,
            ...image,
            sourceInstanceId: image.sourceInstanceId || existing.sourceInstanceId,
            sourceInstanceName: image.sourceInstanceName || existing.sourceInstanceName,
          }
        : image;
      return [merged, ...current.filter((item) => item.id !== image.id)]
        .sort((left, right) => String(right.createdAt || '').localeCompare(String(left.createdAt || '')));
    });
  }

  async function pollOciCustomImage(image: OciCustomImage) {
    if (!image.id || !image.region) {
      return;
    }

    for (let attempt = 0; attempt < 36; attempt += 1) {
      await new Promise((resolve) => window.setTimeout(resolve, attempt === 0 ? 5000 : 10000));
      try {
        const response = await ociService.getOciCustomImageStatus(image.id, image.region);
        const latest = {
          ...response.data.image,
          sourceInstanceId: image.sourceInstanceId,
          sourceInstanceName: image.sourceInstanceName,
        };
        upsertOciCustomImage(latest);
        const status = String(latest.status || '').toUpperCase();
        if (status === 'AVAILABLE' || status === 'FAILED') {
          setOciVmActionMessage(`${latest.name || 'Custom image'} is ${status}.`);
          return;
        }
      } catch (err) {
        setOciCustomImagesError(err instanceof Error ? err.message : 'Unable to refresh custom image status.');
        return;
      }
    }
  }

  async function loadOciCustomImagesForVisibleScope() {
    if (!selectedOciConnector || selectedOciConnector.status !== 'verified') {
      setOciCustomImages([]);
      setOciCustomImagesError(selectedOciConnector ? 'Verify the selected OCI connector to load custom images.' : 'No OCI connector selected.');
      return;
    }

    const scopeKeys = new Set<string>();
    const selectedCompartment = ociVmCompartmentFilter === 'all'
      ? null
      : ociVmCompartmentOptions.find((compartment) => compartment.id === ociVmCompartmentFilter || compartment.path === ociVmCompartmentFilter)
        || ociCompartmentTree.find((compartment) => compartment.id === ociVmCompartmentFilter || compartment.path === ociVmCompartmentFilter)
        || null;
    const selectedCompartmentId = selectedCompartment?.id || '';
    const selectedCompartmentPath = 'path' in (selectedCompartment || {}) ? selectedCompartment?.path || '' : '';
    ociManagedVmRows.forEach((row) => {
      if (!row.region || !row.compartmentId) {
        return;
      }
      if (ociAllResourcesRegion !== 'all' && row.region !== ociAllResourcesRegion) {
        return;
      }
      const rowPath = row.compartmentId ? ociCompartmentPathById.get(row.compartmentId) || row.compartmentName || '' : row.compartmentName || '';
      if (
        ociVmCompartmentFilter !== 'all'
        && row.compartmentId !== ociVmCompartmentFilter
        && row.compartmentId !== selectedCompartmentId
        && rowPath !== ociVmCompartmentFilter
        && rowPath !== selectedCompartmentPath
      ) {
        return;
      }
      scopeKeys.add(`${row.region}|${row.compartmentId}`);
    });

    if (scopeKeys.size === 0 && ociAllResourcesRegion !== 'all' && selectedCompartmentId) {
      scopeKeys.add(`${ociAllResourcesRegion}|${selectedCompartmentId}`);
    }

    if (scopeKeys.size === 0) {
      setOciCustomImages([]);
      setOciCustomImagesError('Run an OCI scan or choose a specific region and compartment to load custom images.');
      return;
    }

    setOciCustomImagesLoading(true);
    setOciCustomImagesError('');
    try {
      const responses = await Promise.all(
        Array.from(scopeKeys).map((key) => {
          const [region, compartmentId] = key.split('|');
          return ociService.getOciCustomImages(region, compartmentId);
        }),
      );
      const images = responses.flatMap((response) => response.data.images);
      setOciCustomImages(images.sort((left, right) => String(right.createdAt || '').localeCompare(String(left.createdAt || ''))));
      const errors = responses.flatMap((response) => response.data.errors || []);
      setOciCustomImagesError(errors[0]?.message || '');
    } catch (err) {
      setOciCustomImagesError(err instanceof Error ? err.message : 'Unable to load custom images.');
    } finally {
      setOciCustomImagesLoading(false);
    }
  }

  function ociImageDeleteConfirmationMatches() {
    if (!ociImageDeleteTarget) {
      return false;
    }
    const typed = ociImageDeleteConfirmation.trim();
    return typed === ociImageDeleteTarget.id || typed === String(ociImageDeleteTarget.name || '').trim();
  }

  async function submitOciImageDelete() {
    if (!ociImageDeleteTarget?.id || !ociImageDeleteTarget.region) {
      setOciCustomImagesError('Custom image OCID and region are required.');
      return;
    }
    if (!ociImageDeleteConfirmationMatches()) {
      setOciCustomImagesError('Type the custom image name or OCID to confirm deletion.');
      return;
    }

    setOciImageDeleting(true);
    setOciCustomImagesError('');
    try {
      const response = await ociService.deleteOciCustomImage(ociImageDeleteTarget.id, {
        region: ociImageDeleteTarget.region,
        compartmentId: ociImageDeleteTarget.compartmentId,
        imageName: ociImageDeleteTarget.name || ociImageDeleteTarget.id,
        confirmation: ociImageDeleteConfirmation.trim(),
      });
      setOciCustomImages((current) => current.filter((image) => image.id !== ociImageDeleteTarget.id));
      setOciVmActionMessage(response.data.message);
      setOciImageDeleteTarget(null);
      setOciImageDeleteConfirmation('');
      dashboardService
        .getAuditLog()
        .then((auditResponse) => setAuditLog(auditResponse.entries))
        .catch(() => undefined);
    } catch (err) {
      setOciCustomImagesError(err instanceof Error ? err.message : 'Unable to delete custom image.');
    } finally {
      setOciImageDeleting(false);
    }
  }

  function openOciCreateVm() {
    const region = ociAllResourcesRegion !== 'all'
      ? ociAllResourcesRegion
      : filteredOciManagedVmRows[0]?.region || ociManagedVmRows[0]?.region || selectedOciConnector?.region || '';
    const selectedFilterCompartment = ociVmCompartmentFilter !== 'all'
      ? selectedOciVmCompartmentFilter?.id || ociVmCompartmentFilter
      : '';
    const compartment = ociVmCompartmentFilter !== 'all'
      ? selectedFilterCompartment
      : filteredOciManagedVmRows[0]?.compartmentId
        || ociManagedVmRows[0]?.compartmentId
        || selectedOciConnector?.compartmentOcid
        || ociCompartmentTree[0]?.id
        || selectedOciConnector?.tenancyOcid
        || '';
    const scopedVms = ociManagedVmRows.filter((vm) =>
      (!region || vm.region === region)
      && (!compartment || vm.compartmentId === compartment || vm.compartmentName === compartment),
    );
    const regionSubnets = (ociAllResources?.subnets || []).filter((subnet) => !region || subnet.region === region);
    const scopedSubnets = regionSubnets.filter((subnet) => !compartment || subnet.compartmentId === compartment);
    const scopedImages = filteredOciCustomImages.filter((image) =>
      (!region || image.region === region)
      && (!compartment || image.compartmentId === compartment),
    );
    const networkCompartmentId = scopedSubnets[0]?.compartmentId || regionSubnets[0]?.compartmentId || compartment;
    setOciCreateVmForm({
      ...defaultOciCreateVmForm(),
      region,
      compartmentId: compartment,
      networkCompartmentId,
      availabilityDomain: scopedVms[0]?.availabilityDomain || ociManagedVmRows.find((vm) => vm.region === region)?.availabilityDomain || '',
      shape: scopedVms[0]?.shape || 'VM.Standard.E5.Flex',
      subnetId: scopedSubnets[0]?.id || regionSubnets[0]?.id || '',
      imageId: scopedImages[0]?.id || filteredOciCustomImages.find((image) => !region || image.region === region)?.id || '',
    });
    setOciCreateVmError('');
    setOciLaunchOptions(null);
    setOciCreateVmOpen(true);
  }

  function updateOciCreateVmField<K extends keyof OciCreateVmForm>(key: K, value: OciCreateVmForm[K]) {
    setOciCreateVmForm((current) => {
      const next = { ...current, [key]: value };
      if (key === 'region' && value !== current.region) {
        next.availabilityDomain = '';
        next.imageId = '';
        next.subnetId = '';
        next.networkCompartmentId = '';
      }
      if (key === 'compartmentId' && value !== current.compartmentId) {
        next.availabilityDomain = '';
        next.imageId = '';
        next.subnetId = '';
        next.networkCompartmentId = current.networkCompartmentId || String(value || '');
      }
      if (key === 'networkCompartmentId' && value !== current.networkCompartmentId) {
        next.subnetId = '';
      }
      return next;
    });
  }

  useEffect(() => {
    if (!ociCreateVmOpen || !ociCreateVmForm.region) {
      return;
    }

    let isCurrent = true;
    setOciCreateVmAdLoading(true);
    ociService
      .getOciAvailabilityDomains(ociCreateVmForm.region)
      .then((response) => {
        if (!isCurrent) {
          return;
        }
        const domains = response.data.availabilityDomains || [];
        setOciCreateVmAdRegion(response.data.region);
        setOciCreateVmAvailabilityDomains(domains);
        setOciCreateVmForm((current) => {
          if (current.region !== response.data.region || current.availabilityDomain || domains.length === 0) {
            return current;
          }
          return { ...current, availabilityDomain: domains[0] };
        });
      })
      .catch(() => {
        if (!isCurrent) {
          return;
        }
        setOciCreateVmAdRegion('');
        setOciCreateVmAvailabilityDomains([]);
      })
      .finally(() => {
        if (isCurrent) {
          setOciCreateVmAdLoading(false);
        }
      });

    return () => {
      isCurrent = false;
    };
  }, [ociCreateVmOpen, ociCreateVmForm.region]);

  useEffect(() => {
    if (!ociCreateVmOpen || !ociCreateVmForm.region || !ociCreateVmForm.compartmentId) {
      return;
    }

    let isCurrent = true;
    setOciLaunchOptionsLoading(true);
    ociService
      .getOciLaunchOptions(
        ociCreateVmForm.region,
        ociCreateVmForm.compartmentId,
        ociCreateVmForm.availabilityDomain,
        ociCreateVmForm.networkCompartmentId || ociCreateVmForm.compartmentId,
      )
      .then((response) => {
        if (!isCurrent) {
          return;
        }
        const options = response.data;
        setOciLaunchOptions(options);
        setOciCreateVmForm((current) => {
          if (current.region !== options.region || current.compartmentId !== options.compartmentId) {
            return current;
          }
          const ad = current.availabilityDomain || options.availabilityDomains[0] || '';
          const shapeNames = new Set(options.shapes.map((shape) => shape.name).filter(Boolean));
          const imageIds = new Set(options.images.map((image) => image.id).filter(Boolean));
          const subnetIds = new Set(options.subnets.map((subnet) => subnet.id).filter(Boolean));
          return {
            ...current,
            availabilityDomain: ad,
            networkCompartmentId: current.networkCompartmentId || options.networkCompartmentId || current.compartmentId,
            shape: current.shape && (shapeNames.size === 0 || shapeNames.has(current.shape)) ? current.shape : options.shapes[0]?.name || current.shape,
            imageId: current.imageId && (imageIds.size === 0 || imageIds.has(current.imageId)) ? current.imageId : options.images[0]?.id || current.imageId,
            subnetId: current.subnetId && (subnetIds.size === 0 || subnetIds.has(current.subnetId)) ? current.subnetId : options.subnets[0]?.id || current.subnetId,
          };
        });
        if (options.errors?.length) {
          setOciCreateVmError(options.errors[0].message || 'Some OCI launch options could not be loaded.');
        } else {
          setOciCreateVmError('');
        }
      })
      .catch((err) => {
        if (!isCurrent) {
          return;
        }
        setOciLaunchOptions(null);
        setOciCreateVmError(err instanceof Error ? err.message : 'Unable to load OCI launch options.');
      })
      .finally(() => {
        if (isCurrent) {
          setOciLaunchOptionsLoading(false);
        }
      });

    return () => {
      isCurrent = false;
    };
  }, [ociCreateVmOpen, ociCreateVmForm.region, ociCreateVmForm.compartmentId, ociCreateVmForm.networkCompartmentId]);

  useEffect(() => {
    if (!ociDbSystemCreateOpen || !ociDbSystemCreateForm.region || !ociDbSystemCreateForm.compartmentId) {
      return;
    }

    let isCurrent = true;
    setOciLaunchOptionsLoading(true);
    ociService
      .getOciLaunchOptions(
        ociDbSystemCreateForm.region,
        ociDbSystemCreateForm.compartmentId,
        ociDbSystemCreateForm.availabilityDomain,
        ociDbSystemCreateForm.networkCompartmentId || ociDbSystemCreateForm.compartmentId,
      )
      .then((response) => {
        if (!isCurrent) {
          return;
        }
        const options = response.data;
        setOciLaunchOptions(options);
        setOciDbSystemCreateForm((current) => {
          if (current.region !== options.region || current.compartmentId !== options.compartmentId) {
            return current;
          }
          const shapeNames = new Set(options.shapes.map((shape) => shape.name).filter(Boolean));
          const subnetIds = new Set(options.subnets.map((subnet) => subnet.id).filter(Boolean));
          return {
            ...current,
            availabilityDomain: current.availabilityDomain || options.availabilityDomains[0] || '',
            networkCompartmentId: current.networkCompartmentId || options.networkCompartmentId || current.compartmentId,
            shape: current.shape && (shapeNames.size === 0 || shapeNames.has(current.shape)) ? current.shape : options.shapes[0]?.name || current.shape,
            subnetId: current.subnetId && (subnetIds.size === 0 || subnetIds.has(current.subnetId)) ? current.subnetId : options.subnets[0]?.id || current.subnetId,
          };
        });
        setOciDbSystemCreateError(options.errors?.[0]?.message || '');
      })
      .catch((err) => {
        if (!isCurrent) {
          return;
        }
        setOciLaunchOptions(null);
        setOciDbSystemCreateError(err instanceof Error ? err.message : 'Unable to load DB System launch options.');
      })
      .finally(() => {
        if (isCurrent) {
          setOciLaunchOptionsLoading(false);
        }
      });

    return () => {
      isCurrent = false;
    };
  }, [ociDbSystemCreateOpen, ociDbSystemCreateForm.region, ociDbSystemCreateForm.compartmentId, ociDbSystemCreateForm.networkCompartmentId]);

  useEffect(() => {
    if (!ociDbSystemCreateOpen || !ociDbSystemCreateForm.region || !ociDbSystemCreateForm.compartmentId) {
      setOciDbSystemVersions([]);
      return;
    }

    let isCurrent = true;
    setOciDbSystemVersionsLoading(true);
    ociService
      .getOciDbVersions({
        region: ociDbSystemCreateForm.region,
        compartmentId: ociDbSystemCreateForm.compartmentId,
        dbSystemShape: ociDbSystemCreateForm.shape,
        storageManagement: ociDbSystemCreateForm.storageManagement,
      })
      .then((response) => {
        if (!isCurrent) {
          return;
        }
        const versions = response.data.versions || [];
        setOciDbSystemVersions(versions);
        setOciDbSystemCreateForm((current) => {
          const available = new Set(versions.map((version) => version.version));
          if (versions.length === 0 || (current.dbVersion && available.has(current.dbVersion))) {
            return current;
          }
          return { ...current, dbVersion: versions[0].version };
        });
      })
      .catch(() => {
        if (isCurrent) {
          setOciDbSystemVersions([]);
        }
      })
      .finally(() => {
        if (isCurrent) {
          setOciDbSystemVersionsLoading(false);
        }
      });

    return () => {
      isCurrent = false;
    };
  }, [ociDbSystemCreateOpen, ociDbSystemCreateForm.region, ociDbSystemCreateForm.compartmentId, ociDbSystemCreateForm.shape, ociDbSystemCreateForm.storageManagement]);

  async function submitOciCreateVm() {
    const required: Array<[keyof OciCreateVmForm, string]> = [
      ['displayName', 'VM name is required.'],
      ['region', 'Region is required.'],
      ['compartmentId', 'Compartment is required.'],
      ['availabilityDomain', 'Availability domain is required.'],
      ['shape', 'Shape is required.'],
      ['imageId', 'Image OCID is required.'],
      ['subnetId', 'Subnet OCID is required.'],
    ];
    const missing = required.find(([key]) => !String(ociCreateVmForm[key] || '').trim());
    if (missing) {
      setOciCreateVmError(missing[1]);
      return;
    }
    setOciCreateVmSubmitting(true);
    setOciCreateVmError('');
    try {
      const response = await ociService.createOciVm(ociCreateVmForm);
      const instance = {
        ...response.data.instance,
        compartmentName: ociCompartmentPathById.get(ociCreateVmForm.compartmentId) || ociCreateVmForm.compartmentId,
      };
      setOciVmActionMessage(response.data.message);
      setOciCreateVmOpen(false);
      setOciAllResources((current) => {
        if (!current) {
          return current;
        }
        return {
          ...current,
          summary: {
            ...current.summary,
            instances: current.summary.instances + 1,
          },
          instances: [instance, ...current.instances.filter((item) => item.id !== instance.id)],
        };
      });
      if (instance.id && instance.region) {
        updateOciVmRow(instance.id, instance);
        void pollOciVmStatus(instance, 'RUNNING', 'start');
      }
    } catch (err) {
      setOciCreateVmError(err instanceof Error ? err.message : 'Unable to create OCI VM.');
    } finally {
      setOciCreateVmSubmitting(false);
    }
  }

  function openOciVmAction(vm: ResourceRecord, action: 'terminate' | 'image' | 'move') {
    setOciVmActionTarget(vm);
    setOciVmActionType(action);
    setOciVmActionInput(action === 'image' ? `${vm.name || 'oci-vm'}-image` : '');
    setOciVmActionError('');
    setOciVmActionMessage('');
  }

  function openOciVmEdit(vm: ResourceRecord) {
    setOciVmEditTarget(vm);
    setOciVmEditForm(defaultOciEditVmForm(vm));
    setOciVmEditError('');
    setOciVmActionMessage('');
    setOciVmActionError('');
  }

  async function submitOciVmEdit() {
    if (!ociVmEditTarget?.id || !ociVmEditTarget.region) {
      setOciVmEditError('VM OCID and region are required.');
      return;
    }
    const displayName = ociVmEditForm.displayName.trim();
    const shape = ociVmEditForm.shape.trim();
    const ocpus = Number(ociVmEditForm.ocpus);
    const memoryGb = Number(ociVmEditForm.memoryGb);
    if (!displayName || !shape) {
      setOciVmEditError('VM name and shape are required.');
      return;
    }
    if (!Number.isFinite(ocpus) || ocpus <= 0) {
      setOciVmEditError('OCPU count must be greater than zero.');
      return;
    }
    if (!Number.isFinite(memoryGb) || memoryGb <= 0) {
      setOciVmEditError('Memory must be greater than zero.');
      return;
    }

    setOciVmEditSubmitting(true);
    setOciVmEditError('');
    try {
      const response = await ociService.updateOciVm(ociVmEditTarget.id, {
        region: ociVmEditTarget.region,
        displayName,
        shape,
        ocpus: String(ocpus),
        memoryGb: String(memoryGb),
      });
      const latest = {
        ...response.data.instance,
        compartmentName: ociVmEditTarget.compartmentName || response.data.instance.compartmentName,
        privateIp: ociVmEditTarget.privateIp || response.data.instance.privateIp,
        publicIp: ociVmEditTarget.publicIp || response.data.instance.publicIp,
      };
      updateOciVmRow(ociVmEditTarget.id, latest);
      setOciVmActionMessage(response.data.message);
      setOciVmEditTarget(null);
    } catch (err) {
      setOciVmEditError(err instanceof Error ? err.message : 'Unable to update OCI VM configuration.');
    } finally {
      setOciVmEditSubmitting(false);
    }
  }

  async function submitOciVmAction() {
    if (!ociVmActionTarget?.id || !ociVmActionTarget.region || !ociVmActionType) {
      setOciVmActionError('VM OCID, region, and action are required.');
      return;
    }

    setOciVmActionInFlight(`${ociVmActionType}:${ociVmActionTarget.id}`);
    setOciVmActionError('');
    setOciVmActionMessage('');
    try {
      const input = ociVmActionInput.trim();
      const response = ociVmActionType === 'terminate'
        ? await ociService.terminateOciVm(ociVmActionTarget.id, {
            region: ociVmActionTarget.region,
            instanceName: ociVmActionTarget.name || ociVmActionTarget.id,
            confirmation: input,
          })
        : ociVmActionType === 'image'
          ? await ociService.createOciVmImage(ociVmActionTarget.id, {
              region: ociVmActionTarget.region,
              compartmentId: ociVmActionTarget.compartmentId || '',
              displayName: input,
              instanceName: ociVmActionTarget.name || '',
            })
          : await ociService.moveOciVm(ociVmActionTarget.id, {
              region: ociVmActionTarget.region,
              targetCompartmentId: input,
            });
      setOciVmActionMessage(response.data.message);
      const imageResponse = response.data as { image?: OciCustomImage };
      if (ociVmActionType === 'image' && imageResponse.image?.id) {
        const image = {
          ...imageResponse.image,
          sourceInstanceId: ociVmActionTarget.id,
          sourceInstanceName: ociVmActionTarget.name || ociVmActionTarget.id,
        };
        upsertOciCustomImage(image);
        void pollOciCustomImage(image);
      }
      void refreshAuditLog();
      setOciVmActionTarget(null);
      setOciVmActionType(null);
      setOciVmActionInput('');
      setOciAllResources((current) => {
        if (!current) {
          return current;
        }
        if (ociVmActionType === 'terminate') {
          return {
            ...current,
            summary: {
              ...current.summary,
              instances: Math.max(0, current.summary.instances - 1),
              runningInstances: String(ociVmActionTarget.status || '').toUpperCase() === 'RUNNING'
                ? Math.max(0, current.summary.runningInstances - 1)
                : current.summary.runningInstances,
              stoppedInstances: ['STOPPED', 'STOPPING'].includes(String(ociVmActionTarget.status || '').toUpperCase())
                ? Math.max(0, current.summary.stoppedInstances - 1)
                : current.summary.stoppedInstances,
            },
            instances: current.instances.filter((item) => item.id !== ociVmActionTarget.id),
          };
        }
        return current;
      });
    } catch (err) {
      setOciVmActionError(err instanceof Error ? err.message : 'Unable to submit OCI VM action.');
    } finally {
      setOciVmActionInFlight('');
    }
  }

  function upsertOciVolumeRow(volume: ResourceRecord, resourceType: 'blockVolume' | 'bootVolume') {
    if (!volume.id) {
      return;
    }
    const normalizedVolume = { ...volume, providerType: resourceType, resourceType };
    setOciVolumeOverrides((current) => ({
      ...current,
      [String(volume.id)]: normalizedVolume,
    }));
    const listKey = resourceType === 'bootVolume' ? 'bootVolumes' : 'blockVolumes';
    setOciAllResources((current) => {
      if (!current) {
        return current;
      }
      const existing = current[listKey].find((item) => item.id === volume.id);
      const merged = existing ? { ...existing, ...normalizedVolume } : normalizedVolume;
      return {
        ...current,
        summary: {
          ...current.summary,
          [listKey]: existing ? current.summary[listKey] : current.summary[listKey] + 1,
        },
        [listKey]: [merged, ...current[listKey].filter((item) => item.id !== volume.id)],
      };
    });
  }

  async function loadOciVolumeBackups(volume: ResourceRecord, volumeType: ociService.OciVolumeType) {
    const volumeId = volume.id || '';
    const region = volume.region || '';
    const compartmentId = volume.compartmentId || '';
    setOciVolumeBackups([]);
    if (!volumeId || !region || !compartmentId) {
      setOciVolumeError('Volume OCID, region, and compartment are required to list backups.');
      return;
    }
    setOciVolumeBackupsLoading(true);
    try {
      const response = await ociService.getOciVolumeBackups(volumeType, volumeId, region, compartmentId);
      const backups = response.data.backups || [];
      setOciVolumeBackups(backups);
      setOciVolumeForm((current) => ({
        ...current,
        backupId: backups[0]?.id || '',
      }));
      if (!backups.length) {
        setOciVolumeError('No backups were found for this volume.');
      }
    } catch (err) {
      setOciVolumeError(err instanceof Error ? err.message : 'Unable to load available volume backups.');
    } finally {
      setOciVolumeBackupsLoading(false);
    }
  }

  function getOciVolumeCatalogScopes() {
    const scopeMap = new Map<string, { region: string; compartmentId: string }>();
    filteredOciVolumeRows.forEach((volume) => {
      const region = volume.region || '';
      const compartmentId = volume.compartmentId
        || ociVolumeCompartmentOptions.find((compartment) => compartment.name === volume.compartmentName || compartment.path === volume.compartmentName)?.id
        || '';
      if (region && compartmentId) {
        scopeMap.set(`${region}|${compartmentId}`, { region, compartmentId });
      }
    });
    if (scopeMap.size === 0 && ociVolumeRegionFilter !== 'all' && ociVolumeCompartmentFilter !== 'all') {
      scopeMap.set(`${ociVolumeRegionFilter}|${ociVolumeCompartmentFilter}`, {
        region: ociVolumeRegionFilter,
        compartmentId: ociVolumeCompartmentFilter,
      });
    }

    return Array.from(scopeMap.values());
  }

  async function loadOciVolumeBackupCatalog() {
    if (!selectedOciConnector || selectedOciConnector.status !== 'verified') {
      setOciVolumeBackupCatalogError(selectedOciConnector ? 'Verify the selected OCI connector to load volume backups.' : 'Select an OCI connector to load volume backups.');
      setOciBlockVolumeBackups([]);
      setOciBootVolumeBackups([]);
      return;
    }

    const scopes = getOciVolumeCatalogScopes();
    if (!scopes.length) {
      setOciBlockVolumeBackups([]);
      setOciBootVolumeBackups([]);
      setOciVolumeBackupCatalogError('Select a region and compartment, or scan volumes first, to load backup catalogs.');
      return;
    }

    setOciVolumeBackupCatalogLoading(true);
    setOciVolumeBackupCatalogError('');
    try {
      const blockBackups: ociService.OciVolumeBackup[] = [];
      const bootBackups: ociService.OciVolumeBackup[] = [];
      const failures: string[] = [];

      await Promise.all(scopes.flatMap((scope) => [
        ociService.getOciVolumeBackupsForCompartment('block', scope.region, scope.compartmentId)
          .then((response) => {
            blockBackups.push(...(response.data.backups || []));
          })
          .catch((err) => {
            failures.push(`${scope.region} block backups: ${err instanceof Error ? err.message : 'Unable to load backups.'}`);
          }),
        ociService.getOciVolumeBackupsForCompartment('boot', scope.region, scope.compartmentId)
          .then((response) => {
            bootBackups.push(...(response.data.backups || []));
          })
          .catch((err) => {
            failures.push(`${scope.region} boot backups: ${err instanceof Error ? err.message : 'Unable to load backups.'}`);
          }),
      ]));

      const sortBackups = (rows: ociService.OciVolumeBackup[]) =>
        Array.from(new Map(rows.filter((backup) => backup.id).map((backup) => [backup.id, backup])).values())
          .sort((left, right) => String(right.createdAt || '').localeCompare(String(left.createdAt || '')));
      setOciBlockVolumeBackups(sortBackups(blockBackups));
      setOciBootVolumeBackups(sortBackups(bootBackups));
      setOciVolumeBackupCatalogError(failures.length ? `Backup scan loaded with ${failures.length} warning${failures.length === 1 ? '' : 's'}. ${failures.slice(0, 3).join(' ')}` : '');
    } finally {
      setOciVolumeBackupCatalogLoading(false);
    }
  }

  async function loadOciVolumeGroupCatalog() {
    if (!selectedOciConnector || selectedOciConnector.status !== 'verified') {
      setOciVolumeGroupCatalogError(selectedOciConnector ? 'Verify the selected OCI connector to load volume groups.' : 'Select an OCI connector to load volume groups.');
      setOciVolumeGroups([]);
      setOciVolumeGroupBackups([]);
      setOciVolumeGroupReplicas([]);
      return;
    }

    const scopes = getOciVolumeCatalogScopes();
    if (!scopes.length) {
      setOciVolumeGroups([]);
      setOciVolumeGroupBackups([]);
      setOciVolumeGroupReplicas([]);
      setOciVolumeGroupCatalogError('Select a region and compartment, or scan volumes first, to load volume group catalogs.');
      return;
    }

    setOciVolumeGroupCatalogLoading(true);
    setOciVolumeGroupCatalogError('');
    try {
      const groups: ociService.OciVolumeGroupResource[] = [];
      const backups: ociService.OciVolumeGroupResource[] = [];
      const replicas: ociService.OciVolumeGroupResource[] = [];
      const failures: string[] = [];

      await Promise.all(scopes.flatMap((scope) => [
        ociService.getOciVolumeGroupResources('volumeGroup', scope.region, scope.compartmentId)
          .then((response) => groups.push(...(response.data.resources || [])))
          .catch((err) => failures.push(`${scope.region} volume groups: ${err instanceof Error ? err.message : 'Unable to load volume groups.'}`)),
        ociService.getOciVolumeGroupResources('volumeGroupBackup', scope.region, scope.compartmentId)
          .then((response) => backups.push(...(response.data.resources || [])))
          .catch((err) => failures.push(`${scope.region} volume group backups: ${err instanceof Error ? err.message : 'Unable to load volume group backups.'}`)),
        ociService.getOciVolumeGroupResources('volumeGroupReplica', scope.region, scope.compartmentId)
          .then((response) => replicas.push(...(response.data.resources || [])))
          .catch((err) => failures.push(`${scope.region} volume group replicas: ${err instanceof Error ? err.message : 'Unable to load volume group replicas.'}`)),
      ]));

      const sortRows = (rows: ociService.OciVolumeGroupResource[]) =>
        Array.from(new Map(rows.filter((item) => item.id).map((item) => [item.id, item])).values())
          .sort((left, right) => String(right.createdAt || '').localeCompare(String(left.createdAt || '')));
      setOciVolumeGroups(sortRows(groups));
      setOciVolumeGroupBackups(sortRows(backups));
      setOciVolumeGroupReplicas(sortRows(replicas));
      setOciVolumeGroupCatalogError(failures.length ? `Volume group scan loaded with ${failures.length} warning${failures.length === 1 ? '' : 's'}. ${failures.slice(0, 3).join(' ')}` : '');
    } finally {
      setOciVolumeGroupCatalogLoading(false);
    }
  }

  async function loadOciFileStorageCatalog() {
    if (!selectedOciConnector || selectedOciConnector.status !== 'verified') {
      setOciFileStorageError(selectedOciConnector ? 'Verify the selected OCI connector to load file systems.' : 'Select an OCI connector to load file systems.');
      return;
    }
    const region = ociFileSystemRegionFilter || ociAllResourcesRegion;
    const compartmentId = ociFileSystemCompartmentFilter;
    if (!region || region === 'all' || !compartmentId || compartmentId === 'all') {
      setOciFileStorageError('Select one region and one compartment to load OCI File Storage resources.');
      setOciFileSystems([]);
      setOciMountTargets([]);
      setOciFileExports([]);
      setOciFileSnapshots([]);
      return;
    }

    setOciFileStorageLoading(true);
    setOciFileStorageError('');
    try {
      const response = await ociService.getOciFileStorageResources(region, compartmentId);
      setOciFileSystems(response.data.fileSystems || []);
      setOciMountTargets(response.data.mountTargets || []);
      setOciFileExports(response.data.exports || []);
      setOciFileSnapshots(response.data.snapshots || []);
      const errors = response.data.errors || [];
      setOciFileStorageError(errors.length ? `File Storage loaded with ${errors.length} warning${errors.length === 1 ? '' : 's'}. ${errors.slice(0, 3).map((item) => item.message).join(' ')}` : '');
    } catch (err) {
      setOciFileSystems([]);
      setOciMountTargets([]);
      setOciFileExports([]);
      setOciFileSnapshots([]);
      setOciFileStorageError(err instanceof Error ? err.message : 'Unable to load OCI File Storage resources.');
    } finally {
      setOciFileStorageLoading(false);
    }
  }

