  async function submitOciBucketCreate() {
    const name = ociBucketForm.name.trim();
    if (!ociBucketForm.region || !ociBucketForm.compartmentId || !name) {
      setOciBucketCreateError('Region, compartment, and bucket name are required.');
      return;
    }
    if (!/^[a-zA-Z0-9._-]{1,256}$/.test(name)) {
      setOciBucketCreateError('Bucket name can use letters, numbers, dots, underscores, and hyphens.');
      return;
    }
    setOciBucketCreating(true);
    setOciBucketCreateError('');
    try {
      const response = await ociService.createOciBucket({ ...ociBucketForm, name });
      const bucket = response.data.bucket;
      setOciObjectBuckets((current) => [bucket, ...current.filter((item) => (item.id || item.name) !== (bucket.id || bucket.name))]);
      setOciAllResources((current) => current ? {
        ...current,
        summary: { ...current.summary, buckets: current.buckets.some((item) => (item.id || item.name) === (bucket.id || bucket.name)) ? current.summary.buckets : current.summary.buckets + 1 },
        buckets: [bucket, ...current.buckets.filter((item) => (item.id || item.name) !== (bucket.id || bucket.name))],
      } : current);
      setOciVmActionMessage(response.data.message);
      setOciBucketCreateOpen(false);
    } catch (err) {
      setOciBucketCreateError(err instanceof Error ? err.message : 'Unable to create OCI bucket.');
    } finally {
      setOciBucketCreating(false);
    }
  }

