  async function submitOciDatabaseDelete() {
    const databaseId = ociDatabaseDeleteTarget?.database.id;
    if (!databaseId) {
      return;
    }
    const database = ociDatabaseDeleteTarget.database;
    const resourceType = ociDatabaseDeleteTarget.resourceType;
    const expectedName = String(database.name || database.dbName || '').trim();
    const confirmation = ociDatabaseDeleteConfirmation.trim();
    if (confirmation !== databaseId && (!expectedName || confirmation !== expectedName)) {
      setOciDatabaseDeleteError('Type the database name or OCID to confirm deletion.');
      return;
    }
    setOciDatabaseDeleting(true);
    setOciDatabaseDeleteError('');
    try {
      const response = await ociService.deleteOciDatabase(databaseId, {
        region: database.region || ociDatabaseRegionFilter,
        databaseName: expectedName,
        resourceType,
        confirmation,
      });
      const deletedId = databaseId;
      setOciDatabaseResources((current) => current ? {
        ...current,
        dbSystems: resourceType === 'dbSystem' ? current.dbSystems.filter((item) => item.id !== deletedId) : current.dbSystems,
        autonomousDatabases: resourceType === 'autonomousDatabase' ? current.autonomousDatabases.filter((item) => item.id !== deletedId) : current.autonomousDatabases,
      } : current);
      setOciAllResources((current) => current ? {
        ...current,
        summary: {
          ...current.summary,
          dbSystems: resourceType === 'dbSystem' ? Math.max(0, (current.summary.dbSystems || 0) - 1) : current.summary.dbSystems,
          autonomousDatabases: resourceType === 'autonomousDatabase' ? Math.max(0, (current.summary.autonomousDatabases || 0) - 1) : current.summary.autonomousDatabases,
        },
        dbSystems: resourceType === 'dbSystem' ? (current.dbSystems || []).filter((item) => item.id !== deletedId) : current.dbSystems,
        autonomousDatabases: resourceType === 'autonomousDatabase' ? (current.autonomousDatabases || []).filter((item) => item.id !== deletedId) : current.autonomousDatabases,
      } : current);
      setOciDatabaseError(response.data.message);
      setOciDatabaseDeleteTarget(null);
      setOciDatabaseDeleteConfirmation('');
    } catch (err) {
      setOciDatabaseDeleteError(err instanceof Error ? err.message : 'Unable to delete OCI database.');
    } finally {
      setOciDatabaseDeleting(false);
    }
  }

  async function runOciAdbQuickAction(database: ResourceRecord, action: 'start' | 'stop') {
    if (!database.id || !database.region) {
      setOciDatabaseError('Database OCID and region are required.');
      return;
    }
    const nextStatus = action === 'start' ? 'STARTING' : 'STOPPING';
    updateOciAutonomousDatabaseRow({ ...database, status: nextStatus });
    setOciDatabaseError('');
    try {
      const response = await ociService.runOciAutonomousDatabaseAction(database.id, action, {
        region: database.region,
        databaseName: database.name || database.dbName || database.id,
      });
      updateOciAutonomousDatabaseRow({ ...database, ...response.data.database });
      setOciDatabaseError(response.data.message);
    } catch (err) {
      updateOciAutonomousDatabaseRow(database);
      setOciDatabaseError(err instanceof Error ? err.message : `Unable to ${action} Autonomous Database.`);
    }
  }

  function openOciAdbAction(database: ResourceRecord, action: OciAutonomousDatabaseLifecycleAction) {
    setOciAdbActionTarget(database);
    setOciAdbActionType(action);
    setOciAdbActionForm(defaultOciAutonomousDatabaseActionForm(database));
    setOciAdbActionError('');
  }

  function updateOciAdbActionField<K extends keyof OciAutonomousDatabaseActionForm>(key: K, value: OciAutonomousDatabaseActionForm[K]) {
    setOciAdbActionForm((current) => ({ ...current, [key]: value }));
  }

  async function submitOciAdbAction() {
    if (!ociAdbActionTarget?.id || !ociAdbActionTarget.region || !ociAdbActionType) {
      setOciAdbActionError('Database OCID, region, and action are required.');
      return;
    }

    const database = ociAdbActionTarget;
    const databaseId = ociAdbActionTarget.id;
    const databaseRegion = ociAdbActionTarget.region;
    const action = ociAdbActionType;
    const form = ociAdbActionForm;
    const databaseName = String(database.name || database.dbName || database.id);
    if (action === 'clone' && (!form.displayName.trim() || !form.dbName.trim() || !form.adminPassword || form.adminPassword !== form.confirmAdminPassword)) {
      setOciAdbActionError('Clone name, database name, and matching admin passwords are required.');
      return;
    }
    if (action === 'restore' && !form.restoreTimestamp.trim()) {
      setOciAdbActionError('Restore timestamp is required.');
      return;
    }
    if (action === 'switchover' && !form.peerDbId.trim()) {
      setOciAdbActionError('Peer Autonomous Database OCID is required.');
      return;
    }
    if (action === 'terminate' && form.confirmation.trim() !== database.id && form.confirmation.trim() !== databaseName) {
      setOciAdbActionError('Type the database name or OCID to confirm termination.');
      return;
    }

    setOciAdbActionSubmitting(true);
    setOciAdbActionError('');
    try {
      if (action === 'clone') {
        const response = await ociService.cloneOciAutonomousDatabase(databaseId, {
          region: databaseRegion,
          compartmentId: database.compartmentId || '',
          displayName: form.displayName.trim(),
          dbName: form.dbName.trim(),
          adminPassword: form.adminPassword,
          cloneType: form.cloneType,
        });
        upsertOciDatabaseRow(response.data.database);
        setOciDatabaseError(response.data.message);
      } else if (action === 'terminate') {
        const response = await ociService.deleteOciDatabase(databaseId, {
          region: databaseRegion,
          databaseName,
          resourceType: 'autonomousDatabase',
          confirmation: form.confirmation.trim(),
        });
        const deletedId = databaseId;
        setOciDatabaseResources((current) => current ? {
          ...current,
          autonomousDatabases: current.autonomousDatabases.filter((item) => item.id !== deletedId),
        } : current);
        setOciAllResources((current) => current ? {
          ...current,
          summary: { ...current.summary, autonomousDatabases: Math.max(0, (current.summary.autonomousDatabases || 0) - 1) },
          autonomousDatabases: (current.autonomousDatabases || []).filter((item) => item.id !== deletedId),
        } : current);
        setOciDatabaseError(response.data.message);
      } else {
        const response = await ociService.runOciAutonomousDatabaseAction(databaseId, action, {
          region: databaseRegion,
          databaseName,
          restoreTimestamp: action === 'restore' ? form.restoreTimestamp.trim() : undefined,
          peerDbId: action === 'switchover' ? form.peerDbId.trim() : undefined,
        });
        updateOciAutonomousDatabaseRow({ ...database, ...response.data.database });
        setOciDatabaseError(response.data.message);
      }
      setOciAdbActionTarget(null);
      setOciAdbActionType(null);
      setOciAdbActionForm(defaultOciAutonomousDatabaseActionForm());
    } catch (err) {
      setOciAdbActionError(err instanceof Error ? err.message : 'Unable to submit Autonomous Database action.');
    } finally {
      setOciAdbActionSubmitting(false);
    }
  }

  function openOciDbSystemAction(database: ResourceRecord, action: OciDbSystemAction) {
    setOciDbSystemActionTarget(database);
    setOciDbSystemActionType(action);
    setOciDbSystemActionForm(defaultOciDbSystemActionForm(database));
    setOciDbSystemActionError('');
    setOciDbSystemNodes([]);
    if (action === 'nodes') {
      void loadOciDbSystemNodes(database);
    }
  }

  function updateOciDbSystemActionField<K extends keyof OciDbSystemActionForm>(key: K, value: OciDbSystemActionForm[K]) {
    setOciDbSystemActionForm((current) => ({ ...current, [key]: value }));
  }

  async function loadOciDbSystemNodes(database = ociDbSystemActionTarget) {
    if (!database?.id || !database.region || !database.compartmentId) {
      setOciDbSystemActionError('DB System OCID, region, and compartment are required to list nodes.');
      return;
    }
    setOciDbSystemNodesLoading(true);
    setOciDbSystemActionError('');
    try {
      const response = await ociService.getOciDbSystemNodes(database.id, {
        region: database.region,
        compartmentId: database.compartmentId,
      });
      setOciDbSystemNodes(response.data.nodes || []);
      const errors = response.data.errors || [];
      setOciDbSystemActionError(errors.length ? errors[0].message : '');
    } catch (err) {
      setOciDbSystemActionError(err instanceof Error ? err.message : 'Unable to list DB System nodes.');
    } finally {
      setOciDbSystemNodesLoading(false);
    }
  }

  async function runOciDbSystemNodeAction(node: ociService.OciDbSystemNode, action: 'start' | 'stop') {
    const database = ociDbSystemActionTarget;
    if (!database?.id || !database.region || !node.id) {
      setOciDbSystemActionError('DB System, node OCID, and region are required.');
      return;
    }
    const previousNodes = ociDbSystemNodes;
    setOciDbSystemNodes((current) => current.map((item) => item.id === node.id ? { ...item, status: action === 'start' ? 'STARTING' : 'STOPPING' } : item));
    setOciDbSystemActionError('');
    try {
      const response = await ociService.runOciDbNodeAction(database.id, node.id, action, { region: database.region });
      setOciDbSystemNodes((current) => current.map((item) => item.id === node.id ? { ...item, ...response.data.node } : item));
      setOciDatabaseError(response.data.message);
    } catch (err) {
      setOciDbSystemNodes(previousNodes);
      setOciDbSystemActionError(err instanceof Error ? err.message : `Unable to ${action} DB node.`);
    }
  }

  async function submitOciDbSystemAction() {
    const database = ociDbSystemActionTarget;
    const action = ociDbSystemActionType;
    const form = ociDbSystemActionForm;
    if (!database?.id || !database.region || !action) {
      setOciDbSystemActionError('DB System OCID, region, and action are required.');
      return;
    }
    setOciDbSystemActionSubmitting(true);
    setOciDbSystemActionError('');
    try {
      if (action === 'clone') {
        if (!form.displayName.trim() || !form.hostnamePrefix.trim() || !form.dbName.trim() || !form.adminPassword || form.adminPassword !== form.confirmAdminPassword || !form.sshPublicKeys.trim()) {
          setOciDbSystemActionError('Clone name, hostname, database name, matching admin passwords, and SSH public key are required.');
          setOciDbSystemActionSubmitting(false);
          return;
        }
        const response = await ociService.createOciDbSystem({
          ...defaultOciDbSystemForm(database),
          displayName: form.displayName.trim(),
          hostnamePrefix: form.hostnamePrefix.trim(),
          dbName: form.dbName.trim(),
          adminPassword: form.adminPassword,
          sshPublicKeys: form.sshPublicKeys,
          sourceDbSystemId: database.id,
        });
        upsertOciDatabaseRow(response.data.database);
        setOciDatabaseError(response.data.message);
      } else if (action === 'storage') {
        const response = await ociService.updateOciDbSystem(database.id, {
          region: database.region,
          databaseName: database.name || database.id,
          dataStorageSizeInGBs: form.dataStorageSizeInGBs,
        });
        upsertOciDatabaseRow({ ...database, ...response.data.database });
        setOciDatabaseError(response.data.message);
      } else if (action === 'sshKeys') {
        if (!form.sshPublicKeys.trim()) {
          setOciDbSystemActionError('At least one SSH public key is required.');
          setOciDbSystemActionSubmitting(false);
          return;
        }
        const response = await ociService.updateOciDbSystem(database.id, {
          region: database.region,
          databaseName: database.name || database.id,
          sshPublicKeys: form.sshPublicKeys,
        });
        upsertOciDatabaseRow({ ...database, ...response.data.database });
        setOciDatabaseError(response.data.message);
      }
      setOciDbSystemActionTarget(null);
      setOciDbSystemActionType(null);
      setOciDbSystemActionForm(defaultOciDbSystemActionForm());
      setOciDbSystemNodes([]);
    } catch (err) {
      setOciDbSystemActionError(err instanceof Error ? err.message : 'Unable to submit DB System action.');
    } finally {
      setOciDbSystemActionSubmitting(false);
    }
  }

  async function loadOciNetworkCatalog() {
    if (!selectedOciConnector || selectedOciConnector.status !== 'verified') {
      setOciNetworkError(selectedOciConnector ? 'Verify the selected OCI connector to load Network resources.' : 'Select an OCI connector to load Network resources.');
      return;
    }
    const region = ociNetworkRegionFilter !== 'all' ? ociNetworkRegionFilter : ociAllResourcesRegion !== 'all' ? ociAllResourcesRegion : '';
    const compartmentId = ociNetworkCompartmentFilter;
    if (!region || !compartmentId || compartmentId === 'all') {
      setOciNetworkError('Select one region and one compartment to refresh OCI Network resources.');
      return;
    }
    setOciNetworkLoading(true);
    setOciNetworkError('');
    try {
      const response = await ociService.getOciNetworkResources(region, compartmentId);
      setOciNetworkResources(response.data);
      const errors = response.data.errors || [];
      setOciNetworkError(errors.length ? `Network loaded with ${errors.length} warning${errors.length === 1 ? '' : 's'}. ${errors.slice(0, 3).map((item) => item.message).join(' ')}` : '');
    } catch (err) {
      setOciNetworkError(err instanceof Error ? err.message : 'Unable to load OCI Network resources.');
    } finally {
      setOciNetworkLoading(false);
    }
  }

  function openOciNetworkAction(action: OciNetworkAction) {
    const region = ociNetworkRegionFilter !== 'all' ? ociNetworkRegionFilter : ociAllResourcesRegion !== 'all' ? ociAllResourcesRegion : selectedOciConnector?.region || '';
    const compartmentId = ociNetworkCompartmentFilter !== 'all' ? ociNetworkCompartmentFilter : selectedOciConnector?.compartmentOcid || ociCompartmentTree[0]?.id || '';
    setOciNetworkForm({
      ...defaultOciNetworkForm(),
      region,
      compartmentId,
      vcnId: filteredOciNetworkVcns[0]?.id || '',
      networkEntityId: ociNetworkGatewayOptions[0]?.id || '',
      drgId: filteredOciDrgs[0]?.id || '',
      remotePeeringConnectionId: filteredOciRemotePeeringConnections[0]?.id || '',
    });
    setOciNetworkError('');
    setOciNetworkAction(action);
  }

  function openOciVcnWizard() {
    const region = ociNetworkRegionFilter !== 'all' ? ociNetworkRegionFilter : ociAllResourcesRegion !== 'all' ? ociAllResourcesRegion : selectedOciConnector?.region || '';
    const compartmentId = ociNetworkCompartmentFilter !== 'all' ? ociNetworkCompartmentFilter : selectedOciConnector?.compartmentOcid || ociCompartmentTree[0]?.id || '';
    setOciVcnWizardForm({
      ...defaultOciVcnWizardForm(),
      region,
      compartmentId,
    });
    setOciVcnWizardStep(1);
    setOciVcnWizardOpen(true);
    setOciNetworkError('');
  }

  async function submitOciNetworkAction() {
    if (!ociNetworkAction) {
      return;
    }
    const baseRequired = ociNetworkAction === 'remotePeeringConnectionConnect'
      ? [ociNetworkForm.region]
      : [ociNetworkForm.region, ociNetworkForm.compartmentId, ociNetworkForm.displayName.trim()];
    if (baseRequired.some((value) => !value)) {
      setOciNetworkError(ociNetworkAction === 'remotePeeringConnectionConnect' ? 'Region is required.' : 'Region, compartment, and name are required.');
      return;
    }
    setOciNetworkSubmitting(true);
    setOciNetworkError('');
    try {
      let message = '';
      if (ociNetworkAction === 'vcn') {
        const response = await ociService.createOciVcn(ociNetworkForm);
        message = response.data.message;
        setOciNetworkResources((current) => current ? { ...current, vcns: [response.data.vcn, ...current.vcns.filter((row) => row.id !== response.data.vcn.id)] } : current);
        setOciAllResources((current) => current ? { ...current, summary: { ...current.summary, vcns: current.summary.vcns + 1 }, vcns: [response.data.vcn, ...current.vcns] } : current);
      } else if (ociNetworkAction === 'subnet') {
        if (!ociNetworkForm.vcnId || !ociNetworkForm.cidrBlock) {
          setOciNetworkError('VCN and subnet CIDR block are required.');
          return;
        }
        const response = await ociService.createOciSubnet(ociNetworkForm);
        message = response.data.message;
        setOciNetworkResources((current) => current ? { ...current, subnets: [response.data.subnet, ...current.subnets.filter((row) => row.id !== response.data.subnet.id)] } : current);
        setOciAllResources((current) => current ? { ...current, summary: { ...current.summary, subnets: current.summary.subnets + 1 }, subnets: [response.data.subnet, ...current.subnets] } : current);
      } else if (ociNetworkAction === 'gateway') {
        if (!ociNetworkForm.vcnId) {
          setOciNetworkError('VCN is required.');
          return;
        }
        const response = await ociService.createOciGateway(ociNetworkForm);
        message = response.data.message;
        const key = ociNetworkForm.gatewayType === 'natGateway' ? 'natGateways' : ociNetworkForm.gatewayType === 'serviceGateway' ? 'serviceGateways' : 'internetGateways';
        setOciNetworkResources((current) => current ? { ...current, [key]: [response.data.gateway, ...(current[key] || [])] } : current);
      } else if (ociNetworkAction === 'drg') {
        const response = await ociService.createOciDrg(ociNetworkForm);
        message = response.data.message;
        setOciNetworkResources((current) => current ? { ...current, drgs: [response.data.drg, ...(current.drgs || []).filter((row) => row.id !== response.data.drg.id)] } : current);
      } else if (ociNetworkAction === 'drgAttachment') {
        if (!ociNetworkForm.drgId || !ociNetworkForm.vcnId) {
          setOciNetworkError('DRG and VCN are required.');
          return;
        }
        const response = await ociService.createOciDrgAttachment(ociNetworkForm);
        message = response.data.message;
        setOciNetworkResources((current) => current ? { ...current, drgAttachments: [response.data.attachment, ...(current.drgAttachments || []).filter((row) => row.id !== response.data.attachment.id)] } : current);
      } else if (ociNetworkAction === 'remotePeeringConnection') {
        if (!ociNetworkForm.drgId) {
          setOciNetworkError('DRG is required.');
          return;
        }
        const response = await ociService.createOciRemotePeeringConnection(ociNetworkForm);
        message = response.data.message;
        setOciNetworkResources((current) => current ? { ...current, remotePeeringConnections: [response.data.connection, ...(current.remotePeeringConnections || []).filter((row) => row.id !== response.data.connection.id)] } : current);
      } else if (ociNetworkAction === 'remotePeeringConnectionConnect') {
        if (!ociNetworkForm.remotePeeringConnectionId || !ociNetworkForm.peerId || !ociNetworkForm.peerRegionName) {
          setOciNetworkError('Local RPC, peer RPC OCID, and peer region are required.');
          return;
        }
        const response = await ociService.connectOciRemotePeeringConnection(ociNetworkForm.remotePeeringConnectionId, {
          region: ociNetworkForm.region,
          peerId: ociNetworkForm.peerId.trim(),
          peerRegionName: ociNetworkForm.peerRegionName.trim(),
        });
        message = response.data.message;
        setOciNetworkResources((current) => current ? {
          ...current,
          remotePeeringConnections: (current.remotePeeringConnections || []).map((row) => row.id === response.data.connection.id ? { ...row, ...response.data.connection } : row),
        } : current);
      } else if (ociNetworkAction === 'routeTable') {
        if (!ociNetworkForm.vcnId || !ociNetworkForm.destinationCidrBlock || !ociNetworkForm.networkEntityId) {
          setOciNetworkError('VCN, destination CIDR, and gateway/network entity are required.');
          return;
        }
        const response = await ociService.createOciRouteTable(ociNetworkForm);
        message = response.data.message;
        setOciNetworkResources((current) => current ? { ...current, routeTables: [response.data.routeTable, ...current.routeTables] } : current);
      } else if (ociNetworkAction === 'securityList') {
        if (!ociNetworkForm.vcnId) {
          setOciNetworkError('VCN is required.');
          return;
        }
        const response = await ociService.createOciSecurityList(ociNetworkForm);
        message = response.data.message;
        setOciNetworkResources((current) => current ? { ...current, securityLists: [response.data.securityList, ...current.securityLists] } : current);
      }
      setOciVmActionMessage(message);
      setOciNetworkAction(null);
    } catch (err) {
      setOciNetworkError(err instanceof Error ? err.message : 'Unable to submit OCI Network action.');
    } finally {
      setOciNetworkSubmitting(false);
    }
  }

  async function submitOciVcnWizard() {
    const form = ociVcnWizardForm;
    if (!form.region || !form.compartmentId || !form.displayName.trim() || !form.cidrBlock.trim()) {
      setOciNetworkError('Region, compartment, VCN name, and VCN CIDR are required.');
      return;
    }
    if (form.createPublicSubnet && (!form.publicSubnetName.trim() || !form.publicSubnetCidr.trim())) {
      setOciNetworkError('Public subnet name and CIDR are required.');
      return;
    }
    if (form.createPrivateSubnet && (!form.privateSubnetName.trim() || !form.privateSubnetCidr.trim())) {
      setOciNetworkError('Private subnet name and CIDR are required.');
      return;
    }

    setOciNetworkSubmitting(true);
    setOciNetworkError('');
    try {
      const vcnResponse = await ociService.createOciVcn({
        region: form.region,
        compartmentId: form.compartmentId,
        displayName: form.displayName.trim(),
        cidrBlock: form.cidrBlock.trim(),
        dnsLabel: form.dnsLabel.trim(),
      });
      const createdVcn = vcnResponse.data.vcn;
      const vcnId = createdVcn.id || '';
      if (!vcnId) {
        throw new Error('VCN was created but OCI did not return a VCN OCID.');
      }

      const createdSubnets: ResourceRecord[] = [];
      const createdGateways: ResourceRecord[] = [];
      let routeTargetId = '';

      if (form.createPublicSubnet) {
        const response = await ociService.createOciSubnet({
          region: form.region,
          compartmentId: form.compartmentId,
          vcnId,
          displayName: form.publicSubnetName.trim(),
          cidrBlock: form.publicSubnetCidr.trim(),
        });
        createdSubnets.push(response.data.subnet);
      }
      if (form.createPrivateSubnet) {
        const response = await ociService.createOciSubnet({
          region: form.region,
          compartmentId: form.compartmentId,
          vcnId,
          displayName: form.privateSubnetName.trim(),
          cidrBlock: form.privateSubnetCidr.trim(),
        });
        createdSubnets.push(response.data.subnet);
      }
      if (form.createInternetGateway) {
        const response = await ociService.createOciGateway({
          region: form.region,
          compartmentId: form.compartmentId,
          vcnId,
          displayName: form.internetGatewayName.trim() || `${form.displayName.trim()}-igw`,
          gatewayType: 'internetGateway',
        });
        createdGateways.push(response.data.gateway);
        routeTargetId = response.data.gateway.id || routeTargetId;
      }
      if (form.createNatGateway) {
        const response = await ociService.createOciGateway({
          region: form.region,
          compartmentId: form.compartmentId,
          vcnId,
          displayName: form.natGatewayName.trim() || `${form.displayName.trim()}-nat`,
          gatewayType: 'natGateway',
        });
        createdGateways.push(response.data.gateway);
        routeTargetId = routeTargetId || response.data.gateway.id || '';
      }
      if (form.createServiceGateway) {
        const response = await ociService.createOciGateway({
          region: form.region,
          compartmentId: form.compartmentId,
          vcnId,
          displayName: form.serviceGatewayName.trim() || `${form.displayName.trim()}-service`,
          gatewayType: 'serviceGateway',
        });
        createdGateways.push(response.data.gateway);
      }

      let createdRouteTable: ResourceRecord | null = null;
      if (form.createDefaultRoute && routeTargetId) {
        const response = await ociService.createOciRouteTable({
          region: form.region,
          compartmentId: form.compartmentId,
          vcnId,
          displayName: form.routeTableName.trim() || `${form.displayName.trim()}-routes`,
          destinationCidrBlock: '0.0.0.0/0',
          networkEntityId: routeTargetId,
        });
        createdRouteTable = response.data.routeTable;
      }

      let createdSecurityList: ResourceRecord | null = null;
      if (form.createSecurityList) {
        const response = await ociService.createOciSecurityList({
          region: form.region,
          compartmentId: form.compartmentId,
          vcnId,
          displayName: form.securityListName.trim() || `${form.displayName.trim()}-security`,
          direction: 'ingress',
          protocol: '6',
          source: '0.0.0.0/0',
          tcpPort: form.securityTcpPort.trim(),
        });
        createdSecurityList = response.data.securityList;
      }

      setOciNetworkResources((current) => {
        const next = current || {
          generatedAt: new Date().toISOString(),
          region: form.region,
          compartmentId: form.compartmentId,
          vcns: [],
          subnets: [],
          internetGateways: [],
          natGateways: [],
          serviceGateways: [],
          drgs: [],
          drgAttachments: [],
          remotePeeringConnections: [],
          routeTables: [],
          securityLists: [],
          errors: [],
        };
        return {
          ...next,
          vcns: [createdVcn, ...next.vcns.filter((row) => row.id !== createdVcn.id)],
          subnets: [...createdSubnets, ...next.subnets.filter((row) => !createdSubnets.some((created) => created.id === row.id))],
          internetGateways: [...createdGateways.filter((row) => row.resourceType === 'internetGateway' || row.providerType === 'internetGateway'), ...next.internetGateways],
          natGateways: [...createdGateways.filter((row) => row.resourceType === 'natGateway' || row.providerType === 'natGateway'), ...next.natGateways],
          serviceGateways: [...createdGateways.filter((row) => row.resourceType === 'serviceGateway' || row.providerType === 'serviceGateway'), ...next.serviceGateways],
          routeTables: createdRouteTable ? [createdRouteTable, ...next.routeTables] : next.routeTables,
          securityLists: createdSecurityList ? [createdSecurityList, ...next.securityLists] : next.securityLists,
        };
      });
      setOciAllResources((current) => current ? {
        ...current,
        summary: {
          ...current.summary,
          vcns: current.summary.vcns + 1,
          subnets: current.summary.subnets + createdSubnets.length,
        },
        vcns: [createdVcn, ...current.vcns],
        subnets: [...createdSubnets, ...current.subnets],
      } : current);
      setOciVmActionMessage('VCN wizard completed.');
      setOciVcnWizardOpen(false);
    } catch (err) {
      setOciNetworkError(err instanceof Error ? err.message : 'Unable to complete VCN wizard.');
    } finally {
      setOciNetworkSubmitting(false);
    }
  }

  function openOciVcnDelete(vcn: ResourceRecord) {
    setOciNetworkDeleteTarget(vcn);
    setOciNetworkDeleteKind('vcn');
    setOciNetworkDeleteConfirmation('');
    setOciNetworkError('');
  }

