  function validateNetworkForm() {
    const errors: string[] = [];
    if (!networkNode) {
      errors.push('Select a node.');
    }
    if (!networkForm.iface.trim()) {
      errors.push('Interface name is required.');
    }
    if (networkForm.type === 'bridge' && !/^vmbr\d+$/.test(networkForm.iface.trim())) {
      errors.push('Bridge name must look like vmbr1 or vmbr2.');
    }
    if (networkInterfaces.some((item) => item.iface === networkForm.iface.trim() && item.iface !== networkEditingIface)) {
      errors.push(`Interface ${networkForm.iface.trim()} already exists.`);
    }
    if (networkForm.type === 'bond' && !networkForm.slaves.trim()) {
      errors.push('Linux bond requires at least one slave port.');
    }
    if (networkForm.type === 'vlan') {
      const vlanId = Number(networkForm.vlanId);
      if (!Number.isInteger(vlanId) || vlanId < 1 || vlanId > 4094) {
        errors.push('VLAN ID must be from 1 to 4094.');
      }
      if (!networkForm.vlanRawDevice.trim()) {
        errors.push('Select a raw device.');
      }
    }
    if (networkForm.type === 'OVSBond') {
      if (!networkForm.ovsBridge.trim()) {
        errors.push('Select an OVS bridge.');
      }
      if (!networkForm.ovsBonds.trim()) {
        errors.push('OVS bond requires at least one bond port.');
      }
    }
    if (networkForm.type === 'OVSIntPort' && !networkForm.ovsBridge.trim()) {
      errors.push('Select an OVS bridge.');
    }
    if (networkForm.method === 'static' && (!networkForm.address.trim() || !networkForm.netmask.trim())) {
      errors.push('Static configuration requires address and netmask.');
    }
    return errors;
  }

  async function submitNetworkForm() {
    const errors = validateNetworkForm();
    if (errors.length) {
      setNetworkError(errors.join(' '));
      return;
    }

    setNetworkSaving(true);
    setNetworkError('');
    setNetworkMessage('');

    try {
      const payload = {
        ...networkForm,
        iface: networkForm.iface.trim(),
        address: networkForm.address.trim(),
        netmask: networkForm.netmask.trim(),
        gateway: networkForm.gateway.trim(),
        bridgePorts: networkForm.bridgePorts.trim(),
        slaves: networkForm.slaves.trim(),
        vlanId: networkForm.vlanId.trim(),
        vlanRawDevice: networkForm.vlanRawDevice.trim(),
        ovsBridge: networkForm.ovsBridge.trim(),
        ovsBonds: networkForm.ovsBonds.trim(),
        ovsPorts: networkForm.ovsPorts.trim(),
        ovsOptions: networkForm.ovsOptions.trim(),
        ovsTag: networkForm.ovsTag.trim(),
        mtu: networkForm.mtu.trim(),
        comments: networkForm.comments.trim(),
      };
      const response = networkEditingIface
        ? await dashboardService.updateNodeNetwork(networkNode, networkEditingIface, payload)
        : await dashboardService.createNodeNetwork(networkNode, payload);
      setNetworkMessage(response.data.message);
      setNetworkEditingIface('');
      setNetworkModalOpen(false);
      await loadNetwork(networkNode, false);
    } catch (err) {
      setNetworkError(err instanceof Error ? err.message : 'Unable to save network.');
    } finally {
      setNetworkSaving(false);
    }
  }

