  function downloadTaskOutput() {
    if (!taskViewerTask) {
      return;
    }
    const lines = (taskDetail?.output || []).map((line) => line.text).join('\n');
    const blob = new Blob([lines], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${taskViewerTask.node || 'node'}-${taskViewerTask.id || 'task'}-output.txt`;
    link.click();
    URL.revokeObjectURL(url);
  }

  async function stopViewedTask() {
    if (!taskViewerTask?.node || !taskViewerTask.upid) {
      return;
    }

    openSafetyDelete({
      eyebrow: 'Job Center',
      title: 'Cancel running task',
      message: 'This asks Proxmox to stop the selected task.',
      expected: taskViewerTask.upid,
      details: [
        { label: 'Node', value: taskViewerTask.node },
        { label: 'Task ID', value: <span className="break-all">{taskViewerTask.upid}</span> },
      ],
      confirmLabel: 'Cancel Task',
      onConfirm: async (confirmation) => {
        setTaskStopping(true);
        setTaskDetailError('');
        try {
          await dashboardService.stopTask({
            node: taskViewerTask.node,
            upid: taskViewerTask.upid,
            confirmation,
          });
          await loadTaskDetail(taskViewerTask, false);
          await loadProxmoxLogs(false);
        } catch (err) {
          setTaskDetailError(err instanceof Error ? err.message : 'Unable to stop task.');
          throw err;
        } finally {
          setTaskStopping(false);
        }
      },
    });
  }

  async function retryViewedTask() {
    const task = taskDetail?.task || taskViewerTask;
    if (!task?.node || !task.upid) {
      return;
    }
    if (!task.retryable) {
      setTaskDetailError('This job cannot be retried automatically.');
      return;
    }
    if (!window.confirm('Retry this failed job?')) {
      return;
    }

    setTaskRetrying(true);
    setTaskDetailError('');
    try {
      const response = await dashboardService.retryTask({
        node: task.node,
        upid: task.upid,
      });
      setOperationMessage(response.data.message);
      await Promise.all([loadProxmoxLogs(false), loadDashboard()]);
      setTaskViewerTask(null);
      setTaskDetail(null);
    } catch (err) {
      setTaskDetailError(err instanceof Error ? err.message : 'Unable to retry job.');
    } finally {
      setTaskRetrying(false);
    }
  }

  function getTaskLinkedResource(task: ProxmoxTask) {
    if (['aws', 'azure', 'oci'].includes(String(task.provider || '')) && task.linkedResource?.id) {
      return task.linkedResource;
    }

    if (task.linkedResource?.vmid) {
      return task.linkedResource;
    }

    const vmid = Number(task.id);
    if (!Number.isFinite(vmid)) {
      return null;
    }

    const node = task.node || '';
    const vmMatch = [...(dashboard?.resources.vms || []), ...(dashboard?.resources.vmTemplates || [])].find(
      (resource) => Number(resource.vmid) === vmid && (!node || resource.node === node),
    );
    if (vmMatch) {
      return { type: 'qemu' as const, vmid, node: vmMatch.node || node };
    }

    const containerMatch = (dashboard?.resources.containers || []).find(
      (resource) => Number(resource.vmid) === vmid && (!node || resource.node === node),
    );
    if (containerMatch) {
      return { type: 'lxc' as const, vmid, node: containerMatch.node || node };
    }

    if (task.resourceType === 'qemu' || task.resourceType === 'lxc') {
      return { type: task.resourceType, vmid, node };
    }

    return null;
  }

  function getTaskResourceLabel(task: ProxmoxTask) {
    const linkedResource = getTaskLinkedResource(task);
    if (!linkedResource) {
      return '-';
    }
    if (['aws', 'azure', 'oci'].includes(String(linkedResource.provider || task.provider || ''))) {
      return `${String(linkedResource.type || task.provider || 'resource').toUpperCase()} ${linkedResource.name || linkedResource.id || ''}${linkedResource.region ? ` in ${linkedResource.region}` : ''}`.trim();
    }
    return `${linkedResource.type.toUpperCase()} ${linkedResource.vmid}${linkedResource.node ? ` on ${linkedResource.node}` : ''}`;
  }

  function openLinkedTaskResource(task: ProxmoxTask) {
    const linkedResource = getTaskLinkedResource(task);
    if (!linkedResource) {
      return;
    }

    if (linkedResource.provider === 'aws' || task.provider === 'aws') {
      setActiveCloud('aws');
      if (['ec2Instance', 'ec2', 'instance'].includes(linkedResource.type)) {
        setActiveTab('awsEc2Management');
      } else if (['rdsDatabase', 'rdsSnapshot'].includes(linkedResource.type)) {
        setActiveTab('awsDatabaseManagement');
      } else if (['ebsVolume', 'ebsSnapshot', 's3Bucket', 's3Object'].includes(linkedResource.type)) {
        setActiveTab('awsStorageManagement');
      } else if (['vpc', 'subnet', 'routeTable', 'internetGateway', 'natGateway', 'securityGroup'].includes(linkedResource.type)) {
        setActiveTab('awsNetworkManagement');
      } else {
        setActiveTab('aws');
      }
      if (linkedResource.region) {
        setAwsInventoryRegion(linkedResource.region);
      }
      return;
    }

    if (linkedResource.provider === 'azure' || task.provider === 'azure') {
      setActiveCloud('azure');
      const type = String(linkedResource.type || '');
      if (['virtualMachine', 'vm'].includes(type)) {
        setActiveTab('azureVmManagement');
      } else if (['storageAccount', 'managedDisk', 'snapshot', 'blobContainer', 'fileShare'].includes(type)) {
        setActiveTab('azureStorageManagement');
      } else if (['vnet', 'subnet', 'routeTable', 'networkSecurityGroup', 'publicIp'].includes(type)) {
        setActiveTab('azureNetworkManagement');
      } else if (['sqlServer', 'sqlDatabase', 'cosmosDbAccount', 'cosmosDbDatabase', 'postgresFlexibleServer', 'mysqlFlexibleServer'].includes(type)) {
        setActiveTab('azureDatabaseManagement');
      } else {
        setActiveTab('azureInventory');
      }
      void loadAzureInventory(false);
      return;
    }

    if (linkedResource.provider === 'oci' || task.provider === 'oci') {
      setActiveCloud('oci');
      setActiveTab('ociAllResources');
      return;
    }

    setActiveCloud('pve');
    setActiveTab('operations');
    if (linkedResource.type === 'qemu') {
      setVmSearch('');
      setVmStatusFilter('all');
      setSelectedVmKey(`qemu-${linkedResource.node || 'node'}-${linkedResource.vmid}`);
      return;
    }

    setContainerSearch('');
    setContainerStatusFilter('all');
    setSelectedContainerKey(`lxc-${linkedResource.node || 'node'}-${linkedResource.vmid}`);
  }

  function taskMatchesJobView(task: ProxmoxTask) {
    const normalizedProvider = task.provider === 'proxmox' || !task.provider ? 'proxmox' : String(task.provider);
    if (jobProviderFilter !== 'all' && normalizedProvider !== jobProviderFilter) {
      return false;
    }
    if (jobFilter === 'running' && !isTaskRunning(task)) {
      return false;
    }
    if (jobFilter === 'failed' && !isTaskFailed(task)) {
      return false;
    }
    if (jobFilter === 'completed' && !isTaskCompleted(task)) {
      return false;
    }
    if (jobFilter === 'retryable' && !isTaskRetryable(task)) {
      return false;
    }
    if (jobFilter === 'cancelable' && !isTaskCancelable(task)) {
      return false;
    }
    const query = jobSearch.trim().toLowerCase();
    if (!query) {
      return true;
    }
    return [
      task.description,
      task.node,
      task.user,
      task.type,
      task.id,
      task.exitstatus,
      task.action,
      task.resourceType,
      getTaskResourceLabel(task),
    ].some((value) => String(value || '').toLowerCase().includes(query));
  }

