  async function reuploadTerraformStack(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0] || null;
    const stack = terraformReuploadStackRef.current;
    event.target.value = '';
    if (!file || !stack) {
      return;
    }

    setTerraformActionStackId(`${stack.id}:reupload`);
    setTerraformError('');
    setTerraformMessage('');
    try {
      const response = await dashboardService.reuploadTerraformStack({ stackId: stack.id, file });
      setTerraformStacks((current) => current.map((item) => item.id === stack.id ? response.data.stack : item));
      setTerraformMessage(response.data.message);
      void refreshAuditLog();
    } catch (err) {
      setTerraformError(err instanceof Error ? err.message : 'Unable to re-upload Terraform stack ZIP.');
    } finally {
      terraformReuploadStackRef.current = null;
      setTerraformActionStackId('');
    }
  }

  function getTerraformConfirmation(stack: TerraformStack, action: 'deploy' | 'destroy' | 'delete') {
    const current = terraformConfirmation.trim();
    if (action === 'deploy' && current === stack.name) {
      return current;
    }
    if ((action === 'destroy' || action === 'delete') && (current === stack.name || current === stack.id)) {
      return current;
    }
    const expected = action === 'deploy' ? stack.name : `${stack.name} or ${stack.id}`;
    const typed = window.prompt(`Type ${expected} to confirm ${action}.`)?.trim() || '';
    if (action === 'deploy' && typed === stack.name) {
      setTerraformConfirmation(typed);
      return typed;
    }
    if ((action === 'destroy' || action === 'delete') && (typed === stack.name || typed === stack.id)) {
      setTerraformConfirmation(typed);
      return typed;
    }
    setTerraformError(`Confirmation did not match. Type ${expected} to confirm ${action}.`);
    return '';
  }

  async function runTerraformStack(stack: TerraformStack, action: 'validate' | 'plan' | 'deploy' | 'destroy') {
    const confirmation = action === 'deploy' || action === 'destroy'
      ? getTerraformConfirmation(stack, action)
      : '';
    if ((action === 'deploy' || action === 'destroy') && !confirmation) {
      return;
    }
    setTerraformActionStackId(`${stack.id}:${action}`);
    setTerraformError('');
    setTerraformMessage('');
    const startedAt = new Date().toISOString();
    const optimisticRun = {
      id: `${stack.id}-${action}-${Date.now()}`,
      action,
      status: 'running',
      message: `${action} started.`,
      startedAt,
      finishedAt: null,
      output: [`${action} started. (${startedAt})`],
    };
    setTerraformStacks((current) => current.map((item) => item.id === stack.id ? {
      ...item,
      status: 'running',
      lastAction: action,
      lastMessage: `${action} started.`,
      lastRunAt: startedAt,
      lastOutput: optimisticRun.output,
      runs: [optimisticRun, ...(item.runs || [])],
    } : item));
    try {
      const response = action === 'validate'
        ? await dashboardService.validateTerraformStack(stack.id)
        : action === 'plan'
          ? await dashboardService.planTerraformStack(stack.id)
          : action === 'deploy'
            ? await dashboardService.deployTerraformStack(stack.id, confirmation)
            : await dashboardService.destroyTerraformStack(stack.id, confirmation);
      setTerraformStacks((current) => current.map((item) => item.id === stack.id ? response.data.stack : item));
      setTerraformConfirmation('');
      setTerraformMessage(response.data.message);
      void loadProxmoxLogs(false);
    } catch (err) {
      setTerraformError(err instanceof Error ? err.message : `Unable to ${action} Terraform stack.`);
      void loadTerraformStacks();
    } finally {
      setTerraformActionStackId('');
    }
  }

  async function removeTerraformStack(stack: TerraformStack) {
    const confirmation = getTerraformConfirmation(stack, 'delete');
    if (!confirmation) {
      return;
    }
    setTerraformActionStackId(`${stack.id}:delete`);
    setTerraformError('');
    setTerraformMessage('');
    try {
      await dashboardService.deleteTerraformStack(stack.id, confirmation);
      setTerraformStacks((current) => current.filter((item) => item.id !== stack.id));
      setTerraformConfirmation('');
      setTerraformMessage('Terraform stack deleted from MC3.');
      void refreshAuditLog();
    } catch (err) {
      setTerraformError(err instanceof Error ? err.message : 'Unable to delete Terraform stack.');
    } finally {
      setTerraformActionStackId('');
    }
  }

  async function downloadTerraformStack(stack: TerraformStack) {
    setTerraformActionStackId(`${stack.id}:download`);
    setTerraformError('');
    setTerraformMessage('');
    try {
      const response = await dashboardService.downloadTerraformStack(stack.id);
      const url = URL.createObjectURL(response.blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = response.fileName;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
      setTerraformMessage(`Downloaded ${response.fileName}.`);
    } catch (err) {
      setTerraformError(err instanceof Error ? err.message : 'Unable to download Terraform stack.');
    } finally {
      setTerraformActionStackId('');
    }
  }

  async function pullTerraformStackFromGit(stack: TerraformStack) {
    setTerraformActionStackId(`${stack.id}:pull`);
    setTerraformError('');
    setTerraformMessage('');
    try {
      const response = await dashboardService.pullTerraformStackFromGit(stack.id);
      setTerraformStacks((current) => current.map((item) => item.id === stack.id ? response.data.stack : item));
      setTerraformMessage(response.data.message);
      void refreshAuditLog();
    } catch (err) {
      setTerraformError(err instanceof Error ? err.message : 'Unable to pull latest Terraform stack from Git.');
    } finally {
      setTerraformActionStackId('');
    }
  }

