  async function saveConnector(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSaving(true);
    setMessage('');
    setError('');

    try {
      const response = editingId
        ? await connectorsService.updateConnector(editingId, form)
        : await connectorsService.createConnector(form);

      setConnectors((current) => {
        if (editingId) {
          return current.map((connector) =>
            connector.id === response.connector.id ? response.connector : connector,
          );
        }
        return [response.connector, ...current];
      });

      if ((response.connector.provider || 'proxmox') === 'proxmox' && response.connector.selected) {
        setSelectedConnectorId(response.connector.id);
      }
      if (response.connector.provider === 'oci' && response.connector.selected) {
        setSelectedOciConnectorId(response.connector.id);
      }
      if (response.connector.provider === 'aws' && response.connector.selected) {
        setSelectedAwsConnectorId(response.connector.id);
      }
      if (response.connector.provider === 'azure' && response.connector.selected) {
        setSelectedAzureConnectorId(response.connector.id);
      }
      if (response.connector.provider === 'gcp' && response.connector.selected) {
        setSelectedGcpConnectorId(response.connector.id);
      }
      setMessage(editingId ? 'Connector updated.' : 'Connector saved.');
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unable to save connector.');
    } finally {
      setSaving(false);
    }
  }

  async function selectConnector(id: string) {
    setMessage('');
    setError('');

    try {
      const response = await connectorsService.selectConnector(id);
      if ((response.connector.provider || 'proxmox') === 'proxmox') {
        setSelectedConnectorId(response.connector.id);
      } else if (response.connector.provider === 'oci') {
        setSelectedOciConnectorId(response.connector.id);
      } else if (response.connector.provider === 'aws') {
        setSelectedAwsConnectorId(response.connector.id);
      } else if (response.connector.provider === 'azure') {
        setSelectedAzureConnectorId(response.connector.id);
      } else if (response.connector.provider === 'gcp') {
        setSelectedGcpConnectorId(response.connector.id);
      }
      setConnectors((current) =>
        current.map((connector) => ({
          ...connector,
          selected:
            (connector.provider || 'proxmox') === (response.connector.provider || 'proxmox')
              ? connector.id === response.connector.id
              : connector.selected,
        })),
      );
      setMessage(`${response.connector.name} selected.`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unable to select connector.');
    }
  }

  async function verifyConnector(id: string) {
    setVerifyingId(id);
    setMessage('');
    setError('');

    try {
      const response = await connectorsService.verifyConnector(id);
      setConnectors((current) =>
        current.map((connector) => (connector.id === response.connector.id ? response.connector : connector)),
      );
      setMessage(response.result.message);
      if (response.connector.id === selectedConnectorId && response.connector.status === 'verified') {
        void loadDashboard(response.connector);
      }
      if (response.connector.id === selectedOciConnectorId && response.connector.status === 'verified') {
        void loadOciInventory();
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unable to verify connector.');
    } finally {
      setVerifyingId(null);
    }
  }

  function deleteConnector(connector: ProxmoxConnector) {
    const id = connector.id;
    openSafetyDelete({
      eyebrow: 'Connector',
      title: `Delete ${connector.name}`,
      message: 'This removes the saved connector and its stored backend secret from this application.',
      expected: connector.name,
      alternateExpected: connector.id,
      details: [
        { label: 'Provider', value: (connector.provider || 'proxmox').toUpperCase() },
        { label: 'Name', value: connector.name },
        { label: 'ID', value: <span className="break-all">{connector.id}</span> },
      ],
      confirmLabel: 'Delete Connector',
      onConfirm: async (confirmation) => {
        setMessage('');
        setError('');
        try {
          await connectorsService.deleteConnector(id, confirmation);
          setConnectors((current) => {
            const next = current.filter((item) => item.id !== id);
            if (selectedConnectorId === id) {
              setSelectedConnectorId(next.find((item) => (item.provider || 'proxmox') === 'proxmox')?.id ?? null);
            }
            if (selectedOciConnectorId === id) {
              setSelectedOciConnectorId(next.find((item) => item.provider === 'oci')?.id ?? null);
            }
            if (selectedAwsConnectorId === id) {
              setSelectedAwsConnectorId(next.find((item) => item.provider === 'aws')?.id ?? null);
            }
            if (selectedAzureConnectorId === id) {
              setSelectedAzureConnectorId(next.find((item) => item.provider === 'azure')?.id ?? null);
            }
            if (selectedGcpConnectorId === id) {
              setSelectedGcpConnectorId(next.find((item) => item.provider === 'gcp')?.id ?? null);
            }
            return next;
          });
          if (editingId === id) {
            resetForm();
          }
          setMessage('Connector deleted.');
        } catch (err) {
          setError(err instanceof Error ? err.message : 'Unable to delete connector.');
          throw err;
        }
      },
    });
  }

  async function runOperation(resource: ResourceRecord, type: 'qemu' | 'lxc', action: ResourceAction) {
    if (!resource.node || !resource.vmid) {
      setOperationError('Resource is missing node or VM ID.');
      return;
    }

    const key = `${type}-${resource.node}-${resource.vmid}-${action}`;
    setActionInFlight(key);
    setOperationMessage('');
    setOperationError('');
    setConfirmation(null);

    try {
      const response = await dashboardService.runResourceAction({
        type,
        node: resource.node,
        vmid: resource.vmid,
        action,
      });
      setOperationMessage(response.data.message);
      await loadDashboard();
    } catch (err) {
      setOperationError(err instanceof Error ? err.message : `Unable to ${action} resource.`);
    } finally {
      setActionInFlight('');
    }
  }

  function requestOperation(resource: ResourceRecord, type: 'qemu' | 'lxc', action: ResourceAction) {
    if (action === 'start') {
      void runOperation(resource, type, action);
      return;
    }
    setConfirmation({ resource, type, action });
  }

  async function launchConsole(resource: ResourceRecord, type: 'qemu' | 'lxc') {
    if (!resource.node || !resource.vmid) {
      setConsoleError('Resource is missing node or VM ID.');
      return;
    }

    const key = `${type}-${resource.node}-${resource.vmid}`;
    setConsoleLoading(key);
    setConsoleError('');

    try {
      const response = await dashboardService.createConsoleSession({
        type,
        node: resource.node,
        vmid: resource.vmid,
      });
      setConsoleSession(response.data);
      setConsoleTarget({ resource, type });
    } catch (err) {
      setConsoleError(err instanceof Error ? err.message : 'Unable to open console.');
    } finally {
      setConsoleLoading('');
    }
  }

