  function validateCreateVmForm() {
    const errors: string[] = [];
    const vmid = Number(createVmForm.vmid);
    const diskSizeGb = Number(createVmForm.diskSizeGb);
    const cores = Number(createVmForm.cores);
    const sockets = Number(createVmForm.sockets);
    const memoryMb = Number(createVmForm.memoryMb);
    const existingIds = [
      ...(dashboard?.resources.vms || []),
      ...(dashboard?.resources.vmTemplates || []),
      ...(dashboard?.resources.containers || []),
    ]
      .map((item) => Number(item.vmid))
      .filter((value) => Number.isInteger(value));

    if (!Number.isInteger(vmid) || vmid <= 0) {
      errors.push('Enter a valid VM ID.');
    } else if (existingIds.includes(vmid)) {
      errors.push(`VM ID ${vmid} is already in use.`);
    }
    if (!createVmForm.name.trim()) {
      errors.push('Enter a VM name.');
    }
    if (!createVmForm.node) {
      errors.push('Select a target node.');
    }
    if (!createVmForm.storage) {
      errors.push('Select target storage.');
    }
    const storageValid = (dashboard?.resources.storage || []).some(
      (item) => item.storage === createVmForm.storage && item.status !== 'unknown' && (!item.node || item.node === createVmForm.node),
    );
    if (createVmForm.storage && !storageValid) {
      errors.push('Selected storage is not valid for the target node.');
    }
    if (!Number.isFinite(diskSizeGb) || diskSizeGb <= 0) {
      errors.push('Enter a positive disk size.');
    }
    if (!Number.isInteger(cores) || cores <= 0) {
      errors.push('Enter a positive core count.');
    }
    if (!Number.isInteger(sockets) || sockets <= 0) {
      errors.push('Enter a positive socket count.');
    }
    if (!Number.isInteger(memoryMb) || memoryMb < 128) {
      errors.push('Memory must be at least 128 MB.');
    }
    if (!createVmForm.bridge.trim()) {
      errors.push('Enter a network bridge.');
    }

    return errors;
  }

  async function submitCreateVm() {
    const errors = validateCreateVmForm();
    if (errors.length) {
      setCreateVmError(errors.join(' '));
      return;
    }

    setCreateVmSubmitting(true);
    setCreateVmError('');
    setOperationMessage('');
    setOperationError('');

    try {
      const response = await dashboardService.createVM({
        node: createVmForm.node,
        vmid: Number(createVmForm.vmid),
        name: createVmForm.name.trim(),
        storage: createVmForm.storage,
        diskSizeGb: Number(createVmForm.diskSizeGb),
        cores: Number(createVmForm.cores),
        sockets: Number(createVmForm.sockets),
        memoryMb: Number(createVmForm.memoryMb),
        bridge: createVmForm.bridge.trim(),
        iso: createVmForm.iso.trim(),
        ostype: createVmForm.ostype,
        scsihw: createVmForm.scsihw,
        description: createVmForm.description.trim(),
        startAfterCreate: createVmForm.startAfterCreate,
      });
      setOperationMessage(response.data.message);
      setCreateVmModalOpen(false);
      await loadDashboard();
    } catch (err) {
      setCreateVmError(err instanceof Error ? err.message : 'Unable to create VM.');
    } finally {
      setCreateVmSubmitting(false);
    }
  }

  async function loadCreateVmInventory(node: string) {
    if (!node) {
      setCreateVmNetworks([]);
      setCreateVmIsos([]);
      return;
    }

    setCreateVmInventoryLoading(true);
    try {
      const [networkResponse, isoResponse] = await Promise.all([
        dashboardService.getNodeNetwork(node),
        dashboardService.getIsoVolumes(node),
      ]);
      const bridges = networkResponse.data.bridges;
      const isos = isoResponse.data.volumes;
      setCreateVmNetworks(bridges);
      setCreateVmIsos(isos);
      setCreateVmForm((current) => ({
        ...current,
        bridge: bridges.some((bridge) => bridge.name === current.bridge) ? current.bridge : bridges[0]?.name || current.bridge,
        iso: current.iso && isos.some((iso) => iso.volid === current.iso) ? current.iso : '',
      }));
    } catch (err) {
      setCreateVmNetworks([]);
      setCreateVmIsos([]);
      setCreateVmError(err instanceof Error ? err.message : 'Unable to load node network and ISO inventory.');
    } finally {
      setCreateVmInventoryLoading(false);
    }
  }

