  function validateBackupForm() {
    const errors: string[] = [];
    const resource = backupTarget?.resource;
    if (!resource?.node || !resource.vmid) {
      errors.push('Resource is missing node or VM ID.');
    }
    if (!backupForm.storage) {
      errors.push('Select backup storage.');
    }
    const storageValid = backupStorageOptions(dashboard, resource?.node).some((item) => item.storage === backupForm.storage);
    if (backupForm.storage && !storageValid) {
      errors.push('Selected storage is not valid for backups on this node.');
    }
    return errors;
  }

  async function submitBackup() {
    if (!backupTarget?.resource.node || !backupTarget.resource.vmid) {
      setBackupError('Resource is missing node or VM ID.');
      return;
    }

    const errors = validateBackupForm();
    if (errors.length) {
      setBackupError(errors.join(' '));
      return;
    }

    setBackupSubmitting(true);
    setBackupError('');
    setOperationMessage('');
    setOperationError('');

    try {
      const response = await dashboardService.backupResource({
        type: backupTarget.type,
        node: backupTarget.resource.node,
        vmid: backupTarget.resource.vmid,
        storage: backupForm.storage,
        mode: backupForm.mode,
        compress: backupForm.compress,
        notes: backupForm.notes.trim(),
      });
      setOperationMessage(response.data.message);
      setBackupTarget(null);
      await Promise.all([loadDashboard(), loadProxmoxLogs(false)]);
    } catch (err) {
      setBackupError(err instanceof Error ? err.message : 'Unable to start backup.');
    } finally {
      setBackupSubmitting(false);
    }
  }

  function openBackupScheduleModal(resource: ResourceRecord, type: 'qemu' | 'lxc', schedule?: BackupSchedule) {
    setBackupScheduleTarget({ resource, type, schedule });
    setBackupScheduleError('');
    setOperationMessage('');
    setOperationError('');
    setBackupScheduleForm(schedule ? {
      storage: schedule.storage,
      mode: schedule.mode,
      compress: schedule.compress,
      notes: schedule.notes || '',
      frequency: schedule.frequency,
      time: schedule.time,
      dayOfWeek: String(schedule.dayOfWeek ?? 0),
      dayOfMonth: String(schedule.dayOfMonth ?? 1),
      retention: String(schedule.retention) as BackupScheduleForm['retention'],
      enabled: schedule.enabled !== false,
    } : defaultBackupScheduleForm(resource, dashboard));
  }

  function validateBackupScheduleForm() {
    const errors: string[] = [];
    const resource = backupScheduleTarget?.resource;
    if (!selectedConnectorId) {
      errors.push('Select a connector.');
    }
    if (!resource?.node || !resource.vmid) {
      errors.push('Resource is missing node or VM ID.');
    }
    if (!backupScheduleForm.storage) {
      errors.push('Select backup storage.');
    }
    if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(backupScheduleForm.time)) {
      errors.push('Use HH:mm schedule time.');
    }
    return errors;
  }

  async function submitBackupSchedule() {
    if (!backupScheduleTarget || !selectedConnectorId) {
      setBackupScheduleError('Select a resource and connector.');
      return;
    }
    const errors = validateBackupScheduleForm();
    if (errors.length) {
      setBackupScheduleError(errors.join(' '));
      return;
    }

    setBackupScheduleSubmitting(true);
    setBackupScheduleError('');
    setOperationMessage('');
    setOperationError('');

    const input = {
      connectorId: selectedConnectorId,
      resourceType: backupScheduleTarget.type,
      node: backupScheduleTarget.resource.node || '',
      vmid: Number(backupScheduleTarget.resource.vmid),
      resourceName: backupScheduleTarget.resource.name || '',
      storage: backupScheduleForm.storage,
      mode: backupScheduleForm.mode,
      compress: backupScheduleForm.compress,
      notes: backupScheduleForm.notes.trim(),
      frequency: backupScheduleForm.frequency,
      time: backupScheduleForm.time,
      dayOfWeek: Number(backupScheduleForm.dayOfWeek),
      dayOfMonth: Number(backupScheduleForm.dayOfMonth),
      retention: Number(backupScheduleForm.retention) as 7 | 14 | 30,
      enabled: backupScheduleForm.enabled,
    };

    try {
      const response = backupScheduleTarget.schedule
        ? await dashboardService.updateBackupSchedule(backupScheduleTarget.schedule.id, input)
        : await dashboardService.createBackupSchedule(input);
      setOperationMessage(response.data.message);
      setBackupScheduleTarget(null);
      await loadBackupSchedules(false);
    } catch (err) {
      setBackupScheduleError(err instanceof Error ? err.message : 'Unable to save backup schedule.');
    } finally {
      setBackupScheduleSubmitting(false);
    }
  }

  function removeBackupSchedule(schedule: BackupSchedule) {
    openSafetyDelete({
      eyebrow: 'Backup Scheduler',
      title: `Delete backup schedule ${schedule.resourceName || schedule.vmid}`,
      message: 'This removes the backup schedule. Existing backup files are not deleted.',
      expected: schedule.id,
      details: [
        { label: 'Resource', value: `${schedule.resourceType === 'lxc' ? 'Container' : 'VM'} ${schedule.resourceName || schedule.vmid}` },
        { label: 'Node', value: schedule.node },
        { label: 'Schedule ID', value: <span className="break-all">{schedule.id}</span> },
      ],
      confirmLabel: 'Delete Schedule',
      onConfirm: async (confirmation) => {
        setBackupScheduleError('');
        setOperationMessage('');
        try {
          const response = await dashboardService.deleteBackupSchedule(schedule.id, confirmation);
          setOperationMessage(response.data.message);
          await loadBackupSchedules(false);
        } catch (err) {
          setBackupScheduleError(err instanceof Error ? err.message : 'Unable to delete backup schedule.');
          throw err;
        }
      },
    });
  }

  async function openBackupHistory(resource: ResourceRecord, type: 'qemu' | 'lxc') {
    if (!resource.node || !resource.vmid) {
      setOperationError('Resource is missing node or VM ID.');
      return;
    }
    setBackupHistoryTarget({ resource, type });
    setBackupHistory([]);
    setBackupHistoryError('');
    setBackupHistoryLoading(true);
    try {
      const response = await dashboardService.getResourceBackups({
        type,
        node: resource.node,
        vmid: resource.vmid,
      });
      setBackupHistory(response.data.backups);
    } catch (err) {
      setBackupHistoryError(err instanceof Error ? err.message : 'Unable to load backup history.');
    } finally {
      setBackupHistoryLoading(false);
    }
  }

  function openRestoreModal(backup: BackupVolume) {
    if (!backupHistoryTarget) {
      return;
    }
    setRestoreTarget({ ...backupHistoryTarget, backup });
    setRestoreForm(defaultRestoreForm(backupHistoryTarget.resource, backup, dashboard));
    setRestoreError('');
  }

  async function submitRestore() {
    if (!restoreTarget?.resource.node || !restoreTarget.resource.vmid) {
      setRestoreError('Source resource is missing node or VM ID.');
      return;
    }
    const targetVmid = Number(restoreForm.targetVmid);
    if (!restoreForm.archive || !restoreForm.targetNode || !Number.isInteger(targetVmid) || targetVmid <= 0) {
      setRestoreError('Select a backup, target node, and target VM/CT ID.');
      return;
    }
    if (restoreForm.restoreMode === 'same' && targetVmid !== Number(restoreTarget.resource.vmid)) {
      setRestoreError('Same-ID restore must use the original VM/CT ID.');
      return;
    }
    if (restoreForm.restoreMode === 'new' && targetVmid === Number(restoreTarget.resource.vmid)) {
      setRestoreError('Choose a different VM/CT ID for a new-ID restore.');
      return;
    }
    if (restoreForm.restoreMode === 'new' && !restoreForm.targetName.trim()) {
      setRestoreError('Enter a target VM/CT name.');
      return;
    }
    if (resourceIdExists(dashboard, targetVmid) && !restoreForm.force) {
      setRestoreError(`VM/CT ID ${targetVmid} already exists. Enable force only when overwriting an existing target.`);
      return;
    }
    if (restoreForm.confirmation.trim() !== String(targetVmid)) {
      setRestoreError('Type the target VM/CT ID to confirm restore.');
      return;
    }

    setRestoreSubmitting(true);
    setRestoreError('');
    setOperationMessage('');
    setOperationError('');
    try {
      const response = await dashboardService.restoreResource({
        type: restoreTarget.type,
        node: restoreTarget.resource.node,
        vmid: restoreTarget.resource.vmid,
        archive: restoreForm.archive,
        restoreMode: restoreForm.restoreMode,
        targetNode: restoreForm.targetNode,
        targetVmid,
        targetName: restoreForm.targetName.trim(),
        targetStorage: restoreForm.targetStorage,
        force: restoreForm.force,
        confirmation: restoreForm.confirmation.trim(),
      });
      setOperationMessage(response.data.message);
      setRestoreTarget(null);
      setBackupHistoryTarget(null);
      await loadDashboard();
    } catch (err) {
      setRestoreError(err instanceof Error ? err.message : 'Unable to restore backup.');
    } finally {
      setRestoreSubmitting(false);
    }
  }

  function setRestoreMode(mode: 'same' | 'new') {
    if (!restoreTarget) {
      return;
    }
    const targetVmid = mode === 'same'
      ? String(restoreTarget.resource.vmid || '')
      : String(nextAvailableVmId(dashboard, Number(restoreTarget.resource.vmid || 100) + 1));
    setRestoreForm((current) => ({
      ...current,
      restoreMode: mode,
      targetVmid,
      targetName: mode === 'same'
        ? String(restoreTarget.resource.name || '')
        : `${restoreTarget.resource.name || `restored-${restoreTarget.resource.vmid || 'vm'}`}-restore`,
      force: mode === 'same',
      confirmation: '',
    }));
  }

  function validateCloneForm() {
    const errors: string[] = [];
    const newId = Number(cloneForm.newid);
    const existingIds = [
      ...(dashboard?.resources.vms || []),
      ...(dashboard?.resources.vmTemplates || []),
      ...(dashboard?.resources.containers || []),
    ]
      .map((item) => Number(item.vmid))
      .filter((value) => Number.isInteger(value));

    if (!Number.isInteger(newId) || newId <= 0) {
      errors.push('Enter a positive VM ID.');
    } else if (existingIds.includes(newId)) {
      errors.push(`VM ID ${newId} is already in use.`);
    }

    if (!cloneForm.name.trim()) {
      errors.push('Enter a new VM name.');
    }
    if (!cloneForm.target) {
      errors.push('Select a target node.');
    }
    if (!cloneForm.storage) {
      errors.push('Select target storage.');
    }

    const storageValid = (dashboard?.resources.storage || []).some(
      (item) => item.storage === cloneForm.storage && (!item.node || !cloneForm.target || item.node === cloneForm.target),
    );
    if (cloneForm.storage && !storageValid) {
      errors.push('Selected storage is not valid for the target node.');
    }

    return errors;
  }

  async function submitClone() {
    if (!cloneTarget?.node || !cloneTarget.vmid) {
      setCloneError('Source VM is missing node or VM ID.');
      return;
    }

    const errors = validateCloneForm();
    if (errors.length) {
      setCloneError(errors.join(' '));
      return;
    }

    setCloneSubmitting(true);
    setCloneError('');
    setOperationMessage('');
    setOperationError('');

    try {
      const response = await dashboardService.cloneVM({
        node: cloneTarget.node,
        vmid: cloneTarget.vmid,
        newid: Number(cloneForm.newid),
        name: cloneForm.name.trim(),
        target: cloneForm.target,
        storage: cloneForm.storage,
        full: cloneForm.full,
        description: cloneForm.description.trim(),
      });
      setOperationMessage(response.data.message);
      setCloneTarget(null);
      await loadDashboard();
    } catch (err) {
      setCloneError(err instanceof Error ? err.message : 'Unable to clone VM.');
    } finally {
      setCloneSubmitting(false);
    }
  }

  function openDeleteModal(resource: ResourceRecord, type: 'qemu' | 'lxc' = 'qemu') {
    setDeleteTarget(resource);
    setDeleteTargetType(type);
    setDeleteConfirmation('');
    setDeleteForce(false);
    setDeleteError('');
    setOperationMessage('');
    setOperationError('');
  }

  function deleteConfirmationMatches() {
    if (!deleteTarget) {
      return false;
    }
    const value = deleteConfirmation.trim();
    return value === String(deleteTarget.vmid || '') || value === String(deleteTarget.name || '').trim();
  }

  async function submitDelete() {
    const label = deleteTargetType === 'qemu' ? 'VM' : 'container';
    if (!deleteTarget?.node || !deleteTarget.vmid) {
      setDeleteError(`Source ${label} is missing node or ID.`);
      return;
    }
    if (!deleteConfirmationMatches()) {
      setDeleteError(`Type the ${label} name or ID to confirm deletion.`);
      return;
    }

    setDeleteSubmitting(true);
    setDeleteError('');
    setOperationMessage('');
    setOperationError('');

    try {
      const response = await dashboardService.deleteVM({
        type: deleteTargetType,
        node: deleteTarget.node,
        vmid: deleteTarget.vmid,
        confirmation: deleteConfirmation.trim(),
        force: deleteForce,
      });
      setOperationMessage(response.data.message);
      setDeleteTarget(null);
      await loadDashboard();
    } catch (err) {
      setDeleteError(err instanceof Error ? err.message : `Unable to delete ${label}.`);
    } finally {
      setDeleteSubmitting(false);
    }
  }

  function openTemplateModal(resource: ResourceRecord) {
    setTemplateTarget(resource);
    setTemplateConfirmation('');
    setTemplateError('');
    setOperationMessage('');
    setOperationError('');
  }

  function templateConfirmationMatches() {
    if (!templateTarget) {
      return false;
    }
    const value = templateConfirmation.trim();
    return value === String(templateTarget.vmid || '') || value === String(templateTarget.name || '').trim();
  }

  async function submitTemplateConversion() {
    if (!templateTarget?.node || !templateTarget.vmid) {
      setTemplateError('Source VM is missing node or VM ID.');
      return;
    }
    if (templateTarget.status === 'running') {
      setTemplateError('Stop the VM before converting it to a template.');
      return;
    }
    if (!templateConfirmationMatches()) {
      setTemplateError('Type the VM name or VM ID to confirm template conversion.');
      return;
    }

    setTemplateSubmitting(true);
    setTemplateError('');
    setOperationMessage('');
    setOperationError('');

    try {
      const response = await dashboardService.convertVMToTemplate({
        node: templateTarget.node,
        vmid: templateTarget.vmid,
        confirmation: templateConfirmation.trim(),
      });
      setOperationMessage(response.data.message);
      setTemplateTarget(null);
      await loadDashboard();
    } catch (err) {
      setTemplateError(err instanceof Error ? err.message : 'Unable to convert VM to template.');
    } finally {
      setTemplateSubmitting(false);
    }
  }

  function renderVirtualMachineManager(rows: ResourceRecord[]) {
    function renderUsageMeter(percent: number | null, detail?: string) {
      if (percent === null) {
        return <span className="text-slate-500">-</span>;
      }
      const toneClass = percent >= 90 ? 'vm-usage-critical' : percent >= 75 ? 'vm-usage-warning' : 'vm-usage-normal';
      return (
        <div className="vm-usage-cell">
          <span className="vm-usage-percent">{percent}%</span>
          <span className="vm-usage-track" aria-hidden="true">
            <span className={`vm-usage-fill ${toneClass}`} style={{ width: `${percent}%` }} />
          </span>
          {detail ? <span className="vm-usage-detail">{detail}</span> : null}
        </div>
      );
    }

    const normalizedSearch = vmSearch.trim().toLowerCase();
    const filteredRows = rows.filter((resource) => {
      const status = String(resource.status || 'unknown').toLowerCase();
      const matchesStatus = vmStatusFilter === 'all' || status === vmStatusFilter;
      const searchable = [resource.vmid, resource.name, resource.node, resource.status, resource.type]
        .map((value) => String(value || '').toLowerCase())
        .join(' ');
      return matchesStatus && (!normalizedSearch || searchable.includes(normalizedSearch));
    });
    const selectedVm = filteredRows.find((resource) => resourceKey('qemu', resource) === selectedVmKey) || filteredRows[0] || null;
    const selectedVmName = selectedVm?.name || (selectedVm?.vmid ? `VM ${selectedVm.vmid}` : 'No VM selected');
    const selectedVmStatus = String(selectedVm?.status || 'unknown').toLowerCase();
    const canStart = Boolean(selectedVm && canRunAction(selectedVm, 'start', 'qemu'));
    const canShutdown = Boolean(selectedVm && canRunAction(selectedVm, 'shutdown', 'qemu'));
    const canStop = Boolean(selectedVm && canRunAction(selectedVm, 'stop', 'qemu'));
    const canReboot = Boolean(selectedVm && canRunAction(selectedVm, 'reboot', 'qemu'));
    const canSuspend = Boolean(selectedVm && canRunAction(selectedVm, 'suspend', 'qemu'));
    const vmToolbarDisabled = !selectedVm || Boolean(actionInFlight);
    const selectedActionBusy = selectedVm ? actionInFlight.startsWith(`${resourceKey('qemu', selectedVm)}-`) : false;
    const toolbarUnsupportedMessage = selectedVm ? 'This workflow is not available yet.' : 'Select a VM first.';

    return (
      <section className="vm-manager-shell">
        <div className="vm-manager-card">
          <div className="vm-manager-titlebar">
            <div className="flex min-w-0 items-center gap-3">
              <span aria-hidden="true" className="vm-manager-title-icon">VM</span>
              <div className="min-w-0">
                <h3 className="truncate text-xl font-semibold text-slate-950">Virtual machines</h3>
                <p className="text-xs text-slate-600">Select a VM, then use the command bar for validated operations.</p>
              </div>
            </div>
            <div className="text-right text-xs text-slate-600">
              <p className="font-semibold text-slate-900">{rows.length} total</p>
              <p>{filteredRows.length} shown</p>
            </div>
          </div>

          <div className="vm-commandbar" role="toolbar" aria-label="Virtual machine commands">
            <button className="vm-command-button vm-command-primary" onClick={openCreateVmModal} type="button">
              <span aria-hidden="true">+</span>
              ADD
            </button>
            <button className="vm-command-button vm-command-muted" disabled title={toolbarUnsupportedMessage} type="button">
              <span aria-hidden="true">E</span>
              EDIT
            </button>
            <button
              className="vm-command-button vm-command-danger"
              disabled={vmToolbarDisabled || deleteSubmitting}
              onClick={() => selectedVm && openDeleteModal(selectedVm)}
              type="button"
            >
              <span aria-hidden="true">X</span>
              Delete
            </button>
            <span className="vm-command-separator" aria-hidden="true" />
            <button
              className="vm-command-button vm-command-start"
              disabled={!canStart || Boolean(actionInFlight)}
              onClick={() => selectedVm && requestOperation(selectedVm, 'qemu', 'start')}
              title="Start selected VM"
              type="button"
            >
              <span aria-hidden="true">&gt;</span>
              Start
            </button>
            <button
              className="vm-command-button vm-command-stop"
              disabled={!canStop || Boolean(actionInFlight)}
              onClick={() => selectedVm && requestOperation(selectedVm, 'qemu', 'stop')}
              type="button"
            >
              <span aria-hidden="true">S</span>
              Power Off
            </button>
            <button
              className="vm-command-button vm-command-restart"
              disabled={!canReboot || Boolean(actionInFlight)}
              onClick={() => selectedVm && requestOperation(selectedVm, 'qemu', 'reboot')}
              type="button"
            >
              <span aria-hidden="true">R</span>
              RESTART
            </button>
            <button
              className="vm-command-button vm-command-muted"
              disabled={!canShutdown || Boolean(actionInFlight)}
              onClick={() => selectedVm && requestOperation(selectedVm, 'qemu', 'shutdown')}
              type="button"
            >
              Shutdown
            </button>
            <button
              className="vm-command-button vm-command-muted"
              disabled={!canSuspend || Boolean(actionInFlight)}
              onClick={() => selectedVm && requestOperation(selectedVm, 'qemu', 'suspend')}
              type="button"
            >
              Suspend
            </button>
            <button
              className="vm-command-button vm-command-blue"
              disabled={vmToolbarDisabled || cloneSubmitting}
              onClick={() => selectedVm && openCloneModal(selectedVm)}
              type="button"
            >
              Clone
            </button>
            <button
              className="vm-command-button vm-command-warning"
              disabled={vmToolbarDisabled || templateSubmitting || selectedVm?.status === 'running'}
              onClick={() => selectedVm && openTemplateModal(selectedVm)}
              type="button"
            >
              Template
            </button>
            <button
              className="vm-command-button vm-command-blue"
              disabled={vmToolbarDisabled || backupSubmitting}
              onClick={() => selectedVm && openBackupModal(selectedVm, 'qemu')}
              type="button"
            >
              Backup
            </button>
            <button
              className="vm-command-button vm-command-blue"
              disabled={vmToolbarDisabled || backupScheduleSubmitting}
              onClick={() => selectedVm && openBackupScheduleModal(selectedVm, 'qemu')}
              type="button"
            >
              Schedule
            </button>
            <button
              className="vm-command-button vm-command-muted"
              disabled={!selectedVm || backupHistoryLoading}
              onClick={() => selectedVm && void openBackupHistory(selectedVm, 'qemu')}
              type="button"
            >
              History
            </button>
            <span className="vm-command-separator" aria-hidden="true" />
            {['Rebuild', 'Password', 'Disks', 'Interfaces', 'IP addresses', 'Information'].map((label) => (
              <button className="vm-command-button vm-command-muted" disabled key={label} title="This VM tool is not available yet." type="button">
                {label}
              </button>
            ))}
            <button
              className="vm-command-button vm-command-vnc"
              disabled={!selectedVm || Boolean(consoleLoading)}
              onClick={() => selectedVm && void launchConsole(selectedVm, 'qemu')}
              type="button"
            >
              VNC
            </button>
          </div>

          <div className="vm-manager-filterbar">
            <label className="sr-only" htmlFor="vm-search">Search virtual machines</label>
            <input
              className="vm-search-input"
              id="vm-search"
              onChange={(event) => setVmSearch(event.target.value)}
              placeholder="Search"
              type="search"
              value={vmSearch}
            />
            <label className="sr-only" htmlFor="vm-status-filter">Filter virtual machines</label>
            <select
              className="vm-filter-select"
              id="vm-status-filter"
              onChange={(event) => setVmStatusFilter(event.target.value)}
              value={vmStatusFilter}
            >
              <option value="all">All statuses</option>
              <option value="running">Running</option>
              <option value="stopped">Stopped</option>
              <option value="paused">Paused</option>
              <option value="unknown">Unknown</option>
            </select>
            <button className="vm-filter-button" onClick={() => { setVmSearch(''); setVmStatusFilter('all'); }} type="button">
              Clear filters
            </button>
            <div className="ml-auto min-w-0 text-xs text-slate-600">
              Selected: <span className="font-semibold text-slate-950">{selectedVmName}</span>
              <span className={`ml-2 vm-status-pill vm-status-${selectedVmStatus}`}>{selectedVmStatus}</span>
            </div>
          </div>

          {rows.length === 0 ? (
            <div className="pm-muted-panel m-4">No virtual machines available for operations.</div>
          ) : filteredRows.length === 0 ? (
            <div className="pm-muted-panel m-4">No virtual machines match the current search or filter.</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="vm-manager-table">
                <thead>
                  <tr>
                    {[
                      'Id',
                      'Name',
                      'Domain name',
                      'Cluster node',
                      'CPU usage',
                      'Memory usage',
                      'Uptime',
                      'Owner',
                      'IPv4 address',
                      'IPv6 address',
                      'OS',
                      'RAM, MiB',
                      'Number of cores',
                      'Disk size, MiB',
                      'Status',
                    ].map((heading) => (
                      <th key={heading}>{heading}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {filteredRows.map((resource) => {
                    const key = resourceKey('qemu', resource);
                    const extended = resource as ResourceRecord & {
                      cpus?: number;
                      cores?: number;
                      ip?: string;
                      ip4?: string;
                      ip6?: string;
                      owner?: string;
                      os?: string;
                      ostype?: string;
                    };
                    const isSelected = selectedVm ? key === resourceKey('qemu', selectedVm) : false;
                    const status = String(resource.status || 'unknown').toLowerCase();
                    const cpuPercent = normalizeUsagePercent(resource.cpu);
                    const memoryPercent = resource.maxmem ? normalizeUsagePercent(Number(resource.mem || 0) / Number(resource.maxmem || 1)) : null;
                    const memoryDetail = resource.maxmem ? `${formatMib(resource.mem)} / ${formatMib(resource.maxmem)} MiB` : undefined;
                    return (
                      <tr
                        aria-selected={isSelected}
                        className={isSelected ? 'vm-row-selected' : ''}
                        key={key}
                        onClick={() => setSelectedVmKey(key)}
                        onKeyDown={(event) => {
                          if (event.key === 'Enter' || event.key === ' ') {
                            event.preventDefault();
                            setSelectedVmKey(key);
                          }
                        }}
                        tabIndex={0}
                      >
                        <td>{resource.vmid || '-'}</td>
                        <td className="font-semibold text-slate-950">{resource.name || '-'}</td>
                        <td>-</td>
                        <td>{resource.node || '-'}</td>
                        <td>{renderUsageMeter(cpuPercent)}</td>
                        <td>{renderUsageMeter(memoryPercent, memoryDetail)}</td>
                        <td>{formatUptime(resource.uptime)}</td>
                        <td>{extended.owner || '-'}</td>
                        <td>{extended.ip4 || extended.ip || '-'}</td>
                        <td>{extended.ip6 || '-'}</td>
                        <td>{extended.os || extended.ostype || (resource.template ? 'Template' : '-')}</td>
                        <td>{formatMib(resource.maxmem || resource.mem)}</td>
                        <td>{extended.cores || extended.cpus || '-'}</td>
                        <td>{formatMib(resource.maxdisk || resource.disk)}</td>
                        <td>
                          <span className={`vm-status-pill vm-status-${status}`}>{status}</span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          {selectedActionBusy ? (
            <div className="border-t border-slate-200 bg-cyan-50 px-4 py-3 text-xs font-semibold text-cyan-900">
              Operation is running for {selectedVmName}.
            </div>
          ) : null}
        </div>
      </section>
    );
  }

  function renderContainerManager(rows: ResourceRecord[]) {
    function renderUsageMeter(percent: number | null, detail?: string) {
      if (percent === null) {
        return <span className="text-slate-500">-</span>;
      }
      const toneClass = percent >= 90 ? 'vm-usage-critical' : percent >= 75 ? 'vm-usage-warning' : 'vm-usage-normal';
      return (
        <div className="vm-usage-cell">
          <span className="vm-usage-percent">{percent}%</span>
          <span className="vm-usage-track" aria-hidden="true">
            <span className={`vm-usage-fill ${toneClass}`} style={{ width: `${percent}%` }} />
          </span>
          {detail ? <span className="vm-usage-detail">{detail}</span> : null}
        </div>
      );
    }

    const normalizedSearch = containerSearch.trim().toLowerCase();
    const filteredRows = rows.filter((resource) => {
      const extended = resource as ResourceRecord & { hostname?: string; ip?: string; ip4?: string; ip6?: string; os?: string; ostype?: string };
      const status = String(resource.status || 'unknown').toLowerCase();
      const matchesStatus = containerStatusFilter === 'all' || status === containerStatusFilter;
      const searchable = [
        resource.vmid,
        resource.name,
        extended.hostname,
        resource.node,
        resource.status,
        resource.type,
        extended.ip,
        extended.ip4,
      ]
        .map((value) => String(value || '').toLowerCase())
        .join(' ');
      return matchesStatus && (!normalizedSearch || searchable.includes(normalizedSearch));
    });
    const selectedContainer = filteredRows.find((resource) => resourceKey('lxc', resource) === selectedContainerKey) || filteredRows[0] || null;
    const selectedContainerName = selectedContainer?.name || (selectedContainer?.vmid ? `CT ${selectedContainer.vmid}` : 'No container selected');
    const selectedContainerStatus = String(selectedContainer?.status || 'unknown').toLowerCase();
    const canStart = Boolean(selectedContainer && canRunAction(selectedContainer, 'start', 'lxc'));
    const canShutdown = Boolean(selectedContainer && canRunAction(selectedContainer, 'shutdown', 'lxc'));
    const canStop = Boolean(selectedContainer && canRunAction(selectedContainer, 'stop', 'lxc'));
    const canReboot = Boolean(selectedContainer && canRunAction(selectedContainer, 'reboot', 'lxc'));
    const canSuspend = Boolean(selectedContainer && canRunAction(selectedContainer, 'suspend', 'lxc'));
    const containerToolbarDisabled = !selectedContainer || Boolean(actionInFlight);
    const selectedActionBusy = selectedContainer ? actionInFlight.startsWith(`${resourceKey('lxc', selectedContainer)}-`) : false;
    const toolbarUnsupportedMessage = selectedContainer ? 'This container workflow is not available yet.' : 'Select a container first.';

    return (
      <section className="vm-manager-shell">
        <div className="vm-manager-card">
          <div className="vm-manager-titlebar">
            <div className="flex min-w-0 items-center gap-3">
              <span aria-hidden="true" className="vm-manager-title-icon">CT</span>
              <div className="min-w-0">
                <h3 className="truncate text-xl font-semibold text-slate-950">Containers</h3>
                <p className="text-xs text-slate-600">Select a container, then use the command bar for validated operations.</p>
              </div>
            </div>
            <div className="text-right text-xs text-slate-600">
              <p className="font-semibold text-slate-900">{rows.length} total</p>
              <p>{filteredRows.length} shown</p>
            </div>
          </div>

          <div className="vm-commandbar" role="toolbar" aria-label="Container commands">
            <button className="vm-command-button vm-command-primary" onClick={openCreateContainerModal} type="button">
              <span aria-hidden="true">+</span>
              ADD
            </button>
            <button className="vm-command-button vm-command-muted" disabled title={toolbarUnsupportedMessage} type="button">
              <span aria-hidden="true">E</span>
              EDIT
            </button>
            <button
              className="vm-command-button vm-command-danger"
              disabled={containerToolbarDisabled || deleteSubmitting}
              onClick={() => selectedContainer && openDeleteModal(selectedContainer, 'lxc')}
              type="button"
            >
              <span aria-hidden="true">X</span>
              Delete
            </button>
            <span className="vm-command-separator" aria-hidden="true" />
            <button
              className="vm-command-button vm-command-start"
              disabled={!canStart || Boolean(actionInFlight)}
              onClick={() => selectedContainer && requestOperation(selectedContainer, 'lxc', 'start')}
              title="Start selected container"
              type="button"
            >
              <span aria-hidden="true">&gt;</span>
              Start
            </button>
            <button
              className="vm-command-button vm-command-stop"
              disabled={!canStop || Boolean(actionInFlight)}
              onClick={() => selectedContainer && requestOperation(selectedContainer, 'lxc', 'stop')}
              type="button"
            >
              <span aria-hidden="true">S</span>
              Power Off
            </button>
            <button
              className="vm-command-button vm-command-restart"
              disabled={!canReboot || Boolean(actionInFlight)}
              onClick={() => selectedContainer && requestOperation(selectedContainer, 'lxc', 'reboot')}
              type="button"
            >
              <span aria-hidden="true">R</span>
              RESTART
            </button>
            <button
              className="vm-command-button vm-command-muted"
              disabled={!canShutdown || Boolean(actionInFlight)}
              onClick={() => selectedContainer && requestOperation(selectedContainer, 'lxc', 'shutdown')}
              type="button"
            >
              Shutdown
            </button>
            <button
              className="vm-command-button vm-command-muted"
              disabled={!canSuspend || Boolean(actionInFlight)}
              onClick={() => selectedContainer && requestOperation(selectedContainer, 'lxc', 'suspend')}
              title="Suspend is only available for supported virtual machines."
              type="button"
            >
              Suspend
            </button>
            <button
              className="vm-command-button vm-command-blue"
              disabled={containerToolbarDisabled || backupSubmitting}
              onClick={() => selectedContainer && openBackupModal(selectedContainer, 'lxc')}
              type="button"
            >
              Backup
            </button>
            <button
              className="vm-command-button vm-command-blue"
              disabled={containerToolbarDisabled || backupScheduleSubmitting}
              onClick={() => selectedContainer && openBackupScheduleModal(selectedContainer, 'lxc')}
              type="button"
            >
              Schedule
            </button>
            <button
              className="vm-command-button vm-command-muted"
              disabled={!selectedContainer || backupHistoryLoading}
              onClick={() => selectedContainer && void openBackupHistory(selectedContainer, 'lxc')}
              type="button"
            >
              History
            </button>
            <span className="vm-command-separator" aria-hidden="true" />
            {['Rebuild', 'Password', 'Disks', 'Interfaces', 'IP addresses', 'Information'].map((label) => (
              <button className="vm-command-button vm-command-muted" disabled key={label} title="This container tool is not available yet." type="button">
                {label}
              </button>
            ))}
            <button
              className="vm-command-button vm-command-vnc"
              disabled={!selectedContainer || Boolean(consoleLoading)}
              onClick={() => selectedContainer && void launchConsole(selectedContainer, 'lxc')}
              type="button"
            >
              VNC
            </button>
          </div>

          <div className="vm-manager-filterbar">
            <label className="sr-only" htmlFor="container-search">Search containers</label>
            <input
              className="vm-search-input"
              id="container-search"
              onChange={(event) => setContainerSearch(event.target.value)}
              placeholder="Search"
              type="search"
              value={containerSearch}
            />
            <label className="sr-only" htmlFor="container-status-filter">Filter containers</label>
            <select
              className="vm-filter-select"
              id="container-status-filter"
              onChange={(event) => setContainerStatusFilter(event.target.value)}
              value={containerStatusFilter}
            >
              <option value="all">All statuses</option>
              <option value="running">Running</option>
              <option value="stopped">Stopped</option>
              <option value="paused">Paused</option>
              <option value="unknown">Unknown</option>
            </select>
            <button className="vm-filter-button" onClick={() => { setContainerSearch(''); setContainerStatusFilter('all'); }} type="button">
              Clear filters
            </button>
            <div className="ml-auto min-w-0 text-xs text-slate-600">
              Selected: <span className="font-semibold text-slate-950">{selectedContainerName}</span>
              <span className={`ml-2 vm-status-pill vm-status-${selectedContainerStatus}`}>{selectedContainerStatus}</span>
            </div>
          </div>

          {rows.length === 0 ? (
            <div className="pm-muted-panel m-4">No containers available for operations.</div>
          ) : filteredRows.length === 0 ? (
            <div className="pm-muted-panel m-4">No containers match the current search or filter.</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="vm-manager-table">
                <thead>
                  <tr>
                    {[
                      'Id',
                      'Name',
                      'Hostname',
                      'Cluster node',
                      'CPU usage',
                      'Memory usage',
                      'Uptime',
                      'Owner',
                      'IPv4 address',
                      'IPv6 address',
                      'OS',
                      'RAM, MiB',
                      'Disk size, MiB',
                      'Status',
                    ].map((heading) => (
                      <th key={heading}>{heading}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {filteredRows.map((resource) => {
                    const key = resourceKey('lxc', resource);
                    const extended = resource as ResourceRecord & {
                      hostname?: string;
                      ip?: string;
                      ip4?: string;
                      ip6?: string;
                      owner?: string;
                      os?: string;
                      ostype?: string;
                    };
                    const isSelected = selectedContainer ? key === resourceKey('lxc', selectedContainer) : false;
                    const status = String(resource.status || 'unknown').toLowerCase();
                    const cpuPercent = normalizeUsagePercent(resource.cpu);
                    const memoryPercent = resource.maxmem ? normalizeUsagePercent(Number(resource.mem || 0) / Number(resource.maxmem || 1)) : null;
                    const memoryDetail = resource.maxmem ? `${formatMib(resource.mem)} / ${formatMib(resource.maxmem)} MiB` : undefined;
                    const displayName = resource.name || extended.hostname || '-';
                    return (
                      <tr
                        aria-selected={isSelected}
                        className={isSelected ? 'vm-row-selected' : ''}
                        key={key}
                        onClick={() => setSelectedContainerKey(key)}
                        onKeyDown={(event) => {
                          if (event.key === 'Enter' || event.key === ' ') {
                            event.preventDefault();
                            setSelectedContainerKey(key);
                          }
                        }}
                        tabIndex={0}
                      >
                        <td>{resource.vmid || '-'}</td>
                        <td className="font-semibold text-slate-950">{displayName}</td>
                        <td>{extended.hostname || resource.name || '-'}</td>
                        <td>{resource.node || '-'}</td>
                        <td>{renderUsageMeter(cpuPercent)}</td>
                        <td>{renderUsageMeter(memoryPercent, memoryDetail)}</td>
                        <td>{formatUptime(resource.uptime)}</td>
                        <td>{extended.owner || '-'}</td>
                        <td>{extended.ip4 || extended.ip || '-'}</td>
                        <td>{extended.ip6 || '-'}</td>
                        <td>{extended.os || extended.ostype || 'LXC'}</td>
                        <td>{formatMib(resource.maxmem || resource.mem)}</td>
                        <td>{formatMib(resource.maxdisk || resource.disk)}</td>
                        <td>
                          <span className={`vm-status-pill vm-status-${status}`}>{status}</span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          {selectedActionBusy ? (
            <div className="border-t border-slate-200 bg-cyan-50 px-4 py-3 text-xs font-semibold text-cyan-900">
              Operation is running for {selectedContainerName}.
            </div>
          ) : null}
        </div>
      </section>
    );
  }

  function renderOperationsTable(title: string, type: 'qemu' | 'lxc', rows: ResourceRecord[]) {
    if (type === 'qemu') {
      return renderVirtualMachineManager(rows);
    }
    return renderContainerManager(rows);
  }

  function renderStorageTable() {
    if (!storageConfigs.length) {
      return (
        <div className="pm-muted-panel">
          No storage configuration found.
        </div>
      );
    }

    return (
      <section className="pm-card">
        <div className="overflow-x-auto">
          <table className="pm-table">
            <thead>
              <tr>
                {['Storage ID', 'Type', 'Nodes', 'Content', 'Enabled', 'Shared', 'Usage', 'Actions'].map((heading) => (
                  <th key={heading}>
                    {heading}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {storageConfigs.map((storage) => {
                const matchingResources = storageResources.filter((resource) => resource.storage === storage.storage);
                const usage = matchingResources.find((resource) => Number(resource.maxdisk || 0) > 0);
                const used = Number(usage?.disk || 0);
                const total = Number(usage?.maxdisk || 0);
                const enabled = !(storage.disable === true || storage.disable === 1);
                return (
                  <tr key={storage.storage}>
                    <td className="font-medium text-slate-900">{storage.storage}</td>
                    <td>{storage.type || '-'}</td>
                    <td>
                      {storage.nodes || matchingResources.map((resource) => resource.node).filter(Boolean).join(', ') || 'All'}
                    </td>
                    <td className="max-w-xs">
                      <span className="line-clamp-2">{storage.content || '-'}</span>
                    </td>
                    <td>
                      <span className={`pm-status ${
                        enabled ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-700'
                      }`}>
                        {enabled ? 'Enabled' : 'Disabled'}
                      </span>
                    </td>
                    <td>
                      {storage.shared === true || storage.shared === 1 ? 'Yes' : 'No'}
                    </td>
                    <td>
                      {total ? `${formatBytes(used)} / ${formatBytes(total)}` : '-'}
                    </td>
                    <td>
                      <ActionMenu
                        items={[
                          { label: 'Content', tone: 'primary', onClick: () => void openStorageContent(storage) },
                          { label: 'Edit', onClick: () => openEditStorageModal(storage) },
                          {
                            label: 'Delete',
                            tone: 'danger',
                            onClick: () => {
                              setStorageDeleteTarget(storage);
                              setStorageDeleteConfirmation('');
                            },
                          },
                        ]}
                      />
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </section>
    );
  }

  function renderStorageTextField(field: keyof StorageConfigInput, label: string, placeholder = '') {
    return (
      <label className="text-sm font-medium text-slate-700" key={field}>
        {label}
        <input
          className="mt-1 w-full rounded-md border border-slate-300 px-3 py-2"
          onChange={(event) => setStorageForm((current) => ({ ...current, [field]: event.target.value }))}
          placeholder={placeholder}
          type={field === 'password' ? 'password' : 'text'}
          value={String(storageForm[field] || '')}
        />
      </label>
    );
  }

  function renderNetworkTable() {
    if (!networkInterfaces.length) {
      return (
        <div className="pm-muted-panel">
          No network interfaces found for this node.
        </div>
      );
    }

    return (
      <section className="pm-card">
        <div className="overflow-x-auto">
          <table className="pm-table">
            <thead>
              <tr>
                {['Interface', 'Type', 'Status', 'Method', 'Address', 'Gateway', 'Bridge Ports', 'VLAN', 'Comments', 'Actions'].map((heading) => (
                  <th key={heading}>
                    {heading}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {networkInterfaces.map((item) => (
                <tr key={item.iface}>
                  <td className="font-medium text-slate-900">{item.iface}</td>
                  <td>{item.type || '-'}</td>
                  <td>
                    <span className={`pm-status ${
                      item.active ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-700'
                    }`}>
                      {item.active ? 'Active' : 'Inactive'}
                    </span>
                  </td>
                  <td>{item.method || '-'}</td>
                  <td>{item.address || item.netmask ? `${item.address || '-'} ${item.netmask || ''}` : '-'}</td>
                  <td>{item.gateway || '-'}</td>
                  <td>{item.bridgePorts || '-'}</td>
                  <td>{item.vlanAware ? 'Aware' : '-'}</td>
                  <td className="max-w-xs">
                    <span className="line-clamp-2">{item.comments || '-'}</span>
                  </td>
                  <td>
                    <ActionMenu
                      items={[
                        { label: 'Edit', disabled: networkSaving, onClick: () => openEditNetworkModal(item) },
                        {
                          label: item.active ? 'Deactivate' : 'Activate',
                          disabled: networkSaving || item.iface === 'lo',
                          tone: item.active ? 'warning' : 'primary',
                          onClick: () => void changeNetworkActiveState(item, !item.active),
                        },
                        {
                          label: 'Remove',
                          disabled: networkSaving || item.iface === 'lo',
                          tone: 'danger',
                          onClick: () => void removeNetwork(item),
                        },
                      ]}
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    );
  }

  function renderTasksTable(rows: ProxmoxTask[]) {
    if (!rows.length) {
      return (
        <div className="pm-muted-panel">
          No jobs match the current view.
        </div>
      );
    }

    return (
      <section className="job-table-card">
        <div className="overflow-x-auto">
          <table className="pm-table job-table">
            <thead>
              <tr>
                {['Job', 'Timeline', 'Node', 'User name', 'Linked Resource', 'Status', 'Support', 'Actions'].map((heading) => (
                  <th key={heading}>
                    {heading}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((task) => {
                const linkedResource = getTaskLinkedResource(task);
                const cancelable = isTaskCancelable(task);
                const retryable = isTaskRetryable(task);
                return (
                  <tr key={task.upid || `${task.node}-${task.startedAt}-${task.description}`}>
                    <td className="min-w-64">
                      <p className="font-semibold text-slate-950">{task.description || task.type || 'Proxmox job'}</p>
                      <p className="mt-1 break-all text-xs text-slate-500">{task.upid || task.type || '-'}</p>
                    </td>
                    <td className="min-w-44">
                      <p className="font-medium text-slate-900">{formatLogDate(task.startedAt)}</p>
                      <p className="mt-1 text-xs text-slate-500">{task.endedAt ? `Ended ${formatLogDate(task.endedAt)}` : 'Still running'}</p>
                    </td>
                    <td>{task.node || '-'}</td>
                    <td>{task.user || '-'}</td>
                    <td>
                      {linkedResource ? (
                        <button
                          className="job-resource-link"
                          onClick={() => openLinkedTaskResource(task)}
                          type="button"
                        >
                          {getTaskResourceLabel(task)}
                        </button>
                      ) : (
                        <span className="text-slate-500">Not linked</span>
                      )}
                    </td>
                    <td>
                      <span className={`pm-status ${taskStatusClass(task)}`}>
                        {task.endedAt ? task.exitstatus || task.status || 'done' : 'running'}
                      </span>
                      {typeof task.progress === 'number' ? (
                        <p className="mt-1 text-xs text-slate-500">{task.progress}% progress</p>
                      ) : null}
                      {task.errorMessage ? (
                        <p className="mt-1 max-w-56 text-xs text-red-700">{task.errorMessage}</p>
                      ) : null}
                    </td>
                    <td>
                      <div className="flex flex-wrap gap-1.5">
                        <span className={`job-capability ${cancelable ? 'job-capability-active' : ''}`}>Cancel</span>
                        <span className={`job-capability ${retryable ? 'job-capability-active' : ''}`}>Retry</span>
                      </div>
                    </td>
                    <td>
                      <ActionMenu
                        items={[
                          { label: 'View Logs', tone: 'primary', disabled: !task.node || !task.upid, onClick: () => openTaskViewer(task) },
                          ...(cancelable
                            ? [{
                                label: 'Cancel',
                                tone: 'danger' as const,
                                onClick: () => {
                                  openTaskViewer(task);
                                  setTaskViewerTab('status');
                                },
                              }]
                            : []),
                          ...(retryable
                            ? [{
                                label: 'Retry',
                                tone: 'primary' as const,
                                onClick: () => {
                                  openTaskViewer(task);
                                  setTaskViewerTab('status');
                                },
                              }]
                            : []),
                          ...(linkedResource
                            ? [{
                                label: 'Open Resource',
                                tone: 'primary' as const,
                                onClick: () => openLinkedTaskResource(task),
                              }]
                            : []),
                        ]}
                      />
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </section>
    );
  }

  function renderClusterLogTable(rows: ClusterLogEntry[]) {
    if (!rows.length) {
      return (
        <div className="rounded-lg border border-dashed border-slate-300 bg-white p-6 text-sm text-slate-600">
          No cluster log entries found.
        </div>
      );
    }

    return (
      <section className="rounded-lg border border-slate-200 bg-white shadow-sm">
        <div className="overflow-x-auto">
          <table className="min-w-full border-separate border-spacing-0 text-left text-sm">
            <thead>
              <tr>
                {['Time', 'Node', 'User name', 'Priority', 'Message'].map((heading) => (
                  <th
                    className="border-b border-slate-200 bg-slate-50 px-3 py-3 text-xs font-semibold uppercase tracking-wide text-slate-500"
                    key={heading}
                  >
                    {heading}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((entry) => (
                <tr key={entry.id}>
                  <td className="border-b border-slate-100 px-3 py-3 font-medium text-slate-900">
                    {formatLogDate(entry.time)}
                  </td>
                  <td className="border-b border-slate-100 px-3 py-3 text-slate-700">{entry.node || '-'}</td>
                  <td className="border-b border-slate-100 px-3 py-3 text-slate-700">{entry.user || '-'}</td>
                  <td className="border-b border-slate-100 px-3 py-3 text-slate-700">{entry.priority || '-'}</td>
                  <td className="border-b border-slate-100 px-3 py-3 text-slate-900">{entry.message || '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    );
  }

  function renderAuditLogTable(rows: AuditLogEntry[]) {
    if (!rows.length) {
      return (
        <div className="rounded-lg border border-dashed border-slate-300 bg-white p-6 text-sm text-slate-600">
          No audit entries found.
        </div>
      );
    }

    return (
      <section className="rounded-lg border border-slate-200 bg-white shadow-sm">
        <div className="overflow-x-auto">
          <table className="min-w-full border-separate border-spacing-0 text-left text-sm">
            <thead>
              <tr>
                {['Time', 'User', 'Action', 'Status', 'Target', 'Message'].map((heading) => (
                  <th
                    className="border-b border-slate-200 bg-slate-50 px-3 py-3 text-xs font-semibold uppercase tracking-wide text-slate-500"
                    key={heading}
                  >
                    {heading}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((entry) => {
                const target = entry.resourceName
                  || entry.resourceId
                  || entry.connectorName
                  || entry.imageName
                  || entry.imageId
                  || entry.instanceId
                  || entry.vmid
                  || entry.taskId
                  || entry.node
                  || entry.connectorId
                  || '-';
                return (
                  <tr key={entry.id}>
                    <td className="border-b border-slate-100 px-3 py-3 font-medium text-slate-900">
                      {formatLogDate(entry.timestamp)}
                    </td>
                    <td className="border-b border-slate-100 px-3 py-3 text-slate-700">{entry.user || '-'}</td>
                    <td className="border-b border-slate-100 px-3 py-3 text-slate-900">{entry.action || '-'}</td>
                    <td className="border-b border-slate-100 px-3 py-3">
                      <span
                        className={`rounded-full px-2 py-1 text-xs font-semibold uppercase ${
                          entry.status === 'succeeded' || entry.status === 'created'
                            ? 'bg-emerald-100 text-emerald-800'
                            : entry.status === 'failed'
                              ? 'bg-red-100 text-red-800'
                              : 'bg-cyan-100 text-cyan-800'
                        }`}
                      >
                        {entry.status || '-'}
                      </span>
                    </td>
                    <td className="border-b border-slate-100 px-3 py-3 text-slate-700">{String(target)}</td>
                    <td className="max-w-md border-b border-slate-100 px-3 py-3 text-slate-700">
                      <span className="line-clamp-2">{entry.message || '-'}</span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </section>
    );
  }

  function notificationSeverityClass(notification: AppNotification) {
    if (notification.severity === 'critical') {
      return 'border-red-200 bg-red-50 text-red-800';
    }
    if (notification.severity === 'warning') {
      return 'border-amber-200 bg-amber-50 text-amber-800';
    }
    return 'border-cyan-200 bg-cyan-50 text-cyan-800';
  }

  function updateResourceThreshold(metric: ResourceAlertMetric, level: 'warning' | 'critical', value: string) {
    const nextValue = Math.max(1, Math.min(100, Number(value || 0)));
    setNotificationSettings((current) => ({
      ...current,
      resourceAlerts: {
        ...current.resourceAlerts,
        [metric]: {
          ...current.resourceAlerts[metric],
          [level]: nextValue,
        },
      },
    }));
  }

  const latestUnreadNotification = notifications.find((item) => item.status !== 'read');
  const shellCloud = activeTab === 'resourceDetail' && resourceDetailTarget ? cloudForResource(resourceDetailTarget) : activeCloud;
  const resourceDetailCloud = resourceDetailTarget ? cloudForResource(resourceDetailTarget) : activeCloud;
  const resourceDetailInventory = resourceDetailCloud === 'gcp'
    ? gcpInventory
    : resourceDetailCloud === 'aws'
      ? awsInventory
      : resourceDetailCloud === 'azure'
        ? azureInventory
        : ociAllResources;
  const shellConnectorName = shellCloud === 'oci'
    ? selectedOciConnector?.name || 'OCI environment'
    : shellCloud === 'aws'
      ? selectedAwsConnector?.name || 'AWS environment'
      : shellCloud === 'azure'
        ? selectedAzureConnector?.name || 'Azure environment'
        : shellCloud === 'gcp'
          ? selectedGcpConnector?.name || 'GCP environment'
        : selectedConnector ? `${selectedConnector.name} cluster` : 'PVE environment';
