    const stoppedOrIdleDatabases = databases
      .filter((row) => ['stopped', 'stopping'].includes(String(row.status || '').toLowerCase()))
      .map((row) => {
        const estimatedMonthlyCost = estimateAwsRdsStorageMonthlyCost(row);
        return {
          ...row,
          recommendation: 'Review stopped RDS database',
          impact: 'Database storage cost continues',
          reason: `${sizeGbFor(row) || '-'} GB allocated storage remains billable while the database is stopped.`,
          estimatedMonthlyCost,
          monthlyEstimate: formatMonthlyCost(estimatedMonthlyCost),
        } as ResourceRecord;
      });

