    const allResources = scoped(azureInventory?.allResources);
    const approvedRegionSet = new Set(
      (selectedAzureConnector?.azureApprovedRegions || '')
        .split(',')
        .map((region) => region.trim().toLowerCase())
        .filter(Boolean),
    );
    const vmById = new Map(virtualMachines.map((vm) => [String(vm.id || '').toLowerCase(), vm]));

    const stoppedVmsWithDisks = virtualMachines
